    /** Где сейчас закреплена панель: слева/справа (вертикально) или сверху/снизу (горизонтально). */
    private enum SidebarPosition { LEFT, RIGHT, TOP, BOTTOM;
        boolean isHorizontal() { return this == TOP || this == BOTTOM; }
        String toBorderConstraint() {
            return switch (this) {
                case LEFT -> BorderLayout.WEST;
                case RIGHT -> BorderLayout.EAST;
                case TOP -> BorderLayout.NORTH;
                case BOTTOM -> BorderLayout.SOUTH;
            };
        }
        static SidebarPosition fromSettings(String raw) {
            try { return SidebarPosition.valueOf(raw == null ? "LEFT" : raw.trim().toUpperCase(java.util.Locale.ROOT)); }
            catch (IllegalArgumentException ex) { return LEFT; }
        }
    }
