        // Set defaults for dialogs, tooltips, popups and file choosers
        putUiColor("OptionPane.background", WINDOW_BG);
        putUiColor("OptionPane.messageForeground", TEXT_PRIMARY);
        putUiColor("ToolTip.background", new Color(28, 32, 38, 220));
        putUiColor("ToolTip.foreground", TEXT_PRIMARY);
