    private BufferedImage configuredMetroWallpaper() {
        String configured = settings.wallpaperPath();
        String cacheKey = configured == null ? "" : configured;
        if (java.util.Objects.equals(cacheKey, metroWallpaperCacheKey)) {
            return metroWallpaperCache;
        }
        BufferedImage loaded = null;
        if (configured != null && !configured.isBlank()) {
            try {
                Path path = Path.of(configured);
                if (Files.isRegularFile(path)) loaded = javax.imageio.ImageIO.read(path.toFile());
            } catch (IOException | RuntimeException ignored) {
            }
        }
        if (loaded == null) {
            loaded = LauncherAssets.readImage(settings.gameDirectory(),
                    "wallpaper.png", "default-wallpaper.png", "background.png");
        }
        metroWallpaperCacheKey = cacheKey;
        metroWallpaperCache = loaded;
        return loaded;
    }

    private static void paintImageCover(Graphics2D g2, BufferedImage image, int width, int height) {
        if (image == null || width <= 0 || height <= 0) return;
        double scale = Math.max(width / (double) image.getWidth(), height / (double) image.getHeight());
        int drawW = Math.max(1, (int) Math.ceil(image.getWidth() * scale));
        int drawH = Math.max(1, (int) Math.ceil(image.getHeight() * scale));
        int x = (width - drawW) / 2;
        int y = (height - drawH) / 2;
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.drawImage(image, x, y, drawW, drawH, null);
    }

    private JComponent buildMetroTileCanvas() {
        JPanel canvas = transparentPanel(null);
        metroTileCanvas = canvas;
        canvas.setOpaque(false);
        canvas.setPreferredSize(new Dimension(1280, 760));
        populateMetroTileCanvas(canvas);
        JScrollPane scroll = new JScrollPane(canvas);
        scroll.setOpaque(false);
        scroll.getViewport().setOpaque(false);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        styleScrollBar(scroll.getVerticalScrollBar());
        styleScrollBar(scroll.getHorizontalScrollBar());
        installSmoothMetroScrolling(scroll);
        scroll.addMouseWheelListener(e -> {
            JScrollBar vertical = scroll.getVerticalScrollBar();
            JScrollBar horizontal = scroll.getHorizontalScrollBar();
            boolean verticalUnavailable = vertical.getMaximum() <= vertical.getVisibleAmount();
            JScrollBar bar = e.isShiftDown() || verticalUnavailable
                    ? horizontal : vertical;
            smoothScrollBarTo(bar, bar.getValue() + e.getWheelRotation() * 96);
            e.consume();
        });
        return scroll;
    }

