    private void addMetroFavoriteTiles(JPanel canvas) {
        if (favoriteInstances.isEmpty()) {
            return;
        }
        int index = 0;
        int startY = 1;
        for (String id : favoriteInstances) {
            InstalledVersionEntry entry = new InstalledVersionEntry(id, detectInstallKindForProfile(id));
            String title = compactInstanceCardLabel(entry.kind(), id, displayLabelFor(entry.kind(), id));
            String subtitle = ui("Favorite version", "Избранная версия", "Version favorite", "Versione preferita", "お気に入りバージョン", "Versiune favorită", "收藏版本");
            Color color = metroFavoriteTileColor(entry.kind(), index);
            BufferedImage icon = instanceTileIcon(id, entry.kind(), 192);
            final String profileId = id;
            addMetroTile(canvas, metroTile(title, subtitle, color, "game", icon, () -> openMetroFavoriteConfig(profileId)),
                    8 + (index % 4), startY + (index / 4), 1, 1);
            index++;
        }
    }

    private Color metroFavoriteTileColor(InstallKind kind, int index) {
        if (kind == null) {
            kind = InstallKind.VANILLA;
        }
        return switch (kind) {
            case FABRIC -> new Color(0, 171, 169);
            case FORGE, FORGE_OPTIFINE -> new Color(196, 92, 38);
            case NEOFORGE -> new Color(112, 66, 190);
            case QUILT -> new Color(180, 0, 158);
            case OPTIFINE -> new Color(50, 120, 220);
            default -> switch (index % 4) {
                case 1 -> new Color(0, 120, 215);
                case 2 -> new Color(104, 33, 122);
                case 3 -> new Color(31, 31, 31);
                default -> new Color(50, 150, 75);
            };
        };
    }

    private BufferedImage instanceTileIcon(String instanceId, InstallKind kind, int size) {
        BufferedImage custom = instanceIconMap.get(instanceId);
        if (custom != null) {
            return custom;
        }
        return defaultInstanceIcon(kind, Math.max(64, size));
    }

    private static BufferedImage defaultInstanceIcon(InstallKind kind, int size) {
        InstallKind resolved = kind == null ? InstallKind.VANILLA : kind;
        Color base = switch (resolved) {
            case FABRIC -> new Color(0, 171, 169);
            case FORGE, FORGE_OPTIFINE -> new Color(196, 92, 38);
            case NEOFORGE -> new Color(112, 66, 190);
            case QUILT -> new Color(180, 0, 158);
            case OPTIFINE -> new Color(50, 120, 220);
            default -> new Color(50, 150, 75);
        };
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = image.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int arc = Math.max(14, size / 7);
        g2.setPaint(new GradientPaint(0, 0, brighten(base, 26), size, size, base.darker()));
        g2.fillRoundRect(0, 0, size, size, arc, arc);
        g2.setColor(new Color(255, 255, 255, 38));
        g2.setStroke(new BasicStroke(Math.max(2f, size / 42f)));
        g2.drawRoundRect(2, 2, Math.max(1, size - 5), Math.max(1, size - 5), arc, arc);

        int cube = Math.round(size * 0.45f);
        int x = (size - cube) / 2;
        int y = Math.round(size * 0.25f);
        int m = Math.max(6, cube / 4);
        g2.setColor(new Color(255, 255, 255, 210));
        g2.setStroke(new BasicStroke(Math.max(3f, size / 34f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.drawRect(x + m, y + m, cube - m * 2, cube - m * 2);
        g2.drawLine(x + m, y + m, x + cube / 2, y + m / 2);
        g2.drawLine(x + cube - m, y + m, x + cube / 2, y + m / 2);
        g2.drawLine(x + cube / 2, y + m / 2, x + cube / 2, y + cube - m);

        String mark = switch (resolved) {
            case FABRIC -> "F";
            case FORGE, FORGE_OPTIFINE -> "G";
            case NEOFORGE -> "N";
            case QUILT -> "Q";
            case OPTIFINE -> "O";
            default -> "M";
        };
        Font font = new Font(Font.DIALOG, Font.BOLD, Math.max(18, size / 4));
        g2.setFont(font);
        FontMetrics fm = g2.getFontMetrics();
        int tx = (size - fm.stringWidth(mark)) / 2;
        int ty = Math.round(size * 0.78f) + (fm.getAscent() - fm.getDescent()) / 2;
        g2.setColor(new Color(0, 0, 0, 78));
        g2.drawString(mark, tx + 2, ty + 2);
        g2.setColor(Color.WHITE);
        g2.drawString(mark, tx, ty);
        g2.dispose();
        return image;
    }

    private static BufferedImage serverAdIcon(int size) {
        int s = Math.max(64, size);
        BufferedImage image = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = image.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setPaint(new GradientPaint(0, 0, new Color(74, 210, 112), s, s, new Color(24, 92, 58)));
        g2.fillRoundRect(0, 0, s, s, Math.max(14, s / 7), Math.max(14, s / 7));

        int towerW = Math.max(10, s / 10);
        int towerH = Math.round(s * 0.42f);
        int towerX = s / 2 - towerW / 2;
        int towerY = Math.round(s * 0.21f);
        g2.setColor(new Color(255, 255, 255, 218));
        g2.fillRoundRect(towerX, towerY, towerW, towerH, towerW, towerW);
        g2.fillOval(towerX - towerW, towerY - towerW / 2, towerW * 3, towerW * 3);

        g2.setStroke(new BasicStroke(Math.max(4f, s / 26f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        for (int i = 0; i < 3; i++) {
            int r = Math.round(s * (0.18f + i * 0.115f));
            g2.setColor(new Color(255, 255, 255, 190 - i * 36));
            g2.drawArc(s / 2 - r, towerY - r / 3, r * 2, r * 2, 32, 116);
            g2.drawArc(s / 2 - r, towerY - r / 3, r * 2, r * 2, 32 + 180, 116);
        }

        int playSize = Math.round(s * 0.22f);
        int cx = s / 2;
        int cy = Math.round(s * 0.74f);
        g2.setColor(new Color(0, 0, 0, 74));
        g2.fillOval(cx - playSize, cy - playSize, playSize * 2, playSize * 2);
        g2.setColor(Color.WHITE);
        g2.fillPolygon(
                new int[] {cx - playSize / 3, cx - playSize / 3, cx + playSize / 2},
                new int[] {cy - playSize / 2, cy + playSize / 2, cy},
                3);
        g2.dispose();
        return image;
    }

    private void openMetroFavoriteConfig(String profileId) {
        if (profileId == null || profileId.isBlank()) {
            return;
        }
        if (!installedVersionExists(profileId)) {
            JOptionPane.showMessageDialog(this,
                    nr("This favorite version is no longer installed.", "Эта избранная версия больше не установлена."),
                    t("dialog.noVersion"), JOptionPane.WARNING_MESSAGE);
            return;
        }
        InstalledVersionEntry entry = new InstalledVersionEntry(profileId, detectInstallKindForProfile(profileId));
        selectInstalledVersion(profileId);
        SwingUtilities.invokeLater(() -> showInstanceDetailsOverlay(entry));
    }

    private boolean installedVersionExists(String profileId) {
        for (int i = 0; i < installedVersionsModel.getSize(); i++) {
            if (profileId.equals(installedVersionsModel.getElementAt(i).id())) {
                return true;
            }
        }
        return false;
    }

    private void refreshMetroFavoriteTiles() {
        if (!isMetroUi() || metroTileCanvas == null) {
            return;
        }
        populateMetroTileCanvas(metroTileCanvas);
        animateMetroTilesReturnIn();
    }

    private void addMetroTile(JPanel parent, JComponent component, int x, int y, int w, int h) {
        if (component instanceof MetroPreviewTile tile) {
            int[] saved = metroSavedTileBounds(tile.metroIndex);
            if (saved != null) {
                x = saved[0];
                y = saved[1];
                w = saved[2];
                h = saved[3];
            }
        }
        component.putClientProperty("metro.tile.x", x);
        component.putClientProperty("metro.tile.y", y);
        component.putClientProperty("metro.tile.w", w);
        component.putClientProperty("metro.tile.h", h);
        component.putClientProperty("metro.tile.parent", parent);
        if (component instanceof MetroPreviewTile tile) {
            installMetroTileContextMenu(tile);
            installMetroTileDrag(tile);
        }
        parent.add(component);
        normalizeMetroTileGrid(parent, component);
        expandMetroCanvas(parent);
    }

