    private void showMetroTileBackgroundSettings() {
        if (metroTileButtons.isEmpty()) {
            return;
        }
        String[] names = metroTileButtons.stream()
                .map(tile -> tile.getText() == null || tile.getText().isBlank()
                        ? ui("Tile", "Плитка", "Tuile", "Riquadro", "タイル", "Dală", "磁贴")
                        : tile.getText())
                .toArray(String[]::new);
        JComboBox<String> tileChoice = new JComboBox<>(names);
        Object[] message = {
                ui("Choose a tile", "Выберите плитку", "Choisissez une tuile", "Scegli un riquadro",
                        "タイルを選択", "Alegeți dala", "选择磁贴"),
                tileChoice
        };
        String[] actions = {
                ui("Choose image…", "Выбрать изображение…", "Choisir une image…", "Scegli immagine…",
                        "画像を選択…", "Alege imaginea…", "选择图片…"),
                ui("Default", "Стандартный", "Par défaut", "Predefinito", "標準", "Implicit", "默认"),
                t("button.cancel")
        };
        int choice = JOptionPane.showOptionDialog(this, message,
                ui("Tile backgrounds", "Фоны плиток", "Arrière-plans des tuiles", "Sfondi riquadri",
                        "タイル背景", "Fundaluri dale", "磁贴背景"),
                JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, actions, actions[0]);
        if (choice < 0 || choice == 2) return;
        MetroPreviewTile tile = metroTileButtons.get(tileChoice.getSelectedIndex());
        if (choice == 1) {
            tile.setBackgroundImage(null);
            return;
        }
        JFileChooser chooser = new JFileChooser();
        chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
                nr("Images", "Изображения"), "png", "jpg", "jpeg", "gif"));
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            try {
                tile.setBackgroundImage(javax.imageio.ImageIO.read(chooser.getSelectedFile()));
            } catch (IOException ex) {
                JOptionPane.showMessageDialog(this, ex.getMessage(), t("dialog.error"), JOptionPane.ERROR_MESSAGE);
            }
        }
    }

