    private void installMetroTileDrag(MetroPreviewTile tile) {
        final Point[] press = new Point[1];
        final Point[] start = new Point[1];
        final boolean[] dragged = {false};
        final Point[] previewCell = new Point[1];
        final Point[] pendingCell = new Point[1];
        final long[] pendingCellSince = new long[1];
        final Timer edgeScrollTimer = new Timer(16, null);
        edgeScrollTimer.addActionListener(event -> autoScrollMetroTileDrag(tile));
        tile.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    Object parentObj = tile.getClientProperty("metro.tile.parent");
                    if (!(parentObj instanceof JPanel parent)) {
                        return;
                    }
                    parent.setComponentZOrder(tile, 0);
                    parent.repaint(tile.getBounds());
                    press[0] = SwingUtilities.convertPoint(tile, e.getPoint(), parent);
                    start[0] = tile.getLocation();
                    dragged[0] = false;
                    previewCell[0] = new Point(intProp(tile, "metro.tile.x", 0), intProp(tile, "metro.tile.y", 0));
                    pendingCell[0] = new Point(previewCell[0]);
                    pendingCellSince[0] = System.currentTimeMillis();
                    tile.putClientProperty("metro.dragging", Boolean.FALSE);
                    edgeScrollTimer.start();
                }
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (press[0] == null || start[0] == null) {
                    return;
                }
                if (dragged[0]) {
                    snapMetroTileToGrid(tile);
                    tile.putClientProperty("metro.suppressClick", Boolean.TRUE);
                }
                press[0] = null;
                start[0] = null;
                previewCell[0] = null;
                pendingCell[0] = null;
                pendingCellSince[0] = 0L;
                edgeScrollTimer.stop();
                SwingUtilities.invokeLater(() -> tile.putClientProperty("metro.dragging", Boolean.FALSE));
            }
        });
        tile.addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                Object parentObj = tile.getClientProperty("metro.tile.parent");
                if (press[0] == null || start[0] == null || !(parentObj instanceof JPanel parent)) {
                    return;
                }
                Point now = SwingUtilities.convertPoint(tile, e.getPoint(), parent);
                int nx = Math.max(0, start[0].x + now.x - press[0].x);
                int ny = Math.max(0, start[0].y + now.y - press[0].y);
                int cellX = Math.max(0, Math.round(nx / (float) metroTileStepX()));
                int cellY = Math.max(0, Math.round(ny / (float) metroTileStepY()));
                long nowMillis = System.currentTimeMillis();
                if (pendingCell[0] == null || pendingCell[0].x != cellX || pendingCell[0].y != cellY) {
                    pendingCell[0] = new Point(cellX, cellY);
                    pendingCellSince[0] = nowMillis;
                }
                boolean hoveredLongEnough = nowMillis - pendingCellSince[0] >= METRO_TILE_REORDER_HOVER_DELAY_MS;
                if (hoveredLongEnough && (previewCell[0] == null || previewCell[0].x != cellX || previewCell[0].y != cellY)) {
                    previewCell[0] = new Point(cellX, cellY);
                    tile.putClientProperty("metro.tile.x", cellX);
                    tile.putClientProperty("metro.tile.y", cellY);
                    normalizeMetroTileGrid(parent, tile);
                    parent.repaint();
                }
                Rectangle oldBounds = tile.getBounds();
                tile.setLocation(nx, ny);
                dragged[0] = true;
                tile.putClientProperty("metro.dragging", Boolean.TRUE);
                expandMetroCanvasIfNeeded(parent, tile.getBounds());
                Rectangle dirty = oldBounds.union(tile.getBounds());
                dirty.grow(18, 18);
                parent.repaint(dirty);
            }
        });
    }

    private void autoScrollMetroTileDrag(MetroPreviewTile tile) {
        if (!Boolean.TRUE.equals(tile.getClientProperty("metro.dragging"))
                || !(tile.getParent() instanceof JPanel canvas)) {
            return;
        }
        JScrollPane scroll = (JScrollPane) SwingUtilities.getAncestorOfClass(JScrollPane.class, canvas);
        if (scroll == null || !scroll.isShowing()) return;
        Point pointer;
        try {
            pointer = MouseInfo.getPointerInfo().getLocation();
            SwingUtilities.convertPointFromScreen(pointer, scroll.getViewport());
        } catch (RuntimeException ex) {
            return;
        }
        int margin = 72;
        int dx = edgeScrollSpeed(pointer.x, scroll.getViewport().getWidth(), margin);
        int dy = edgeScrollSpeed(pointer.y, scroll.getViewport().getHeight(), margin);
        if (dx == 0 && dy == 0) return;

        Dimension preferred = canvas.getPreferredSize();
        if (dx > 0 || dy > 0) {
            canvas.setPreferredSize(new Dimension(
                    preferred.width + (dx > 0 ? Math.max(20, dx) : 0),
                    preferred.height + (dy > 0 ? Math.max(20, dy) : 0)));
            canvas.revalidate();
        }
        JScrollBar horizontal = scroll.getHorizontalScrollBar();
        JScrollBar vertical = scroll.getVerticalScrollBar();
        horizontal.setValue(horizontal.getValue() + dx);
        vertical.setValue(vertical.getValue() + dy);
    }

    private static int edgeScrollSpeed(int pointer, int extent, int margin) {
        if (pointer < margin) {
            double strength = 1.0 - Math.max(0, pointer) / (double) margin;
            return -(int) Math.round(4 + 18 * strength * strength);
        }
        if (pointer > extent - margin) {
            double strength = 1.0 - Math.max(0, extent - pointer) / (double) margin;
            return (int) Math.round(4 + 18 * strength * strength);
        }
        return 0;
    }

    private void snapMetroTileToGrid(JComponent tile) {
        int x = Math.max(0, Math.round(tile.getX() / (float) metroTileStepX()));
        int y = Math.max(0, Math.round(tile.getY() / (float) metroTileStepY()));
        updateMetroTileGrid(tile, x, y, intProp(tile, "metro.tile.w", 1), intProp(tile, "metro.tile.h", 1));
    }

    private void resizeMetroTile(JComponent tile, int w, int h) {
        updateMetroTileGrid(tile, intProp(tile, "metro.tile.x", 0), intProp(tile, "metro.tile.y", 0), w, h);
    }

    private void moveMetroTile(JComponent tile, int dx, int dy) {
        int w = intProp(tile, "metro.tile.w", 1);
        int h = intProp(tile, "metro.tile.h", 1);
        int x = Math.max(0, Math.min(7, intProp(tile, "metro.tile.x", 0) + dx));
        int y = Math.max(0, intProp(tile, "metro.tile.y", 0) + dy);
        updateMetroTileGrid(tile, x, y, w, h);
    }

    private void updateMetroTileGrid(JComponent tile, int x, int y, int w, int h) {
        Object parentObj = tile.getClientProperty("metro.tile.parent");
        if (!(parentObj instanceof JPanel parent)) {
            return;
        }
        int boundedW = Math.max(1, Math.min(4, w));
        int boundedH = Math.max(1, Math.min(2, h));
        int boundedX = Math.max(0, x);
        int boundedY = Math.max(0, y);
        tile.putClientProperty("metro.tile.x", boundedX);
        tile.putClientProperty("metro.tile.y", boundedY);
        tile.putClientProperty("metro.tile.w", boundedW);
        tile.putClientProperty("metro.tile.h", boundedH);
        normalizeMetroTileGrid(parent, tile);
        expandMetroCanvas(parent);
        parent.revalidate();
        parent.repaint();
        animateMetroTilesSettle(parent);
        saveMetroTileLayout(parent);
    }

    private int[] metroSavedTileBounds(int tileIndex) {
        String layout = settings.metroTileLayout();
        if (layout.isBlank()) {
            return null;
        }
        for (String entry : layout.split(";")) {
            String[] parts = entry.trim().split(",");
            if (parts.length != 5) {
                continue;
            }
            try {
                if (Integer.parseInt(parts[0].trim()) == tileIndex) {
                    int x = Math.max(0, Integer.parseInt(parts[1].trim()));
                    int y = Math.max(0, Integer.parseInt(parts[2].trim()));
                    int w = Math.max(1, Math.min(4, Integer.parseInt(parts[3].trim())));
                    int h = Math.max(1, Math.min(2, Integer.parseInt(parts[4].trim())));
                    return new int[] {x, y, w, h};
                }
            } catch (NumberFormatException ignored) {
                // Ignore malformed legacy/user-edited entries.
            }
        }
        return null;
    }

    private void saveMetroTileLayout(JPanel parent) {
        java.util.List<MetroPreviewTile> tiles = new ArrayList<>();
        for (Component child : parent.getComponents()) {
            if (child instanceof MetroPreviewTile tile) {
                tiles.add(tile);
            }
        }
        tiles.sort(java.util.Comparator.comparingInt(tile -> tile.metroIndex));
        StringBuilder out = new StringBuilder();
        for (MetroPreviewTile tile : tiles) {
            if (!out.isEmpty()) {
                out.append(';');
            }
            out.append(tile.metroIndex).append(',')
                    .append(intProp(tile, "metro.tile.x", 0)).append(',')
                    .append(intProp(tile, "metro.tile.y", 0)).append(',')
                    .append(intProp(tile, "metro.tile.w", 1)).append(',')
                    .append(intProp(tile, "metro.tile.h", 1));
        }
        settings.setMetroTileLayout(out.toString());
        try {
            settings.save();
        } catch (LauncherException ex) {
            log(tf("log.settingsSaveFailed", ex.getMessage()));
        }
    }

    private void normalizeMetroTileGrid(JPanel parent, JComponent priorityTile) {
        java.util.List<JComponent> tiles = new ArrayList<>();
        for (Component child : parent.getComponents()) {
            if (child instanceof JComponent jc && jc.getClientProperty("metro.tile.x") instanceof Number) {
                tiles.add(jc);
            }
        }
        tiles.sort((a, b) -> {
            if (a == priorityTile) return -1;
            if (b == priorityTile) return 1;
            int ay = intProp(a, "metro.tile.y", 0);
            int by = intProp(b, "metro.tile.y", 0);
            if (ay != by) return Integer.compare(ay, by);
            return Integer.compare(intProp(a, "metro.tile.x", 0), intProp(b, "metro.tile.x", 0));
        });

        java.util.List<Rectangle> occupied = new ArrayList<>();
        for (JComponent current : tiles) {
            int w = Math.max(1, Math.min(4, intProp(current, "metro.tile.w", 1)));
            int h = Math.max(1, Math.min(2, intProp(current, "metro.tile.h", 1)));
            int wantedX = Math.max(0, intProp(current, "metro.tile.x", 0));
            int wantedY = Math.max(0, intProp(current, "metro.tile.y", 0));
            Point slot = nearestFreeMetroSlot(occupied, wantedX, wantedY, w, h, tiles.size());
            current.putClientProperty("metro.tile.x", slot.x);
            current.putClientProperty("metro.tile.y", slot.y);
            current.putClientProperty("metro.tile.w", w);
            current.putClientProperty("metro.tile.h", h);
            occupied.add(new Rectangle(slot.x, slot.y, w, h));
            Rectangle target = metroTileBounds(current);
            boolean dragSource = current == priorityTile && Boolean.TRUE.equals(current.getClientProperty("metro.dragging"));
            if (dragSource || current.getWidth() <= 0 || current.getHeight() <= 0) {
                stopMetroTileBoundsAnimation(current);
                current.setBounds(target);
            } else {
                animateMetroTileBounds(current, target);
            }
        }
    }

    private Point nearestFreeMetroSlot(java.util.List<Rectangle> occupied, int wantedX, int wantedY, int w, int h, int tileCount) {
        Point best = new Point(Math.max(0, wantedX), Math.max(0, wantedY));
        int bestScore = Integer.MAX_VALUE;
        int maxColumns = Math.max(16, wantedX + tileCount * 4 + 8);
        int maxRows = Math.max(wantedY + tileCount * 2 + 8, 24);
        for (int x = 0; x <= maxColumns; x++) {
            for (int y = 0; y <= maxRows; y++) {
                Rectangle candidate = new Rectangle(x, y, w, h);
                if (metroSlotOccupied(candidate, occupied)) {
                    continue;
                }
                int dx = x - wantedX;
                int dy = y - wantedY;
                int score = dx * dx * 10 + dy * dy * 18 + x;
                if (score < bestScore) {
                    bestScore = score;
                    best = new Point(x, y);
                }
            }
        }
        return best;
    }

    private boolean metroSlotOccupied(Rectangle candidate, java.util.List<Rectangle> occupied) {
        for (Rectangle used : occupied) {
            if (candidate.intersects(used)) {
                return true;
            }
        }
        return false;
    }

    private void animateMetroTilesSettle(JPanel parent) {
        for (Component child : parent.getComponents()) {
            if (child instanceof MetroPreviewTile tile) {
                tile.setAppearProgress(1.0);
            }
        }
    }

    private void applyMetroTileBounds(JComponent tile) {
        tile.setBounds(metroTileBounds(tile));
    }

    private Rectangle metroTileBounds(JComponent tile) {
        int x = intProp(tile, "metro.tile.x", 0);
        int y = intProp(tile, "metro.tile.y", 0);
        int w = intProp(tile, "metro.tile.w", 1);
        int h = intProp(tile, "metro.tile.h", 1);
        return new Rectangle(8 + x * metroTileStepX(), 8 + y * metroTileStepY(), metroTileWidth(w), metroTileHeight(h));
    }

    private void animateMetroTileBounds(JComponent tile, Rectangle target) {
        if (!LinuxUiSupport.animationsEnabled()) {
            stopMetroTileBoundsAnimation(tile);
            tile.setBounds(target);
            tile.repaint();
            return;
        }
        Rectangle start = tile.getBounds();
        if (start.equals(target)) {
            return;
        }
        stopMetroTileBoundsAnimation(tile);
        final long startedAt = System.currentTimeMillis();
        final int durationMs = 220;
        Timer timer = new Timer(16, null);
        timer.addActionListener(e -> {
            float t = Math.min(1f, (System.currentTimeMillis() - startedAt) / (float) durationMs);
            float eased = smoothStep(t);
            Rectangle old = tile.getBounds();
            int x = Math.round(start.x + (target.x - start.x) * eased);
            int y = Math.round(start.y + (target.y - start.y) * eased);
            int w = Math.round(start.width + (target.width - start.width) * eased);
            int h = Math.round(start.height + (target.height - start.height) * eased);
            tile.setBounds(x, y, w, h);
            if (tile.getParent() instanceof JComponent parent) {
                Rectangle dirty = old.union(tile.getBounds());
                dirty.grow(18, 18);
                parent.repaint(dirty);
            } else {
                tile.repaint();
            }
            if (t >= 1f) {
                timer.stop();
                tile.putClientProperty("metro.boundsAnimation", null);
                tile.setBounds(target);
            }
        });
        tile.putClientProperty("metro.boundsAnimation", timer);
        timer.start();
    }

    private void stopMetroTileBoundsAnimation(JComponent tile) {
        Object running = tile.getClientProperty("metro.boundsAnimation");
        if (running instanceof Timer timer && timer.isRunning()) {
            timer.stop();
        }
        tile.putClientProperty("metro.boundsAnimation", null);
    }

    private void expandMetroCanvas(JPanel parent) {
        int maxX = 0;
        int maxY = 0;
        for (Component child : parent.getComponents()) {
            Rectangle b = child.getBounds();
            maxX = Math.max(maxX, b.x + b.width + 32);
            maxY = Math.max(maxY, b.y + b.height + 32);
        }
        parent.setPreferredSize(new Dimension(Math.max(1180, maxX), Math.max(430, maxY)));
        parent.revalidate();
    }

    private void expandMetroCanvasIfNeeded(JPanel parent, Rectangle changedBounds) {
        Dimension preferred = parent.getPreferredSize();
        int neededW = Math.max(1180, changedBounds.x + changedBounds.width + 32);
        int neededH = Math.max(430, changedBounds.y + changedBounds.height + 32);
        if (neededW > preferred.width || neededH > preferred.height) {
            parent.setPreferredSize(new Dimension(Math.max(preferred.width, neededW), Math.max(preferred.height, neededH)));
            parent.revalidate();
        }
    }

    private void installSmoothMetroScrolling(JScrollPane scroll) {
        scroll.getHorizontalScrollBar().setUnitIncrement(32);
        scroll.getVerticalScrollBar().setUnitIncrement(32);
    }

    private void setMetroHorizontalScrolling(Component component, boolean enabled) {
        if (component instanceof JScrollPane scroll) {
            Object active = scroll.getClientProperty("msc.snapHorizontalScrolling");
            if (enabled && !Boolean.TRUE.equals(active)) {
                scroll.putClientProperty("msc.originalHorizontalPolicy",
                        scroll.getHorizontalScrollBarPolicy());
                scroll.putClientProperty("msc.snapHorizontalScrolling", Boolean.TRUE);
                scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
                installSmoothMetroScrolling(scroll);
                if (!Boolean.TRUE.equals(scroll.getClientProperty("msc.horizontalWheelInstalled"))) {
                    scroll.putClientProperty("msc.horizontalWheelInstalled", Boolean.TRUE);
                    scroll.addMouseWheelListener(event -> {
                        if (!Boolean.TRUE.equals(scroll.getClientProperty(
                                "msc.snapHorizontalScrolling"))) {
                            return;
                        }
                        JScrollBar horizontal = scroll.getHorizontalScrollBar();
                        JScrollBar vertical = scroll.getVerticalScrollBar();
                        boolean canScrollHorizontally = horizontal.getMaximum()
                                > horizontal.getVisibleAmount();
                        boolean canScrollVertically = vertical.getMaximum()
                                > vertical.getVisibleAmount();
                        if (canScrollHorizontally
                                && (event.isShiftDown() || !canScrollVertically)) {
                            smoothScrollBarTo(horizontal, horizontal.getValue()
                                    + event.getWheelRotation() * 72);
                            event.consume();
                        }
                    });
                }
            } else if (!enabled && Boolean.TRUE.equals(active)) {
                Object original = scroll.getClientProperty("msc.originalHorizontalPolicy");
                if (original instanceof Number policy) {
                    scroll.setHorizontalScrollBarPolicy(policy.intValue());
                }
                scroll.putClientProperty("msc.snapHorizontalScrolling", Boolean.FALSE);
            }
        }
        if (component instanceof Container container) {
            for (Component child : container.getComponents()) {
                setMetroHorizontalScrolling(child, enabled);
            }
        }
    }

    private void smoothScrollBarTo(JScrollBar bar, int requestedValue) {
        Object pendingTarget = bar.getClientProperty("msc.smoothScrollTarget");
        if (pendingTarget instanceof Number number) {
            requestedValue = number.intValue() + (requestedValue - bar.getValue());
        }
        int target = Math.max(bar.getMinimum(),
                Math.min(requestedValue, bar.getMaximum() - bar.getVisibleAmount()));
        int start = bar.getValue();
        if (!LinuxUiSupport.animationsEnabled() || start == target) {
            bar.setValue(target);
            return;
        }
        Object running = bar.getClientProperty("msc.smoothScroll");
        if (running instanceof Timer timer) {
            timer.stop();
        }
        long startedAt = System.currentTimeMillis();
        Timer timer = new Timer(15, null);
        timer.addActionListener(event -> {
            float progress = Math.min(1f, (System.currentTimeMillis() - startedAt) / 280f);
            bar.setValue(Math.round(start + (target - start) * smoothStep(progress)));
            if (progress >= 1f) {
                timer.stop();
                bar.putClientProperty("msc.smoothScroll", null);
                bar.putClientProperty("msc.smoothScrollTarget", null);
            }
        });
        bar.putClientProperty("msc.smoothScroll", timer);
        bar.putClientProperty("msc.smoothScrollTarget", target);
        timer.start();
    }

    private int metroTileStepX() {
        return 144;
    }

    private int metroTileStepY() {
        return 134;
    }

    private int metroTileWidth(int w) {
        return 128 * Math.max(1, w) + 16 * (Math.max(1, w) - 1);
    }

    private int metroTileHeight(int h) {
        return 118 * Math.max(1, h) + 16 * (Math.max(1, h) - 1);
    }

    private int intProp(JComponent component, String key, int fallback) {
        Object value = component.getClientProperty(key);
        return value instanceof Number n ? n.intValue() : fallback;
    }

    private void animateMetroTileOpen(Component source, String previewKind, Color color, Runnable action) {
        if (isMetroUi() && metroSnapWorkspace != null
                && metroSnapWorkspace.isWaitingForSecondScreen()) {
            action.run();
            return;
        }
        if (!isMetroUi() || !metroTransitionsEnabled() || source == null || !source.isShowing()) {
            action.run();
            return;
        }
        JLayeredPane layers = getLayeredPane();
        Rectangle start = SwingUtilities.convertRectangle(source.getParent(), source.getBounds(), layers);
        BufferedImage transitionLogo = source instanceof MetroPreviewTile tile && tile.logoOverride != null
                ? tile.logoOverride
                : metroTileLogoFor(previewKind);
        MetroTileOpenTransition transition = new MetroTileOpenTransition(start, color, transitionLogo);
        transition.setBounds(0, 0, layers.getWidth(), layers.getHeight());
        layers.add(transition, JLayeredPane.POPUP_LAYER);
        layers.revalidate();
        layers.repaint();

        source.setVisible(false);
        final boolean[] targetShown = {false};
        runProgressAnimation(1600,
                progress -> {
                    transition.setProgress(progress.floatValue());
                    // Prepare the real screen behind the tile while the highlight
                    // masks the hand-off to the live destination.
                    if (!targetShown[0] && progress >= 0.78) {
                        targetShown[0] = true;
                        action.run();
                    }
                },
                () -> {
                    source.setVisible(true);
                    layers.remove(transition);
                    layers.revalidate();
                    layers.repaint();
                    if (!targetShown[0]) {
                        action.run();
                    }
                });
    }

    private JPanel metroBaseTile(Color color) {
        JPanel panel = new JPanel();
        panel.setOpaque(true);
        panel.setBackground(color);
        panel.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        return panel;
    }

    private BufferedImage metroTileLogoFor(String previewKind) {
        String logo = metroTileLogoFile(previewKind);
        if (logo == null) {
            return null;
        }
        String key = previewKind + ":" + logo;
        BufferedImage cached = metroTileLogoCache.get(key);
        if (cached != null) {
            return cached;
        }
        BufferedImage image = LauncherAssets.readImage(settings.gameDirectory(),
                "pltika/" + previewKind + ".png",
                "pltika/plit_" + previewKind + ".png",
                "pltika/" + logo,
                "plit/" + previewKind + ".png",
                "plit/plit_" + previewKind + ".png",
                "plit/" + logo,
                "nav/" + logo,
                logo);
        if (image != null) {
            metroTileLogoCache.put(key, image);
        }
        return image;
    }

    private BufferedImage metroTargetSnapshotFor(String previewKind) {
        String screen = switch (previewKind) {
            case "mods" -> SCREEN_MODS;
            case "skins" -> SCREEN_SKINS;
            case "library" -> SCREEN_LIBRARY;
            case "backups" -> SCREEN_BACKUPS;
            case "settings" -> "metro-settings-preview";
            default -> null;
        };
        if (screen == null) {
            return null;
        }
        BufferedImage cached = metroTargetSnapshotCache.get(screen);
        if (cached != null) {
            return cached;
        }
        BufferedImage snapshot = snapshotScreenCard(screen, 760, 440);
        if (snapshot != null) {
            metroTargetSnapshotCache.put(screen, snapshot);
        }
        return snapshot;
    }

    private void preloadMetroPreviewSnapshots() {
        for (String kind : List.of("mods", "skins", "library", "settings")) {
            metroTileLogoFor(kind);
        }
        if (metroTilesScreen != null) {
            metroTilesScreen.repaint();
        }
    }

    private void animateMetroTilesIn() {
        if (!isMetroUi() || metroTileButtons.isEmpty() || metroTilesIntroPlayed) {
            return;
        }
        if (!metroTransitionsEnabled()) {
            metroTilesIntroPlayed = true;
            for (MetroPreviewTile tile : metroTileButtons) {
                tile.setAppearProgress(1.0);
                tile.setAppearFromRight(false);
            }
            return;
        }
        if (metroTilesScreen != null && !metroTilesScreen.isShowing()) {
            return;
        }
        metroTilesIntroPlayed = true;
        for (MetroPreviewTile tile : metroTileButtons) {
            tile.setAppearProgress(0.0);
        }
        runProgressAnimation(820, progress -> {
            for (MetroPreviewTile tile : metroTileButtons) {
                double local = Math.max(0.0, Math.min(1.0, (progress - tile.metroDelay()) / 0.72));
                tile.setAppearProgress(local);
            }
        }, () -> {
            for (MetroPreviewTile tile : metroTileButtons) {
                tile.setAppearProgress(1.0);
            }
        });
    }

    private void animateMetroTilesReturnIn() {
        if (!isMetroUi() || metroTileButtons.isEmpty()) {
            return;
        }
        if (!metroTransitionsEnabled()) {
            for (MetroPreviewTile tile : metroTileButtons) {
                tile.setAppearProgress(1.0);
                tile.setAppearFromRight(false);
            }
            return;
        }
        for (MetroPreviewTile tile : metroTileButtons) {
            tile.setAppearFromRight(true);
            tile.setAppearProgress(0.0);
        }
        runProgressAnimation(760, progress -> {
            for (MetroPreviewTile tile : metroTileButtons) {
                double local = Math.max(0.0, Math.min(1.0, (progress - tile.metroDelay()) / 0.68));
                tile.setAppearProgress(local);
            }
        }, () -> {
            for (MetroPreviewTile tile : metroTileButtons) {
                tile.setAppearProgress(1.0);
                tile.setAppearFromRight(false);
            }
        });
    }

    private String metroTileLogoFile(String previewKind) {
        return switch (previewKind) {
            case "mods" -> "nav_mods.png";
            case "skins" -> "nav_skins.png";
            case "library" -> "nav_library.png";
            case "backups" -> "nav_backups.png";
            case "settings" -> "nav_settings.png";
            case "folder" -> "nav_library.png";
            default -> null;
        };
    }

    private BufferedImage snapshotScreenCard(String screen, int width, int height) {
        JComponent target = "metro-settings-preview".equals(screen) ? metroParamsScreen : findScreenCard(screen);
        if (target == null) {
            return null;
        }
        Dimension oldSize = target.getSize();
        boolean wasDoubleBuffered = RepaintManager.currentManager(target).isDoubleBufferingEnabled();
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = image.createGraphics();
        try {
            target.setSize(width, height);
            target.doLayout();
            RepaintManager.currentManager(target).setDoubleBufferingEnabled(false);
            target.printAll(g2);
        } catch (RuntimeException ignored) {
            return null;
        } finally {
            RepaintManager.currentManager(target).setDoubleBufferingEnabled(wasDoubleBuffered);
            target.setSize(oldSize);
            g2.dispose();
        }
        return image;
    }

    private JComponent findScreenCard(String screen) {
        for (Component component : screenPanel.getComponents()) {
            if (component instanceof JComponent jc) {
                Object name = jc.getClientProperty("metro.screen");
                if (screen.equals(name)) {
                    return jc;
                }
            }
        }
        return null;
    }

    private static final class MetroPreviewTile extends JButton {
        private final String title;
        private final String subtitle;
        private final Color color;
        private final String previewKind;
        private final BufferedImage logoOverride;
        private final java.util.function.Function<String, BufferedImage> previewProvider;
        private BufferedImage backgroundImage;
        private int metroIndex;
        private double appearProgress = 1.0;
        private boolean appearFromRight;

        private MetroPreviewTile(String title, String subtitle, Color color, String previewKind,
                                 BufferedImage logoOverride,
                                 java.util.function.Function<String, BufferedImage> previewProvider) {
            this.title = title == null ? "" : title;
            this.subtitle = subtitle == null ? "" : subtitle;
            this.color = color;
            this.previewKind = previewKind == null ? "generic" : previewKind;
            this.logoOverride = logoOverride;
            this.previewProvider = previewProvider;
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
            setRolloverEnabled(true);
            setBorder(BorderFactory.createEmptyBorder());
            setToolTipText(this.title);
        }

        private void setMetroIndex(int metroIndex) {
            this.metroIndex = metroIndex;
        }

        private double metroDelay() {
            return Math.min(0.28, metroIndex * 0.055);
        }

        private void setAppearProgress(double appearProgress) {
            this.appearProgress = Math.max(0.0, Math.min(1.0, appearProgress));
            repaint();
        }

        private void setAppearFromRight(boolean appearFromRight) {
            this.appearFromRight = appearFromRight;
            repaint();
        }

        private void setBackgroundImage(BufferedImage backgroundImage) {
            this.backgroundImage = backgroundImage;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            double easedAppear = 1.0 - Math.pow(1.0 - appearProgress, 3.0);
            float alpha = (float) easedAppear;
            double scale = 0.88 + 0.12 * easedAppear;
            int offsetY = (int) Math.round((1.0 - easedAppear) * 22.0);
            int gridX = 0;
            Object xProp = getClientProperty("metro.tile.x");
            if (xProp instanceof Number n) {
                gridX = n.intValue();
            }
            double drift = 96.0 + gridX * 22.0;
            int offsetX = (int) Math.round((1.0 - easedAppear) * (appearFromRight ? drift : -drift));
            g2.setComposite(AlphaComposite.SrcOver.derive(alpha));
            g2.translate((getWidth() * (1.0 - scale)) / 2.0 + offsetX, (getHeight() * (1.0 - scale)) / 2.0 + offsetY);
            g2.scale(scale, scale);
            ButtonModel model = getModel();
            Color fill = model.isPressed() ? color.darker()
                    : model.isRollover() ? brighten(color, 24)
                    : color;
            g2.setColor(fill);
            g2.fillRect(0, 0, getWidth(), getHeight());
            if (backgroundImage != null) {
                paintMetroLogoImage(g2, new Rectangle(0, 0, getWidth(), getHeight()), backgroundImage, color);
            }
            BufferedImage image = backgroundImage != null ? null
                    : logoOverride != null ? logoOverride : previewProvider == null ? null : previewProvider.apply(previewKind);
            paintMetroLogoImage(g2, new Rectangle(0, 0, getWidth(), getHeight()), image, color);
            paintTileText(g2);
            if (model.isRollover() || model.isPressed()) {
                float strength = model.isPressed() ? 1.0f : 0.82f;
                g2.setComposite(AlphaComposite.SrcOver.derive(0.18f * strength));
                g2.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 230),
                        0, getHeight(), new Color(92, 210, 255, 80)));
                g2.fillRect(0, 0, getWidth(), getHeight());
                g2.setComposite(AlphaComposite.SrcOver.derive(0.38f * strength));
                g2.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 235),
                        0, Math.max(1, getHeight() / 2), new Color(255, 255, 255, 20)));
                g2.fillRect(2, 2, Math.max(0, getWidth() - 4), Math.max(4, getHeight() / 3));
                g2.setComposite(AlphaComposite.SrcOver.derive(0.88f));
                g2.setStroke(new BasicStroke(model.isPressed() ? 2.6f : 2f));
                g2.setPaint(new GradientPaint(0, 0, new Color(220, 250, 255),
                        getWidth(), getHeight(), new Color(65, 185, 255)));
                g2.drawRect(1, 1, Math.max(0, getWidth() - 3), Math.max(0, getHeight() - 3));
                g2.setComposite(AlphaComposite.SrcOver.derive(0.28f * strength));
                g2.setColor(new Color(130, 225, 255));
                g2.setStroke(new BasicStroke(5f));
                g2.drawRect(4, 4, Math.max(0, getWidth() - 9), Math.max(0, getHeight() - 9));
            }
            g2.dispose();
        }

        private void paintTileText(Graphics2D g2) {
            int pad = 12;
            int maxW = Math.max(20, getWidth() - pad * 2);
            int titleY = Math.max(26, getHeight() - 34);
            Font titleFont = getFont().deriveFont(Font.BOLD, getWidth() < 150 ? 12f : 15f);
            Font subtitleFont = getFont().deriveFont(Font.PLAIN, 11f);
            g2.setFont(titleFont);
            FontMetrics titleFm = g2.getFontMetrics();
            String visibleTitle = fitText(title, titleFm, maxW);
            g2.setColor(new Color(0, 0, 0, 120));
            g2.drawString(visibleTitle, pad + 1, titleY + 1);
            g2.setColor(Color.WHITE);
            g2.drawString(visibleTitle, pad, titleY);
            if (!subtitle.isBlank() && getHeight() >= 86) {
                g2.setFont(subtitleFont);
                FontMetrics subFm = g2.getFontMetrics();
                String visibleSubtitle = fitText(subtitle, subFm, maxW);
                int subY = titleY + subFm.getAscent() + 4;
                g2.setColor(new Color(0, 0, 0, 105));
                g2.drawString(visibleSubtitle, pad + 1, subY + 1);
                g2.setColor(new Color(255, 255, 255, 205));
                g2.drawString(visibleSubtitle, pad, subY);
            }
        }
    }

    private static final class MetroTileOpenTransition extends JComponent {
        private final Rectangle start;
        private final Color color;
        private final BufferedImage logoImage;
        private float progress;

        private MetroTileOpenTransition(Rectangle start, Color color, BufferedImage logoImage) {
            this.start = new Rectangle(start);
            this.color = color;
            this.logoImage = logoImage;
            setOpaque(false);
        }

        private void setProgress(float progress) {
            this.progress = Math.max(0f, Math.min(1f, progress));
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
            float zoom = smoothStep(Math.min(1f, progress / 0.88f));
            float fade = smoothStep(Math.max(0f, (progress - 0.88f) / 0.12f));
            float alpha = 1f - fade;
            Color accent = color == null ? new Color(50, 120, 220) : color;

            float screenAlpha = Math.max(0f, Math.min(1f, (0.12f + 0.68f * zoom) * alpha));
            g2.setComposite(AlphaComposite.SrcOver.derive(screenAlpha));
            g2.setPaint(new GradientPaint(0, 0,
                    new Color(Math.max(0, accent.getRed() - 58), Math.max(0, accent.getGreen() - 58), Math.max(0, accent.getBlue() - 58), 238),
                    getWidth(), getHeight(), new Color(8, 12, 20, 246)));
            g2.fillRect(0, 0, getWidth(), getHeight());

            Rectangle end = new Rectangle(-4, -4, getWidth() + 8, getHeight() + 8);
            Rectangle r = interpolate(start, end, zoom);

            // A cosine gives a natural card flip: front -> thin edge -> mirrored back.
            double flipScaleX = Math.cos(Math.PI * smoothStep(progress));
            double visibleWidth = Math.max(0.018, Math.abs(flipScaleX));
            int cx = r.x + r.width / 2;
            int cy = r.y + r.height / 2;
            int arc = Math.round(16f * (1f - zoom));

            g2.setComposite(AlphaComposite.SrcOver.derive(alpha));
            java.awt.geom.AffineTransform oldTransform = g2.getTransform();
            g2.translate(cx, cy);
            g2.scale(visibleWidth, 1.0);
            g2.setColor(new Color(0, 0, 0, Math.round(72 * alpha)));
            g2.fillRoundRect(-r.width / 2 + 10, -r.height / 2 + 14, r.width, r.height, arc, arc);

            Rectangle face = new Rectangle(-r.width / 2, -r.height / 2, r.width, r.height);
            g2.setPaint(new GradientPaint(face.x, face.y, brighten(accent, 18),
                    face.x + face.width, face.y + face.height, accent.darker()));
            g2.fillRoundRect(face.x, face.y, face.width, face.height, arc, arc);
            int logoSize = Math.max(72, Math.min(148, Math.min(getWidth(), getHeight()) / 5));
            int logoW = Math.round(Math.max(44, logoSize * (0.50f + 0.50f * zoom)));
            Rectangle logoRect = new Rectangle(-logoW / 2, -logoW / 2, logoW, logoW);
            if (logoImage != null) {
                paintMetroLogoImage(g2, logoRect, logoImage, color, false);
            } else {
                g2.setColor(new Color(255, 255, 255, 220));
                g2.fillRect(logoRect.x, logoRect.y, logoRect.width, logoRect.height);
            }
            g2.setTransform(oldTransform);

            // A soft highlight hides the hand-off from the preview snapshot to the
            // live screen, then fades away to reveal the already prepared tab.
            float lightIn = smoothStep(Math.max(0f, (progress - 0.70f) / 0.16f));
            float lightOut = 1f - smoothStep(Math.max(0f, (progress - 0.86f) / 0.14f));
            float lightAlpha = 0.28f * lightIn * lightOut;
            if (lightAlpha > 0f) {
                g2.setComposite(AlphaComposite.SrcOver.derive(lightAlpha));
                g2.setPaint(new GradientPaint(0, 0, Color.WHITE,
                        getWidth(), getHeight(), new Color(205, 230, 255)));
                g2.fillRect(0, 0, getWidth(), getHeight());
            }

            g2.dispose();
        }
    }

    private static void paintMetroTransitionPreview(Graphics2D g2, Rectangle r, String kind) {
        if (r.width <= 4 || r.height <= 4) {
            return;
        }
        g2.setColor(new Color(18, 20, 28, 150));
        g2.fillRect(r.x, r.y, r.width, r.height);
        g2.setColor(new Color(255, 255, 255, 58));
        g2.fillRect(r.x, r.y, r.width, Math.max(5, r.height / 8));
        int rows = "settings".equals(kind) ? 3 : 4;
        int top = r.y + Math.max(12, r.height / 5);
        for (int i = 0; i < rows; i++) {
            int y = top + i * Math.max(10, r.height / 7);
            g2.setColor(new Color(255, 255, 255, 60));
            g2.fillRect(r.x + 12, y, Math.max(12, r.width - 24), 6);
            if ("settings".equals(kind)) {
                g2.setColor(new Color(186, 132, 214, 170));
                g2.fillRect(r.x + 12, y, Math.max(10, (r.width - 24) * (i + 2) / 5), 6);
            }
        }
    }

    private static Rectangle interpolate(Rectangle a, Rectangle b, float t) {
        return new Rectangle(
                Math.round(a.x + (b.x - a.x) * t),
                Math.round(a.y + (b.y - a.y) * t),
                Math.round(a.width + (b.width - a.width) * t),
                Math.round(a.height + (b.height - a.height) * t)
        );
    }

    private static float smoothStep(float t) {
        t = Math.max(0f, Math.min(1f, t));
        return t * t * (3f - 2f * t);
    }

    private static Rectangle inset(Rectangle r, int amount) {
        return new Rectangle(
                r.x + amount,
                r.y + amount,
                Math.max(1, r.width - amount * 2),
                Math.max(1, r.height - amount * 2)
        );
    }

    private static Color lerpColor(Color a, Color b, float t) {
        t = Math.max(0f, Math.min(1f, t));
        return new Color(
                Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
                Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
                Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
                Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t)
        );
    }

    private static void paintMetroSnapshotImage(Graphics2D g2, Rectangle r, BufferedImage image, boolean mirrored) {
        if (image == null || r.width <= 0 || r.height <= 0) {
            return;
        }
        double scale = Math.max(r.width / (double) image.getWidth(), r.height / (double) image.getHeight());
        int drawW = Math.max(1, (int) Math.round(image.getWidth() * scale));
        int drawH = Math.max(1, (int) Math.round(image.getHeight() * scale));
        int dx = r.x + (r.width - drawW) / 2;
        int dy = r.y + (r.height - drawH) / 2;
        Object oldInterpolation = g2.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        Shape oldClip = g2.getClip();
        g2.clipRect(r.x, r.y, r.width, r.height);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        if (mirrored) {
            g2.drawImage(image, dx + drawW, dy, -drawW, drawH, null);
        } else {
            g2.drawImage(image, dx, dy, drawW, drawH, null);
        }
        if (oldInterpolation != null) {
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
        }
        g2.setClip(oldClip);
    }

    private static void paintMetroPreviewImage(Graphics2D g2, Rectangle r, BufferedImage image, Color fallbackColor) {
        if (r.width <= 4 || r.height <= 4) {
            return;
        }
        g2.setColor(new Color(18, 20, 28, 150));
        g2.fillRect(r.x, r.y, r.width, r.height);
        if (image == null) {
            g2.setColor(new Color(
                    Math.max(0, fallbackColor.getRed() - 28),
                    Math.max(0, fallbackColor.getGreen() - 28),
                    Math.max(0, fallbackColor.getBlue() - 28),
                    170));
            g2.fillRect(r.x + 1, r.y + 1, Math.max(1, r.width - 2), Math.max(1, r.height - 2));
            return;
        }
        double scale = Math.min(r.width / (double) image.getWidth(), r.height / (double) image.getHeight());
        int drawW = Math.max(1, (int) Math.round(image.getWidth() * scale));
        int drawH = Math.max(1, (int) Math.round(image.getHeight() * scale));
        int dx = r.x + (r.width - drawW) / 2;
        int dy = r.y + (r.height - drawH) / 2;
        Shape oldClip = g2.getClip();
        Object oldInterpolation = g2.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g2.clipRect(r.x, r.y, r.width, r.height);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.drawImage(image, dx, dy, drawW, drawH, null);
        if (oldInterpolation != null) {
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
        }
        g2.setClip(oldClip);
        g2.setColor(new Color(255, 255, 255, 65));
        g2.drawRect(r.x, r.y, Math.max(0, r.width - 1), Math.max(0, r.height - 1));
    }

    private static void paintMetroLogoImage(Graphics2D g2, Rectangle r, BufferedImage image, Color fallbackColor) {
        paintMetroLogoImage(g2, r, image, fallbackColor, false);
    }

    private static void paintMetroLogoImage(Graphics2D g2, Rectangle r, BufferedImage image, Color fallbackColor, boolean mirrored) {
        if (r.width <= 0 || r.height <= 0) {
            return;
        }
        if (image == null) {
            return;
        }
        double maxW = Math.max(1.0, r.width * 0.64);
        double maxH = Math.max(1.0, r.height * 0.64);
        double scale = Math.min(maxW / image.getWidth(), maxH / image.getHeight());
        int drawW = Math.max(1, (int) Math.round(image.getWidth() * scale));
        int drawH = Math.max(1, (int) Math.round(image.getHeight() * scale));
        int dx = r.x + (r.width - drawW) / 2;
        int dy = r.y + (r.height - drawH) / 2;
        Object oldInterpolation = g2.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        if (mirrored) {
            g2.drawImage(image, dx + drawW, dy, -drawW, drawH, null);
        } else {
            g2.drawImage(image, dx, dy, drawW, drawH, null);
        }
        if (oldInterpolation != null) {
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
        }
    }

    private static void paintMetroPreview(Graphics2D g2, Rectangle r, String kind, boolean compact) {
        if (r.width <= 4 || r.height <= 4) {
            return;
        }
        g2.setColor(new Color(18, 20, 28, compact ? 118 : 190));
        g2.fillRect(r.x, r.y, r.width, r.height);
        g2.setColor(new Color(255, 255, 255, compact ? 58 : 82));
        g2.drawRect(r.x, r.y, Math.max(0, r.width - 1), Math.max(0, r.height - 1));
        g2.setColor(new Color(255, 255, 255, compact ? 52 : 72));
        g2.fillRect(r.x, r.y, r.width, Math.max(5, r.height / 7));

        switch (kind) {
            case "mods" -> paintModsPreview(g2, r);
            case "skins" -> paintSkinsPreview(g2, r);
            case "library" -> paintLibraryPreview(g2, r);
            case "settings" -> paintSettingsPreview(g2, r);
            case "game" -> paintGamePreview(g2, r);
            case "folder" -> paintFolderPreview(g2, r);
            default -> paintLibraryPreview(g2, r);
        }
    }

    private static void paintModsPreview(Graphics2D g2, Rectangle r) {
        int top = r.y + Math.max(10, r.height / 6);
        int sideW = Math.max(22, r.width / 4);
        g2.setColor(new Color(255, 255, 255, 54));
        for (int i = 0; i < 4; i++) {
            g2.fillRect(r.x + 8, top + i * 12, Math.max(8, sideW - 12), 5);
        }
        g2.setColor(new Color(255, 255, 255, 78));
        int cardW = Math.max(14, (r.width - sideW - 22) / 2);
        int cardH = Math.max(12, (r.height - 28) / 2);
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                g2.fillRect(r.x + sideW + 8 + x * (cardW + 6), top + y * (cardH + 6), cardW, cardH);
            }
        }
    }

    private static void paintSkinsPreview(Graphics2D g2, Rectangle r) {
        int cx = r.x + r.width / 2;
        int top = r.y + Math.max(12, r.height / 5);
        int unit = Math.max(5, Math.min(r.width, r.height) / 8);
        g2.setColor(new Color(255, 228, 188, 190));
        g2.fillRect(cx - unit, top, unit * 2, unit * 2);
        g2.setColor(new Color(64, 110, 180, 185));
        g2.fillRect(cx - unit, top + unit * 2, unit * 2, unit * 3);
        g2.setColor(new Color(255, 255, 255, 95));
        g2.fillRect(cx - unit * 3, top + unit * 2, unit * 2, unit * 3);
        g2.fillRect(cx + unit, top + unit * 2, unit * 2, unit * 3);
        g2.setColor(new Color(40, 44, 58, 190));
        g2.fillRect(cx - unit, top + unit * 5, unit, unit * 2);
        g2.fillRect(cx, top + unit * 5, unit, unit * 2);
    }

    private static void paintLibraryPreview(Graphics2D g2, Rectangle r) {
        int top = r.y + Math.max(10, r.height / 6);
        for (int i = 0; i < 4; i++) {
            int y = top + i * Math.max(10, r.height / 7);
            g2.setColor(new Color(255, 255, 255, 72));
            g2.fillRect(r.x + 10, y, Math.max(12, r.width - 20), 7);
            g2.setColor(new Color(255, 255, 255, 120));
            g2.fillRect(r.x + 10, y, Math.max(8, r.width / 5), 7);
        }
    }

    private static void paintSettingsPreview(Graphics2D g2, Rectangle r) {
        int top = r.y + Math.max(12, r.height / 5);
        for (int i = 0; i < 3; i++) {
            int y = top + i * Math.max(14, r.height / 5);
            g2.setColor(new Color(255, 255, 255, 70));
            g2.fillRect(r.x + 12, y, Math.max(16, r.width - 24), 6);
            g2.setColor(new Color(186, 132, 214, 190));
            g2.fillRect(r.x + 12, y, Math.max(10, (r.width - 24) * (i + 2) / 5), 6);
            g2.fillRect(r.x + 12 + (r.width - 24) * (i + 2) / 5, y - 4, 7, 14);
        }
    }

    private static void paintGamePreview(Graphics2D g2, Rectangle r) {
        int horizon = r.y + r.height * 2 / 3;
        g2.setPaint(new GradientPaint(r.x, r.y, new Color(80, 140, 190, 160), r.x, horizon, new Color(145, 190, 120, 160)));
        g2.fillRect(r.x + 1, r.y + Math.max(6, r.height / 7), Math.max(1, r.width - 2), Math.max(1, horizon - r.y));
        g2.setColor(new Color(72, 92, 48, 175));
        g2.fillRect(r.x + 1, horizon, Math.max(1, r.width - 2), Math.max(1, r.height - (horizon - r.y) - 1));
        g2.setColor(new Color(80, 58, 42, 190));
        g2.fillRect(r.x + r.width / 2 - 7, horizon - 18, 14, 18);
    }

    private static void paintFolderPreview(Graphics2D g2, Rectangle r) {
        int x = r.x + 12;
        int y = r.y + Math.max(14, r.height / 4);
        int w = Math.max(18, r.width - 24);
        int h = Math.max(14, r.height - (y - r.y) - 12);
        g2.setColor(new Color(255, 220, 120, 170));
        g2.fillRect(x, y, w / 2, Math.max(8, h / 4));
        g2.setColor(new Color(255, 200, 82, 190));
        g2.fillRect(x, y + h / 5, w, h);
        g2.setColor(new Color(0, 0, 0, 45));
        g2.drawRect(x, y + h / 5, Math.max(0, w - 1), Math.max(0, h - 1));
    }

    private static Color brighten(Color color, int amount) {
        return new Color(
                Math.min(255, color.getRed() + amount),
                Math.min(255, color.getGreen() + amount),
                Math.min(255, color.getBlue() + amount),
                color.getAlpha()
        );
    }

    private static String fitText(String text, FontMetrics fm, int maxWidth) {
        if (fm.stringWidth(text) <= maxWidth) {
            return text;
        }
        String ellipsis = "...";
        int limit = Math.max(0, maxWidth - fm.stringWidth(ellipsis));
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            if (fm.stringWidth(out.toString() + text.charAt(i)) > limit) {
                break;
            }
            out.append(text.charAt(i));
        }
        return out + ellipsis;
    }

    private String html(String text) {
        if (text == null) return "";
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

