    /**
     * Two animated ticker strips, one below the other.
     * Row 1 (left-to-right): Главная, Моды, Скины, Библиотеки, Журнал, Бэкапы, Настройки
     * Row 2 (right-to-left): same tabs in reverse order, offset for visual variety.
     * Each tab pill is clickable and navigates to the corresponding screen, and can
     * be dragged with the mouse onto another pill to swap their positions (the
     * new order is shared between both strips, since they show the same items).
     */
    private JPanel buildNavTickersBlock() {
        JPanel block = new JPanel(new BorderLayout(0, 0));
        block.setOpaque(false);
        block.setBorder(BorderFactory.createEmptyBorder(12, 20, 8, 20));

        JLabel title = new JLabel(nr("Recent versions", "Недавние версии"));
        title.setForeground(MR_TEXT);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));
        title.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        recentVersionsRow = transparentPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
        refreshRecentVersions();

        JPanel rows = transparentPanel(new BorderLayout(0, 0));
        rows.add(title, BorderLayout.NORTH);
        rows.add(recentVersionsRow, BorderLayout.CENTER);
        block.add(rows, BorderLayout.NORTH);
        return block;
    }

    private void refreshRecentVersions() {
        if (recentVersionsRow == null) {
            return;
        }
        recentVersionsRow.removeAll();
        Map<String, Long> launches = loadRecentLaunches();
        java.util.List<InstalledVersionEntry> entries = new ArrayList<>();
        for (int i = 0; i < installedVersionsModel.getSize(); i++) {
            InstalledVersionEntry entry = installedVersionsModel.getElementAt(i);
            if (launches.containsKey(entry.id())) {
                entries.add(entry);
            }
        }
        entries.sort(java.util.Comparator.comparingLong(
                (InstalledVersionEntry entry) -> launches.getOrDefault(entry.id(), 0L)).reversed());
        for (InstalledVersionEntry entry : entries.stream().limit(4).toList()) {
            JButton button = new ColoredPillButton(
                    displayLabelFor(entry.kind(), entry.id()), new Color(82, 86, 94), Color.WHITE);
            button.setToolTipText(entry.id());
            button.addActionListener(e -> {
                selectInstalledVersion(entry.id());
                showInstanceDetailsOverlay(entry);
            });
            recentVersionsRow.add(button);
        }
        if (entries.isEmpty()) {
            JLabel empty = new JLabel(nr("No recently launched versions", "Недавно запущенных версий пока нет"));
            empty.setForeground(MR_TEXT_DIM);
            recentVersionsRow.add(empty);
        }
        recentVersionsRow.revalidate();
        recentVersionsRow.repaint();
    }

    /** One clickable/draggable pill in a nav ticker strip. */
    private static final class NavTickerItem {
        final String label;
        final String emoji;
        final Runnable action;
        NavTickerItem(String label, String emoji, Runnable action) {
            this.label = label;
            this.emoji = emoji;
            this.action = action;
        }
    }

    /**
     * A single horizontally scrolling ticker strip of clickable nav pills.
     * Pills can be dragged with the mouse and dropped onto another pill (in
     * this strip or the sibling one, since they share the same item list) to
     * swap their positions.
     */
    private class NavTickerStrip extends JPanel implements java.awt.event.ActionListener {
        private final java.util.List<NavTickerItem> items;
        private final boolean reverse;
        private final Runnable onReorder;
        private float offset = 0f;
        private int totalWidth = 0;
        private final javax.swing.Timer timer;
        private final java.util.List<java.awt.Rectangle> pillBounds = new java.util.ArrayList<>();
        private int hoveredIndex = -1;
        private static final int PILL_H = 38;
        private static final int PILL_PAD_X = 20;
        private static final int GAP = 14;
        private static final float SPEED = 0.6f;
        private static final int DRAG_THRESHOLD = 6;

        // Состояние перетаскивания мышью
        private Point dragPressPoint;
        private boolean dragging;
        private int dragSourceIndex = -1;
        private int dragHoverIndex = -1;

        NavTickerStrip(java.util.List<NavTickerItem> items, boolean reverse, Runnable onReorder) {
            this.items  = items;
            this.reverse = reverse;
            this.onReorder = onReorder;
            setOpaque(true);
            setBackground(MR_SIDEBAR);
            int borderTop    = reverse ? 0 : 1;
            int borderBottom = reverse ? 1 : 0;
            setBorder(BorderFactory.createMatteBorder(borderTop, 0, borderBottom, 0, MR_BORDER));
            setPreferredSize(new Dimension(0, PILL_H + 20));

            timer = new javax.swing.Timer(40, this);
            timer.setRepeats(true);
            addHierarchyListener(e -> {
                if (LinuxUiSupport.animationsEnabled() && isShowing()) {
                    if (!timer.isRunning()) timer.start();
                } else {
                    timer.stop();
                }
            });

            addMouseMotionListener(new java.awt.event.MouseMotionAdapter() {
                @Override public void mouseMoved(java.awt.event.MouseEvent e) {
                    int prev = hoveredIndex;
                    hoveredIndex = hitTest(e.getX(), e.getY());
                    if (hoveredIndex != prev) repaint();
                }
                @Override public void mouseDragged(java.awt.event.MouseEvent e) {
                    if (dragPressPoint == null) return;
                    if (!dragging) {
                        int dx = e.getX() - dragPressPoint.x;
                        int dy = e.getY() - dragPressPoint.y;
                        if (Math.abs(dx) < DRAG_THRESHOLD && Math.abs(dy) < DRAG_THRESHOLD) return;
                        dragging = true;
                        setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.MOVE_CURSOR));
                    }
                    int idx = hitTest(e.getX(), e.getY());
                    dragHoverIndex = (idx < 0) ? -1 : (idx % items.size());
                    repaint();
                }
            });
            addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mousePressed(java.awt.event.MouseEvent e) {
                    dragPressPoint = e.getPoint();
                    dragging = false;
                    int idx = hitTest(e.getX(), e.getY());
                    dragSourceIndex = (idx < 0) ? -1 : (idx % items.size());
                    dragHoverIndex = -1;
                }
                @Override public void mouseReleased(java.awt.event.MouseEvent e) {
                    if (dragging && dragSourceIndex >= 0 && dragHoverIndex >= 0
                            && dragSourceIndex != dragHoverIndex) {
                        java.util.Collections.swap(items, dragSourceIndex, dragHoverIndex);
                        if (onReorder != null) onReorder.run();
                    }
                    dragPressPoint = null;
                    dragHoverIndex = -1;
                    dragSourceIndex = -1;
                    setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
                    // dragging сбрасывается уже после обработки клика ниже,
                    // чтобы отличить обычный клик от завершения перетаскивания.
                    repaint();
                }
                @Override public void mouseClicked(java.awt.event.MouseEvent e) {
                    if (dragging) {
                        // Это было перетаскивание, а не обычный клик — навигацию не запускаем.
                        dragging = false;
                        return;
                    }
                    int idx = hitTest(e.getX(), e.getY());
                    if (idx >= 0) items.get(idx % items.size()).action.run();
                }
                @Override public void mouseExited(java.awt.event.MouseEvent e) {
                    hoveredIndex = -1;
                    repaint();
                }
            });
            setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
        }

        private int hitTest(int mx, int my) {
            for (int i = 0; i < pillBounds.size(); i++) {
                if (pillBounds.get(i).contains(mx, my)) return i;
            }
            return -1;
        }

        @Override public void actionPerformed(java.awt.event.ActionEvent e) {
            if (!isShowing()) return;
            if (dragging) return; // не прокручиваем ленту, пока пользователь тащит элемент
            offset += reverse ? -SPEED : SPEED;
            if (totalWidth > 0) {
                if (!reverse && offset > totalWidth) offset -= totalWidth;
                if (reverse && offset < -totalWidth) offset += totalWidth;
            }
            repaint();
        }

        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);

            Font pillFont  = getFont().deriveFont(Font.PLAIN, 13f);
            Font emojiFont = getFont().deriveFont(Font.PLAIN, 15f);
            g2.setFont(pillFont);

            // Measure one set of pills to get totalWidth
            if (totalWidth == 0) {
                int w = 0;
                for (NavTickerItem item : items) {
                    g2.setFont(emojiFont);
                    int ew = g2.getFontMetrics().stringWidth(item.emoji);
                    g2.setFont(pillFont);
                    int lw = g2.getFontMetrics().stringWidth(item.label);
                    w += ew + 6 + lw + PILL_PAD_X * 2 + GAP;
                }
                totalWidth = w;
            }

            int cy = getHeight() / 2;
            pillBounds.clear();

            // Draw enough copies to fill + overflow the width
            int copies = (getWidth() / (totalWidth + 1)) + 3;
            for (int copy = -1; copy < copies; copy++) {
                // offset уже содержит правильный знак (растёт для прямой полосы,
                // убывает для reverse), поэтому здесь его больше не инвертируем —
                // иначе обе полоски визуально бежали в одну и ту же сторону.
                float baseX = copy * totalWidth + offset;
                float x = baseX;
                for (int i = 0; i < items.size(); i++) {
                    NavTickerItem item = items.get(i);
                    g2.setFont(emojiFont);
                    int ew = g2.getFontMetrics().stringWidth(item.emoji);
                    g2.setFont(pillFont);
                    int lw = g2.getFontMetrics().stringWidth(item.label);
                    int pw = ew + 6 + lw + PILL_PAD_X * 2;

                    int px = Math.round(x);
                    int py = cy - PILL_H / 2;

                    // Simple hover check by position
                    java.awt.Point mouse = getMousePosition();
                    boolean isHover = mouse != null && mouse.x >= px && mouse.x <= px + pw
                            && mouse.y >= py && mouse.y <= py + PILL_H;

                    boolean isDragSource = dragging && i == dragSourceIndex;
                    boolean isDropTarget = dragging && i == dragHoverIndex && dragHoverIndex != dragSourceIndex;

                    // Pill background — theme-aware
                    Color pillBg   = isHover ? MR_CARD : MR_BG;
                    Color pillBord = isDropTarget ? new Color(80, 200, 120) : (isHover ? MR_ACCENT : MR_BORDER);
                    Color textCol  = isHover ? MR_TEXT : MR_TEXT_DIM;

                    if (isDragSource) {
                        g2.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.45f));
                    }
                    g2.setColor(pillBg);
                    g2.fillRoundRect(px, py, pw, PILL_H, 20, 20);
                    g2.setColor(pillBord);
                    g2.setStroke(new java.awt.BasicStroke(isDropTarget ? 2.2f : 1f));
                    g2.drawRoundRect(px, py, pw, PILL_H, 20, 20);
                    g2.setStroke(new java.awt.BasicStroke(1f));

                    // Emoji
                    g2.setFont(emojiFont);
                    g2.setColor(textCol);
                    java.awt.FontMetrics efm = g2.getFontMetrics();
                    int ey = py + (PILL_H + efm.getAscent() - efm.getDescent()) / 2;
                    g2.drawString(item.emoji, px + PILL_PAD_X, ey);

                    // Label
                    g2.setFont(pillFont);
                    g2.setColor(textCol);
                    java.awt.FontMetrics lfm = g2.getFontMetrics();
                    int ly = py + (PILL_H + lfm.getAscent() - lfm.getDescent()) / 2;
                    g2.drawString(item.label, px + PILL_PAD_X + ew + 6, ly);
                    if (isDragSource) {
                        g2.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 1f));
                    }

                    // Register bounds for click
                    pillBounds.add(new java.awt.Rectangle(px, py, pw, PILL_H));

                    x += pw + GAP;
                }
            }

            // Fade edges
            int fadeW = 60;
            java.awt.GradientPaint fadeLeft = new java.awt.GradientPaint(
                    0, 0, getBackground(),
                    fadeW, 0, new Color(getBackground().getRed(), getBackground().getGreen(), getBackground().getBlue(), 0));
            java.awt.GradientPaint fadeRight = new java.awt.GradientPaint(
                    getWidth() - fadeW, 0, new Color(getBackground().getRed(), getBackground().getGreen(), getBackground().getBlue(), 0),
                    getWidth(), 0, getBackground());
            g2.setPaint(fadeLeft);
            g2.fillRect(0, 0, fadeW, getHeight());
            g2.setPaint(fadeRight);
            g2.fillRect(getWidth() - fadeW, 0, fadeW, getHeight());

            g2.dispose();
        }

        /** Stop animation when panel is removed. */
        @Override public void removeNotify() {
            super.removeNotify();
            timer.stop();
        }

        /** Resume animation when panel is added. */
        @Override public void addNotify() {
            super.addNotify();
            if (LinuxUiSupport.animationsEnabled() && !timer.isRunning()) timer.start();
        }

    }

    /**
     * Single status row shown right below the two nav ticker strips.
     * Shows the configured Minecraft server's address, whether it's online,
     * and the live player count (refreshed periodically via Server List Ping).
     * Clicking anywhere on the row launches Minecraft {@link #MC_SERVER_VERSION}
     * and connects straight to the server.
     */
    private class ServerStatusBanner extends JPanel {
        private static final int REFRESH_INTERVAL_MS = 15_000;
        private static final int PING_TIMEOUT_MS = 4_000;

        private final String host;
        private final int port;
        private final javax.swing.Timer refreshTimer;
        private boolean hovered = false;
        private boolean checked = false;
        private volatile boolean online = false;
        private volatile int onlinePlayers = 0;
        private volatile int maxPlayers = 0;
        private final boolean classicStyle;

        ServerStatusBanner(String host, int port) {
            this(host, port, false);
        }

        ServerStatusBanner(String host, int port, boolean classicStyle) {
            this.host = host;
            this.port = port;
            this.classicStyle = classicStyle;
            setOpaque(!classicStyle);
            if (classicStyle) {
                setBorder(BorderFactory.createEmptyBorder());
                setPreferredSize(new Dimension(560, 68));
                setMinimumSize(new Dimension(360, 64));
            } else {
                setBackground(new Color(20, 21, 26));
                setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, MR_BORDER));
                setPreferredSize(new Dimension(0, 52));
            }
            setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
            setToolTipText(ui("Launch Minecraft ", "Запустить Minecraft ", "Lancer Minecraft ", "Avvia Minecraft ", "Minecraft を起動 ", "Lansează Minecraft ", "启动 Minecraft ")
                    + MC_SERVER_VERSION
                    + ui(" and connect to ", " и подключиться к ", " et se connecter à ", " e connettersi a ", " して接続先 ", " și conectare la ", " 并连接到 ")
                    + host);

            addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mouseEntered(java.awt.event.MouseEvent e) {
                    hovered = true;
                    repaint();
                }
                @Override public void mouseExited(java.awt.event.MouseEvent e) {
                    hovered = false;
                    repaint();
                }
                @Override public void mouseClicked(java.awt.event.MouseEvent e) {
                    playOnServer();
                }
            });

            refreshTimer = new javax.swing.Timer(REFRESH_INTERVAL_MS, e -> refreshStatus());
        }

        private void refreshStatus() {
            SwingWorker<ServerStatusService.ServerStatus, Void> worker = new SwingWorker<>() {
                @Override protected ServerStatusService.ServerStatus doInBackground() {
                    return serverStatusService.ping(host, port, PING_TIMEOUT_MS);
                }

                @Override protected void done() {
                    boolean newOnline;
                    int newOnlinePlayers;
                    int newMaxPlayers;
                    try {
                        ServerStatusService.ServerStatus status = get();
                        newOnline = status.online();
                        newOnlinePlayers = status.onlinePlayers();
                        newMaxPlayers = status.maxPlayers();
                    } catch (Exception ex) {
                        newOnline = false;
                        newOnlinePlayers = 0;
                        newMaxPlayers = 0;
                    }
                    online = newOnline;
                    onlinePlayers = newOnlinePlayers;
                    maxPlayers = newMaxPlayers;
                    checked = true;
                    repaint();
                }
            };
            worker.execute();
        }

        @Override public void addNotify() {
            super.addNotify();
            refreshStatus();
            if (!refreshTimer.isRunning()) refreshTimer.start();
        }

        @Override public void removeNotify() {
            refreshTimer.stop();
            super.removeNotify();
        }

        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);

            if (classicStyle) {
                paintClassicServerBanner(g2);
                g2.dispose();
                return;
            }

            if (hovered) {
                g2.setColor(MR_LIGHT_ACTIVE ? new Color(215, 218, 228) : new Color(34, 38, 50));
                g2.fillRect(0, 0, getWidth(), getHeight());
            }

            int cy = getHeight() / 2;
            int x = 20;

            // Индикатор статуса (точка)
            Color dotColor = !checked ? new Color(140, 140, 150)
                    : online ? new Color(70, 200, 120) : new Color(220, 80, 80);
            int dotSize = 10;
            g2.setColor(dotColor);
            g2.fillOval(x, cy - dotSize / 2, dotSize, dotSize);
            x += dotSize + 12;

            // Иконка + адрес сервера
            Font titleFont = getFont().deriveFont(Font.BOLD, 14f);
            g2.setFont(titleFont);
            g2.setColor(MR_TEXT);
            String title = "🎮  " + host;
            java.awt.FontMetrics titleFm = g2.getFontMetrics();
            g2.drawString(title, x, cy + (titleFm.getAscent() - titleFm.getDescent()) / 2);
            x += titleFm.stringWidth(title) + 18;

            // Статус: онлайн/оффлайн + количество игроков
            Font statusFont = getFont().deriveFont(Font.PLAIN, 12f);
            g2.setFont(statusFont);
            String statusText;
            if (!checked) {
                statusText = ui("checking status...", "проверка статуса…", "vérification...", "controllo...", "確認中...", "se verifică...", "正在检查...");
                g2.setColor(MR_TEXT_DIM);
            } else if (online) {
                statusText = ui("online", "онлайн", "en ligne", "online", "オンライン", "online", "在线")
                        + " · " + onlinePlayers + "/" + maxPlayers + " "
                        + ui("players", "игроков", "joueurs", "giocatori", "プレイヤー", "jucători", "玩家");
                g2.setColor(new Color(150, 220, 170));
            } else {
                statusText = ui("offline", "оффлайн", "hors ligne", "offline", "オフライン", "offline", "离线");
                g2.setColor(new Color(220, 140, 140));
            }
            java.awt.FontMetrics statusFm = g2.getFontMetrics();
            g2.drawString(statusText, x, cy + (statusFm.getAscent() - statusFm.getDescent()) / 2);

            // Подсказка про запуск справа
            Font hintFont = new Font(Font.DIALOG, Font.PLAIN, 12);
            g2.setFont(hintFont);
            g2.setColor(hovered ? MR_ACCENT : MR_TEXT_DIM);
            String hint = "▶  " + ui("Play on server", "Играть на сервере", "Jouer sur le serveur", "Gioca sul server", "サーバーでプレイ", "Joacă pe server", "在服务器上游玩");
            java.awt.FontMetrics hintFm = g2.getFontMetrics();
            int hx = getWidth() - hintFm.stringWidth(hint) - 20;
            g2.drawString(hint, hx, cy + (hintFm.getAscent() - hintFm.getDescent()) / 2);

            g2.dispose();
        }

        private void paintClassicServerBanner(Graphics2D g2) {
            int w = getWidth();
            int h = getHeight();
            int arc = 22;
            g2.setColor(new Color(0, 0, 0, hovered ? 116 : 92));
            g2.fillRoundRect(3, 6, Math.max(1, w - 6), Math.max(1, h - 8), arc, arc);
            g2.setPaint(new GradientPaint(0, 0,
                    hovered ? new Color(48, 72, 68, 222) : new Color(34, 43, 48, 206),
                    w, h, hovered ? new Color(18, 28, 38, 230) : new Color(16, 21, 30, 218)));
            g2.fillRoundRect(0, 0, Math.max(1, w - 1), Math.max(1, h - 3), arc, arc);
            g2.setColor(new Color(170, 220, 195, hovered ? 120 : 78));
            g2.drawRoundRect(0, 0, Math.max(0, w - 2), Math.max(0, h - 4), arc, arc);

            int x = 18;
            int cy = h / 2;
            Color dotColor = !checked ? new Color(140, 146, 156)
                    : online ? new Color(70, 210, 128) : new Color(224, 82, 82);
            g2.setColor(new Color(0, 0, 0, 55));
            g2.fillOval(x - 2, cy - 9, 18, 18);
            g2.setColor(dotColor);
            g2.fillOval(x, cy - 7, 14, 14);
            x += 28;

            int actionW = w >= 460 ? 146 : 0;
            int textMax = Math.max(80, w - x - actionW - 28);
            Font titleFont = getFont().deriveFont(Font.BOLD, 14f);
            Font metaFont = getFont().deriveFont(Font.PLAIN, 12f);

            g2.setFont(titleFont);
            FontMetrics titleFm = g2.getFontMetrics();
            String title = ui("Mineco server", "Сервер Mineco", "Serveur Mineco", "Server Mineco", "Mineco サーバー", "Server Mineco", "Mineco 服务器")
                    + " · " + MC_SERVER_HOST;
            g2.setColor(TEXT_PRIMARY);
            g2.drawString(fitText(title, titleFm, textMax), x, cy - 5);

            g2.setFont(metaFont);
            FontMetrics metaFm = g2.getFontMetrics();
            String statusText;
            if (!checked) {
                statusText = ui("checking status...", "проверка статуса...", "vérification...", "controllo...", "確認中...", "se verifică...", "正在检查...");
                g2.setColor(TEXT_SECONDARY);
            } else if (online) {
                statusText = ui("online", "онлайн", "en ligne", "online", "オンライン", "online", "在线")
                        + " · " + onlinePlayers + "/" + maxPlayers + " "
                        + ui("players", "игроков", "joueurs", "giocatori", "プレイヤー", "jucători", "玩家")
                        + " · Minecraft " + MC_SERVER_VERSION;
                g2.setColor(new Color(156, 226, 178));
            } else {
                statusText = ui("offline", "оффлайн", "hors ligne", "offline", "オフライン", "offline", "离线")
                        + " · Minecraft " + MC_SERVER_VERSION;
                g2.setColor(new Color(226, 148, 148));
            }
            g2.drawString(fitText(statusText, metaFm, textMax), x, cy + 15);

            if (actionW > 0) {
                int pillH = 34;
                int pillX = w - actionW - 16;
                int pillY = (h - pillH) / 2 - 1;
                g2.setPaint(new GradientPaint(pillX, pillY,
                        hovered ? new Color(64, 196, 112) : new Color(50, 168, 90),
                        pillX + actionW, pillY + pillH,
                        hovered ? new Color(44, 138, 82) : new Color(36, 116, 72)));
                g2.fillRoundRect(pillX, pillY, actionW, pillH, pillH, pillH);
                g2.setColor(new Color(255, 255, 255, 74));
                g2.drawRoundRect(pillX, pillY, actionW - 1, pillH - 1, pillH, pillH);
                g2.setColor(Color.WHITE);
                g2.setFont(new Font(Font.DIALOG, Font.BOLD, 12));
                String label = ui("Play server", "Играть", "Jouer", "Gioca", "プレイ", "Joacă", "游玩");
                FontMetrics fm = g2.getFontMetrics();
                String text = "\u25b6  " + label;
                g2.drawString(text, pillX + (actionW - fm.stringWidth(text)) / 2,
                        pillY + (pillH + fm.getAscent() - fm.getDescent()) / 2);
            }
        }
    }

    /**
     * Embeds a custom image on the main screen. The image is loaded through
     * the same {@link LauncherAssets} search path used for the launcher icon
     * (see {@link #applyLauncherIcon()}), so dropping a file with the given
     * name into any of those folders — most simply the project's
     * {@code Resources/} folder, right next to {@code launcher-icon.png} — is
     * enough for it to appear here. Scales to fit while keeping its aspect
     * ratio, and never upscales beyond the original size.
     */
    private class EmbeddedImagePanel extends JPanel {
        private final String fileName;
        private BufferedImage image;

        EmbeddedImagePanel(String fileName) {
            this.fileName = fileName;
            setOpaque(false);
            setPreferredSize(new Dimension(0, 220));
            reload();
        }

        void reload() {
            try {
                image = LauncherAssets.readImage(settings.gameDirectory(), fileName);
            } catch (Exception ex) {
                image = null;
            }
            repaint();
        }

        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

            if (image != null) {
                int panelW = getWidth();
                int panelH = getHeight();
                int imgW = image.getWidth();
                int imgH = image.getHeight();
                double scale = Math.min(
                        (panelW - 40) / (double) imgW,
                        (panelH - 24) / (double) imgH);
                scale = Math.min(scale, 1.0); // не увеличиваем картинку сверх оригинального размера
                int drawW = Math.max(1, (int) Math.round(imgW * scale));
                int drawH = Math.max(1, (int) Math.round(imgH * scale));
                int dx = (panelW - drawW) / 2;
                int dy = (panelH - drawH) / 2;
                g2.drawImage(image, dx, dy, drawW, drawH, null);
            } else {
                // Изображение не найдено — ничего не рисуем (текст-подсказка убран)
            }
            g2.dispose();
        }
    }

    private void playOnServer() {
        ServerLaunchChoice choice = showServerLaunchDialog();
        if (choice == null) {
            return;
        }
        playOnServer(choice);
    }

    private ServerLaunchChoice showServerLaunchDialog() {
        List<ServerLaunchChoice> choices = installedServerLaunchChoices();
        if (choices.isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    ui("No installed Minecraft versions from 1.21.4 to 1.21.11.",
                            "Нет установленных версий Minecraft от 1.21.4 до 1.21.11.",
                            "Aucune version Minecraft installée entre 1.21.4 et 1.21.11.",
                            "Nessuna versione Minecraft installata da 1.21.4 a 1.21.11.",
                            "Minecraft 1.21.4 から 1.21.11 のインストール済みバージョンがありません。",
                            "Nu există versiuni Minecraft instalate între 1.21.4 și 1.21.11.",
                            "未安装 Minecraft 1.21.4 到 1.21.11 的版本。"),
                    ui("Play on server", "Играть на сервере", "Jouer sur le serveur", "Gioca sul server", "サーバーでプレイ", "Joacă pe server", "在服务器上游玩"),
                    JOptionPane.WARNING_MESSAGE
            );
            return null;
        }
        RoundedComboBox<ServerLaunchChoice> profileCombo = new RoundedComboBox<>(choices.toArray(new ServerLaunchChoice[0]));
        profileCombo.setSelectedIndex(0);

        JPanel panel = new JPanel(new GridBagLayout());
        panel.setOpaque(false);
        GridBagConstraints c = baseConstraints();
        c.gridx = 0; c.gridy = 0; c.weightx = 0; c.fill = GridBagConstraints.NONE;
        panel.add(new JLabel(ui("Profile:", "Профиль:", "Profil :", "Profilo:", "プロファイル:", "Profil:", "配置文件：")), c);
        c.gridx = 1; c.weightx = 1; c.fill = GridBagConstraints.HORIZONTAL;
        panel.add(profileCombo, c);

        applyDarkTranslucentTheme(panel);
        applyLinuxDarkComponentFixes(panel);
        markSystemFont(profileCombo);

        int result = JOptionPane.showConfirmDialog(
                this,
                panel,
                ui("Play on server", "Играть на сервере", "Jouer sur le serveur", "Gioca sul server", "サーバーでプレイ", "Joacă pe server", "在服务器上游玩"),
                JOptionPane.OK_CANCEL_OPTION,
                JOptionPane.PLAIN_MESSAGE
        );
        if (result != JOptionPane.OK_OPTION) {
            return null;
        }
        Object selected = profileCombo.getSelectedItem();
        return selected instanceof ServerLaunchChoice choice ? choice : null;
    }

    private List<ServerLaunchChoice> installedServerLaunchChoices() {
        List<String> installed = installer.listInstalledVersions(settings.gameDirectory());
        return installed.stream()
                .map(profileId -> new ServerLaunchChoice(profileId, installedGameVersion(profileId), detectInstallKindForProfile(profileId)))
                .filter(choice -> isServerSupportedGameVersion(choice.gameVersion()))
                .sorted((a, b) -> {
                    int versionCompare = VersionSort.compareVersions(b.gameVersion(), a.gameVersion());
                    if (versionCompare != 0) {
                        return versionCompare;
                    }
                    return a.profileId().compareToIgnoreCase(b.profileId());
                })
                .toList();
    }

    private boolean isServerSupportedGameVersion(String gameVersion) {
        if (gameVersion == null || gameVersion.isBlank()) {
            return false;
        }
        return VersionSort.compareVersions(gameVersion, "1.21.4") >= 0
                && VersionSort.compareVersions(gameVersion, "1.21.11") <= 0;
    }

    /**
     * Launches the direct-connect server profile: ensures the selected Minecraft
     * client is installed, then starts it with the Quick Play argument so it
     * connects straight to {@link #MC_SERVER_HOST}.
     */
    private void playOnServer(ServerLaunchChoice choice) {
        saveSettingsFromForm();
        if (account.type() == Account.Type.OFFLINE || !usernameField.getText().trim().equals(account.username())) {
            account = Account.offline(usernameField.getText().trim().isEmpty() ? "Player" : usernameField.getText().trim());
            AccountStore.save(account);
            refreshAccountMenu();
            updateAccountLabel();
        }
        String profileId = choice.profileId();
        String serverAddress = MC_SERVER_HOST + ":" + MC_SERVER_PORT;
        runTask(ui("Launching ", "Запуск ", "Lancement ", "Avvio ", "起動中 ", "Se lansează ", "正在启动 ")
                + choice.kind().label + " " + choice.gameVersion()
                + ui(" on server ", " на сервере ", " sur le serveur ", " sul server ", " サーバー ", " pe serverul ", " 于服务器 ")
                + MC_SERVER_HOST, () -> {
            modContentInstaller.repairInstalledModpack(profileId, settings, uiProgress());
            String launchVersion = modLoaderUpdateService.updateBeforeLaunch(profileId, settings, uiProgress());
            Process process = launcher.launch(launchVersion, settings, account, uiProgress(), serverAddress);
            log(t("log.minecraftStarted"));
            return new LaunchResult(process, launchVersion);
        }, result -> {
            if (result instanceof LaunchResult launchResult) {
                refreshInstalledVersions();
                registerRunningMinecraft(launchResult.process(), launchResult.profileId());
                hideLauncherUntilMinecraftExit(launchResult.process(), launchResult.profileId());
            }
        });
    }

