    private void applyClassicVersionFilter() {
        if (classicApiVersionsList == null) {
            return;
        }
        VersionInstallOption previous = classicApiVersionsList.getSelectedValue();
        String query = classicVersionSearchField == null
                ? ""
                : classicVersionSearchField.getText().trim().toLowerCase(java.util.Locale.ROOT);
        VersionKindFilter kindFilter = classicVersionKindFilter == null
                ? null
                : (VersionKindFilter) classicVersionKindFilter.getSelectedItem();

        classicFilteredVersionsModel.clear();
        int selectedIndex = -1;
        for (int i = 0; i < apiVersionsModel.getSize(); i++) {
            VersionInstallOption option = apiVersionsModel.getElementAt(i);
            boolean matchesQuery = query.isEmpty()
                    || option.versionId().toLowerCase(java.util.Locale.ROOT).contains(query)
                    || option.kind().label.toLowerCase(java.util.Locale.ROOT).contains(query);
            boolean matchesKind = kindFilter == null || kindFilter.kind() == null || option.kind() == kindFilter.kind();
            if (matchesQuery && matchesKind) {
                if (option.equals(previous)) {
                    selectedIndex = classicFilteredVersionsModel.size();
                }
                classicFilteredVersionsModel.addElement(option);
            }
        }

        if (!classicFilteredVersionsModel.isEmpty()) {
            classicApiVersionsList.setSelectedIndex(selectedIndex >= 0 ? selectedIndex : 0);
            classicApiVersionsList.ensureIndexIsVisible(classicApiVersionsList.getSelectedIndex());
        } else {
            classicApiVersionsList.clearSelection();
        }
        if (classicVersionCountLabel != null) {
            classicVersionCountLabel.setText(nr(
                    "Found: " + classicFilteredVersionsModel.size(),
                    "Найдено: " + classicFilteredVersionsModel.size()));
        }
        updateClassicVersionPickerActionState();
    }

    private void updateClassicVersionPickerActionState() {
        if (classicVersionPickerInstallButton != null) {
            classicVersionPickerInstallButton.setEnabled(
                    !launcherBusy && classicApiVersionsList != null && classicApiVersionsList.getSelectedValue() != null);
        }
    }

    private void installClassicSelectedVersion() {
        VersionInstallOption option = classicApiVersionsList == null ? null : classicApiVersionsList.getSelectedValue();
        if (option == null || launcherBusy) {
            return;
        }
        apiVersionsList.clearSelection();
        apiVersions.setSelectedItem(option);
        hideOverlay();
        installButton.doClick();
    }

