    private JScrollPane versionListScroll(JList<?> list, String title) {
        return versionListScroll(list, title, null);
    }

    private JScrollPane versionListScroll(JList<?> list, String title, String emptyStateText) {
        boolean installedList = list instanceof InstalledVersionList;
        boolean cardList = installedList || list instanceof AvailableVersionList;
        list.setVisibleRowCount(installedList ? 15 : 13);
        if (cardList) {
            list.setFixedCellHeight(VERSION_CELL_HEIGHT);
        }
        list.setOpaque(false);
        list.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, cardList ? 12 : 11));
        list.setBorder(BorderFactory.createEmptyBorder(4, 5, 4, 5));
        if (!cardList) {
            list.setCellRenderer(new DefaultListCellRenderer() {
                @Override
                public Component getListCellRendererComponent(JList<?> source, Object value, int index,
                                                              boolean isSelected, boolean cellHasFocus) {
                    JLabel label = (JLabel) super.getListCellRendererComponent(source, value, index, isSelected, cellHasFocus);
                    if (value instanceof VersionInstallOption option) {
                        label.setText(optionText(option));
                    } else if (value instanceof InstalledVersionEntry entry) {
                        label.setText(displayLabelFor(entry.kind(), entry.id()));
                    } else {
                        label.setText(value == null ? "" : value.toString());
                    }
                    label.setOpaque(isSelected);
                    label.setBackground(isSelected ? new Color(0, 0, 0, 120) : new Color(0, 0, 0, 0));
                    label.setForeground(TEXT_PRIMARY);
                    label.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));
                    return label;
                }
            });
        }

        JScrollPane scroll = new VersionScrollPane(list, emptyStateText);
        // Width=0 lets the surrounding BorderLayout/GridBagLayout fill the available space;
        // height is a reasonable starting point that the layout can still override.
        scroll.setPreferredSize(installedList ? new Dimension(0, 328) : new Dimension(0, 294));
        // Minimum width prevents the panel from collapsing when the list is empty.
        scroll.setMinimumSize(new Dimension(220, installedList ? 328 : 294));
        // Make the scroll background a dark translucent surface so the list sits on a dark panel
        scroll.setOpaque(false);
        scroll.setBackground(SURFACE);
        scroll.getViewport().setOpaque(false);
        scroll.getVerticalScrollBar().setUnitIncrement(14);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(new RoundedTitledBorder(
                title,
                list.getFont().deriveFont(Font.PLAIN, 10f),
                TEXT_PRIMARY,
                new Color(180, 195, 220, 60),
                ARC + 8
        ));
        return scroll;
    }

