    /** Modern UI settings window: centred card on wallpaper, left section list + right detail pane. */
    private JPanel buildModernSettingsScreen() {
        // When Modern UI is active, settings are shown as an overlay (see showSettingsScreen).
        // This method is still called at init to build the section data structures; the returned
        // panel is stored in settingsPanel only for styleComponentTree() traversal.
        return buildModernSettingsContent();
    }

    /**
     * Builds the settings panel that is shown inside the overlay card.
     * Header (title + close), left section list, right detail pane, footer with save/refresh.
     */
    private JPanel buildModernSettingsContent() {
        JPanel root = transparentPanel(new BorderLayout(0, 0));

        // ── Header ──────────────────────────────────────────────────────────
        JPanel header = new JPanel(new BorderLayout(10, 0));
        header.setOpaque(false);
        header.setBorder(BorderFactory.createEmptyBorder(16, 20, 12, 20));

        // Try to load the set_settings icon; fall back to emoji if not found
        ImageIcon settingsIcon = loadSetIcon("set_settings.png", 20, 20);
        JLabel title;
        if (settingsIcon != null) {
            // Recolour icon to white so it matches the sidebar icon style
            title = new JLabel("  " + t("tab.settings"), recolorIconWhite(settingsIcon), SwingConstants.LEFT);
        } else {
            title = new JLabel("⚙  " + t("tab.settings"));
        }
        title.setFont(title.getFont().deriveFont(Font.BOLD, 17f));
        title.setForeground(MR_TEXT);
        header.add(title, BorderLayout.WEST);

        // Close button (X) — dismisses the overlay
        JButton closeBtn = modernIcon(new JButton("✕") {
            private boolean hov = false;
            { addMouseListener(new MouseAdapter() {
                @Override public void mouseEntered(MouseEvent e) { hov = true; repaint(); }
                @Override public void mouseExited(MouseEvent e)  { hov = false; repaint(); }
            }); }
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                if (hov) { g2.setColor(new Color(255, 80, 80, 60)); g2.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8); }
                g2.dispose();
                super.paintComponent(g);
            }
        }, "btn_close_settings_overlay");
        closeBtn.setFont(closeBtn.getFont().deriveFont(Font.PLAIN, 14f));
        markSystemFont(closeBtn);
        closeBtn.setForeground(MR_TEXT_DIM);
        closeBtn.setFocusPainted(false);
        closeBtn.setBorderPainted(false);
        closeBtn.setContentAreaFilled(false);
        closeBtn.setOpaque(false);
        closeBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        closeBtn.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 10));
        closeBtn.addActionListener(e -> hideOverlay());
        header.add(closeBtn, BorderLayout.EAST);

        JPanel headerSep = new JPanel();
        headerSep.setOpaque(true);
        headerSep.setBackground(MR_BORDER);
        headerSep.setPreferredSize(new Dimension(0, 1));

        JPanel headerBlock = new JPanel(new BorderLayout(0, 0));
        headerBlock.setOpaque(false);
        headerBlock.add(header, BorderLayout.CENTER);
        headerBlock.add(headerSep, BorderLayout.SOUTH);
        root.add(headerBlock, BorderLayout.NORTH);

        JPanel body = new JPanel(new BorderLayout(0, 0));
        body.setOpaque(false);
        body.setBorder(BorderFactory.createEmptyBorder(0, 16, 0, 16));

        // ── Left: text section list ─────────────────────────────────────────
        JPanel sectionList = new JPanel();
        sectionList.setLayout(new BoxLayout(sectionList, BoxLayout.Y_AXIS));
        sectionList.setOpaque(false);
        sectionList.setBorder(BorderFactory.createEmptyBorder(10, 0, 10, 10));
        sectionList.setPreferredSize(new Dimension(SETTINGS_SECTION_LIST_WIDTH, 0));

        settingsSectionButtons.clear();
        settingsSectionCards.removeAll();
        settingsSectionCards.setOpaque(false);

        addSettingsSection(sectionList, "account", t("section.accounts"), buildAccountSection());
        addSettingsSection(sectionList, "paths", t("section.pathsJava"), buildPathsSection());
        addSettingsSection(sectionList, "java", nr("Java installations", "Установки Java"), buildJavaInstallationsSection());
        addSettingsSection(sectionList, "memory", t("section.memory"), buildMemorySection());
        addSettingsSection(sectionList, "filters", t("section.filters"), buildFiltersSection());
        addSettingsSection(sectionList, "versions", t("section.versions"), buildVersionsManagementSection());
        addSettingsSection(sectionList, "launch", t("section.launch"), buildLaunchBehaviorSection());
        addSettingsSection(sectionList, "updates", t("section.updatesShort"), buildUpdatesSection());
        addSettingsSection(sectionList, "ui", t("section.interfaceShort"), buildInterfaceSection());
        sectionList.add(Box.createVerticalGlue());

        JScrollPane leftScroll = new JScrollPane(sectionList);
        leftScroll.setOpaque(false);
        leftScroll.getViewport().setOpaque(false);
        leftScroll.setBorder(BorderFactory.createEmptyBorder());
        leftScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        leftScroll.getVerticalScrollBar().setUnitIncrement(16);
        styleScrollBar(leftScroll.getVerticalScrollBar());

        // ── Divider ──────────────────────────────────────────────────────────
        JPanel divider = new JPanel();
        divider.setOpaque(true);
        divider.setBackground(MR_BORDER);
        divider.setPreferredSize(new Dimension(1, 0));

        // ── Right: section content cards ─────────────────────────────────────
        JScrollPane rightScroll = new JScrollPane(settingsSectionCards);
        rightScroll.setOpaque(false);
        rightScroll.getViewport().setOpaque(false);
        rightScroll.setBorder(BorderFactory.createEmptyBorder(0, 18, 0, 0));
        rightScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        rightScroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        rightScroll.getVerticalScrollBar().setUnitIncrement(16);
        styleScrollBar(rightScroll.getVerticalScrollBar());
        // Force content to always match the viewport width so nothing clips on the right
        rightScroll.getViewport().addComponentListener(new java.awt.event.ComponentAdapter() {
            @Override public void componentResized(java.awt.event.ComponentEvent e) {
                settingsSectionCards.revalidate();
            }
        });

        JPanel center = new JPanel(new BorderLayout());
        center.setOpaque(false);
        center.add(divider, BorderLayout.WEST);
        center.add(rightScroll, BorderLayout.CENTER);

        body.add(leftScroll, BorderLayout.WEST);
        body.add(center, BorderLayout.CENTER);
        root.add(body, BorderLayout.CENTER);

        // ── Footer ───────────────────────────────────────────────────────────
        JPanel footer = transparentPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
        footer.setBorder(BorderFactory.createEmptyBorder(10, 36, 16, 16));
        makePillButton(saveSettingsButton, true);
        makePillButton(refreshSettingsButton, false);
        footer.add(saveSettingsButton);
        footer.add(refreshSettingsButton);
        root.add(footer, BorderLayout.SOUTH);

        showSettingsSection(activeSettingsSection);
        return root;
    }

    // ── Set icon loading (Resources/set/set_*.png, same pipeline as nav icons) ─
    private final java.util.Map<String, ImageIcon> setIconCache = new java.util.HashMap<>();

    /**
     * Tries to load a PNG settings icon from Resources/set/<filename>.
     * Returns null if not found; the caller falls back to the emoji string.
     */
    private ImageIcon loadSetIcon(String filename) {
        return loadSetIcon(filename, 18, 18);
    }

    private ImageIcon loadSetIcon(String filename, int w, int h) {
        String key = filename + "@" + w + "x" + h;
        if (setIconCache.containsKey(key)) return setIconCache.get(key);
        ImageIcon icon = LauncherAssets.readScaledIcon(
                settings.gameDirectory(), w, h,
                new String[]{"set/" + filename, filename});
        setIconCache.put(key, icon);
        return icon;
    }

    /** Recolours an icon's opaque pixels to solid white while preserving its alpha shape (matches sidebar icon style). */
    private ImageIcon recolorIconWhite(ImageIcon icon) {
        BufferedImage src = new BufferedImage(icon.getIconWidth(), icon.getIconHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D gtmp = src.createGraphics();
        icon.paintIcon(null, gtmp, 0, 0);
        gtmp.dispose();
        BufferedImage white = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D gw = white.createGraphics();
        gw.setColor(Color.WHITE);
        gw.fillRect(0, 0, src.getWidth(), src.getHeight());
        gw.setComposite(AlphaComposite.getInstance(AlphaComposite.DST_IN));
        gw.drawImage(src, 0, 0, null);
        gw.dispose();
        return new ImageIcon(white);
    }

    /** Adds one text row to the settings window's left-hand section list and registers its content card. */
    private void addSettingsSection(JPanel list, String key, String label, JPanel content) {
        JButton button = new JButton(label) {
            private float hoverProgress = 0f;
            private boolean hoverTarget = false;
            private final javax.swing.Timer hoverTimer = new javax.swing.Timer(16, e -> {
                float target = hoverTarget ? 1f : 0f;
                float next = hoverProgress + (target - hoverProgress) * 0.22f;
                if (Math.abs(next - target) < 0.015f) {
                    next = target;
                    ((javax.swing.Timer) e.getSource()).stop();
                }
                hoverProgress = next;
                repaint();
            });
            {
                hoverTimer.setRepeats(true);
                addMouseListener(new MouseAdapter() {
                    @Override public void mouseEntered(MouseEvent e) {
                        hoverTarget = true;
                        hoverTimer.start();
                    }
                    @Override public void mouseExited(MouseEvent e) {
                        hoverTarget = false;
                        hoverTimer.start();
                    }
                });
            }
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

                boolean selected = Boolean.TRUE.equals(getClientProperty("settings.selected"));
                float p = selected ? 1f : hoverProgress;
                int arc = 8;
                int inset = Math.round(4 - (2 * p));
                int alpha = selected ? 58 : Math.round(18 + 42 * p);
                if (p > 0.01f) {
                    g2.setColor(new Color(MR_ACCENT.getRed(), MR_ACCENT.getGreen(), MR_ACCENT.getBlue(), alpha));
                    g2.fillRoundRect(inset, 2, getWidth() - inset * 2, getHeight() - 4, arc, arc);
                }

                Color textColor = selected
                        ? MR_ACCENT
                        : blend(MR_TEXT_DIM, MR_TEXT, p);
                float scale = selected ? 1.045f : 1f + 0.045f * p;
                Font drawFont = getFont().deriveFont(selected ? Font.BOLD : Font.PLAIN, 13.5f * scale);
                g2.setFont(drawFont);
                FontMetrics fm = g2.getFontMetrics();
                String drawn = ellipsize(label, fm, getWidth() - 28);
                int textX = 14;
                int textY = (getHeight() - fm.getHeight()) / 2 + fm.getAscent();
                g2.setColor(textColor);
                g2.drawString(drawn, textX, textY);

                int underlineW = Math.round(fm.stringWidth(drawn) * p);
                if (underlineW > 0) {
                    int underlineY = Math.min(getHeight() - 8, textY + 5);
                    g2.setColor(new Color(MR_ACCENT.getRed(), MR_ACCENT.getGreen(), MR_ACCENT.getBlue(),
                            selected ? 230 : Math.round(80 + 150 * p)));
                    g2.fillRoundRect(textX, underlineY, underlineW, 2, 2, 2);
                }
                g2.dispose();
            }
        };
        button.setMargin(new Insets(0, 0, 0, 0));
        button.setBorder(BorderFactory.createEmptyBorder());
        button.setHorizontalAlignment(SwingConstants.LEFT);
        button.setVerticalAlignment(SwingConstants.CENTER);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setContentAreaFilled(false);
        button.setOpaque(false);
        button.setFont(button.getFont().deriveFont(Font.PLAIN, 13.5f));
        button.setForeground(MR_TEXT);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText(label);
        Dimension size = new Dimension(SETTINGS_SECTION_LIST_WIDTH - 12, SETTINGS_SECTION_BUTTON_HEIGHT);
        button.setPreferredSize(size);
        button.setMinimumSize(size);
        button.setMaximumSize(size);
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.putClientProperty("settings.sectionKey", key);
        button.putClientProperty("settings.selected", false);
        button.addActionListener(e -> showSettingsSection(key));
        styleSettingsSectionButton(button, false);
        list.add(button);
        list.add(Box.createVerticalStrut(6));
        settingsSectionButtons.add(button);

        ScrollablePanel wrapped = new ScrollablePanel(new BorderLayout());
        wrapped.setOpaque(false);
        wrapped.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
        wrapped.add(content, BorderLayout.NORTH);
        settingsSectionCards.add(wrapped, key);
    }

    private void styleSettingsSectionButton(JButton button, boolean selected) {
        button.putClientProperty("settings.selected", selected);
        button.setForeground(selected ? MR_ACCENT : MR_TEXT);
        button.setFont(button.getFont().deriveFont(selected ? Font.BOLD : Font.PLAIN, 13.5f));
        button.repaint();
    }

    private void showSettingsSection(String key) {
        activeSettingsSection = key;
        settingsSectionLayout.show(settingsSectionCards, key);
        for (JButton b : settingsSectionButtons) {
            Object k = b.getClientProperty("settings.sectionKey");
            styleSettingsSectionButton(b, key.equals(k));
        }
    }

    private Color blend(Color from, Color to, float amount) {
        float p = Math.max(0f, Math.min(1f, amount));
        int r = Math.round(from.getRed() + (to.getRed() - from.getRed()) * p);
        int g = Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * p);
        int b = Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * p);
        int a = Math.round(from.getAlpha() + (to.getAlpha() - from.getAlpha()) * p);
        return new Color(r, g, b, a);
    }

    private String ellipsize(String text, FontMetrics fm, int maxWidth) {
        if (text == null || fm.stringWidth(text) <= maxWidth) {
            return text == null ? "" : text;
        }
        String ellipsis = "...";
        int end = text.length();
        while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > maxWidth) {
            end--;
        }
        return end <= 0 ? ellipsis : text.substring(0, end) + ellipsis;
    }

    /** Builds a single titled card used inside the settings window's right-hand pane. */
    private JPanel settingsCard(String iconFile, String fallbackEmoji, String cardTitle) {
        ScrollablePanel card = new ScrollablePanel(new GridBagLayout());
        card.setOpaque(true);
        card.setBackground(MR_CARD);
        card.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(MR_BORDER, 1),
                BorderFactory.createEmptyBorder(16, 18, 16, 18)
        ));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        // Add a stretching filler in column 1 so GridBag distributes extra width correctly
        GridBagConstraints filler = new GridBagConstraints();
        filler.gridx = 1; filler.gridy = 99; filler.weightx = 1.0;
        filler.fill = GridBagConstraints.HORIZONTAL;
        card.add(Box.createHorizontalGlue(), filler);

        GridBagConstraints tc = baseConstraints();
        tc.gridx = 0; tc.gridy = 0; tc.gridwidth = 3;
        tc.fill = GridBagConstraints.HORIZONTAL; tc.weightx = 1.0;
        // Use the same PNG icon as the round nav button on the left, recoloured to white;
        // fall back to the emoji only if the PNG asset is missing.
        ImageIcon pngIcon = loadSetIcon(iconFile, 18, 18);
        JLabel cardTitleLabel = pngIcon != null
                ? new JLabel("  " + cardTitle, recolorIconWhite(pngIcon), SwingConstants.LEFT)
                : new JLabel(fallbackEmoji + "  " + cardTitle);
        cardTitleLabel.setIconTextGap(8);
        cardTitleLabel.setFont(cardTitleLabel.getFont().deriveFont(Font.BOLD, 14f));
        cardTitleLabel.setForeground(MR_TEXT);
        card.add(cardTitleLabel, tc);
        return card;
    }

