    private void makeRectangularAccountButton(JButton button) {
        button.setUI(new javax.swing.plaf.basic.BasicButtonUI() {
            @Override public void paint(Graphics g, JComponent c) {
                Graphics2D g2 = (Graphics2D) g.create();
                ButtonModel model = ((JButton) c).getModel();
                Color fill = model.isPressed() ? new Color(24, 26, 31)
                        : model.isRollover() ? new Color(50, 53, 60) : MR_CARD;
                g2.setColor(fill);
                g2.fillRect(0, 0, c.getWidth(), c.getHeight());
                g2.setColor(MR_BORDER);
                g2.drawRect(0, 0, Math.max(0, c.getWidth() - 1), Math.max(0, c.getHeight() - 1));
                super.paint(g2, c);
                g2.dispose();
            }
        });
        button.setOpaque(false);
        button.setContentAreaFilled(false);
        button.setBorderPainted(false);
        button.setFocusPainted(false);
        button.setRolloverEnabled(true);
        button.setForeground(MR_TEXT);
        button.setFont(button.getFont().deriveFont(Font.PLAIN, 13f));
        button.setBorder(BorderFactory.createEmptyBorder(9, 18, 9, 18));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
        if (Boolean.TRUE.equals(button.getClientProperty("msc.systemFont"))) {
            applySystemFont(button);
        }
    }

    /**
     * Re-styles an existing {@link JButton} to match {@link PillActionButton}'s dark pill look
     * without replacing the button instance (so existing listeners are preserved).
     */
    private void makePillButton(JButton button, boolean primary) {
        button.setUI(new javax.swing.plaf.basic.BasicButtonUI() {
            @Override public void paint(Graphics g, JComponent c) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                int arc = c.getHeight();
                ButtonModel model = ((JButton) c).getModel();
                Color fill;
                if (primary) {
                    fill = model.isPressed() ? MR_ACCENT.darker()
                            : model.isRollover() ? new Color(Math.min(255, MR_ACCENT.getRed()+14), Math.min(255, MR_ACCENT.getGreen()+14), Math.min(255, MR_ACCENT.getBlue()+14))
                              : MR_ACCENT;
                } else {
                    fill = model.isPressed() ? new Color(20, 22, 26)
                            : model.isRollover() ? new Color(50, 53, 60)
                              : MR_CARD;
                }
                // Clip to pill shape so no square corners can bleed through
                g2.setClip(new java.awt.geom.RoundRectangle2D.Float(0, 0, c.getWidth(), c.getHeight(), arc, arc));
                g2.setColor(fill);
                g2.fill(new java.awt.geom.RoundRectangle2D.Float(0, 0, c.getWidth(), c.getHeight(), arc, arc));
                g2.setColor(MR_BORDER);
                g2.draw(new java.awt.geom.RoundRectangle2D.Float(0.5f, 0.5f, c.getWidth()-1f, c.getHeight()-1f, arc, arc));
                super.paint(g2, c);
                g2.dispose();
            }
        });
        button.setOpaque(false);
        button.setContentAreaFilled(false);
        button.setBorderPainted(false);
        button.setFocusPainted(false);
        button.setRolloverEnabled(true);
        button.setForeground(primary ? new Color(18, 20, 22) : MR_TEXT);
        button.setFont(button.getFont().deriveFont(primary ? Font.BOLD : Font.PLAIN, 13f));
        button.setBorder(BorderFactory.createEmptyBorder(9, 18, 9, 18));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.putClientProperty("msc.pillStyle", Boolean.TRUE);
        if (Boolean.TRUE.equals(button.getClientProperty("msc.systemFont"))) {
            applySystemFont(button);
        }
    }

