    /** Builds a single "Java N location" block: title, path field + status indicator, and a row
     *  of Install recommended / Detect / Browse buttons — mirrors the reference layout. */
    private JPanel buildJavaVersionRow(int major, JTextField field, JLabel statusLabel) {
        JPanel block = transparentPanel(new BorderLayout(0, 6));
        block.setAlignmentX(Component.LEFT_ALIGNMENT);
        block.setBorder(BorderFactory.createEmptyBorder(4, 0, 14, 0));

        JLabel title = new JLabel(nr("Java " + major + " location", "Путь к Java " + major));
        title.setForeground(MR_TEXT);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 13f));
        block.add(title, BorderLayout.NORTH);

        JPanel fieldRow = transparentPanel(new BorderLayout(8, 0));
        field.setToolTipText("/path/to/java");
        fieldRow.add(field, BorderLayout.CENTER);
        statusLabel.setHorizontalAlignment(SwingConstants.CENTER);
        statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 14f));
        statusLabel.setPreferredSize(new Dimension(26, 26));
        fieldRow.add(statusLabel, BorderLayout.EAST);

        JPanel buttonsRow = transparentPanel(new FlowLayout(FlowLayout.LEFT, 8, 8));
        JButton installBtn = new JButton(nr("Install recommended", "Установить рекомендуемую"));
        installBtn.addActionListener(e -> installRecommendedJava(major, field, statusLabel));
        JButton detectBtn = new JButton(nr("Detect", "Найти"));
        detectBtn.addActionListener(e -> detectLocalJava(major, field, statusLabel));
        JButton browseBtn = new JButton(nr("Browse", "Обзор"));
        browseBtn.addActionListener(e -> {
            choosePath(field, false);
            saveJavaPathField(major, field);
            updateJavaStatus(major, field, statusLabel);
        });
        buttonsRow.add(installBtn);
        buttonsRow.add(detectBtn);
        buttonsRow.add(browseBtn);

        JPanel middle = transparentPanel(new BorderLayout(0, 4));
        middle.add(fieldRow, BorderLayout.NORTH);
        middle.add(buttonsRow, BorderLayout.SOUTH);
        block.add(middle, BorderLayout.CENTER);
        return block;
    }

    private void applyJavaPathField(int major, JTextField field) {
        String text = field.getText().trim();
        settings.setJavaPathForMajor(major, text.isEmpty() ? null : java.nio.file.Path.of(text));
    }

    private void saveJavaPathField(int major, JTextField field) {
        applyJavaPathField(major, field);
        settings.save();
    }

    /** Refreshes the green check / red cross indicator next to a Java path field. */
    private void updateJavaStatus(int major, JTextField field, JLabel statusLabel) {
        String text = field.getText().trim();
        if (text.isEmpty()) {
            statusLabel.setText("");
            statusLabel.setToolTipText(null);
            return;
        }
        java.nio.file.Path path;
        try {
            path = java.nio.file.Path.of(text);
        } catch (RuntimeException ex) {
            statusLabel.setText("✕");
            statusLabel.setForeground(new Color(235, 90, 90));
            statusLabel.setToolTipText(nr("Invalid path", "Некорректный путь"));
            return;
        }
        int detected = javaRuntimeService.detectMajor(path);
        if (detected == major) {
            statusLabel.setText("✓");
            statusLabel.setForeground(new Color(70, 200, 120));
            statusLabel.setToolTipText(nr("Valid Java ", "Корректная установка Java ") + major);
        } else {
            statusLabel.setText("✕");
            statusLabel.setForeground(new Color(235, 90, 90));
            statusLabel.setToolTipText(detected > 0
                    ? nr("This points to Java ", "Здесь установлена Java ") + detected
                    : nr("Java executable not found here", "Java не найдена по этому пути"));
        }
    }

    private void refreshJavaInstallationStatuses() {
        updateJavaStatus(25, javaPath25Field, javaPath25Status);
        updateJavaStatus(21, javaPath21Field, javaPath21Status);
        updateJavaStatus(17, javaPath17Field, javaPath17Status);
        updateJavaStatus(8, javaPath8Field, javaPath8Status);
    }

    private void installRecommendedJava(int major, JTextField field, JLabel statusLabel) {
        runTask(nr("Installing Java ", "Установка Java ") + major,
                () -> javaRuntimeService.installRecommended(major, settings, uiProgress()),
                result -> {
                    if (result instanceof java.nio.file.Path installedPath) {
                        field.setText(installedPath.toString());
                        saveJavaPathField(major, field);
                        updateJavaStatus(major, field, statusLabel);
                    }
                });
    }

    private void detectLocalJava(int major, JTextField field, JLabel statusLabel) {
        runTask(nr("Detecting Java ", "Поиск Java ") + major,
                () -> javaRuntimeService.detectLocal(major, settings),
                result -> {
                    if (result instanceof java.nio.file.Path foundPath) {
                        field.setText(foundPath.toString());
                        saveJavaPathField(major, field);
                        updateJavaStatus(major, field, statusLabel);
                    } else {
                        updateJavaStatus(major, field, statusLabel);
                        JOptionPane.showMessageDialog(this,
                                nr("No local Java ", "Локальная установка Java ") + major
                                        + nr(" installation was found on this computer.", " не найдена на этом компьютере."),
                                nr("Detect Java", "Поиск Java"), JOptionPane.INFORMATION_MESSAGE);
                    }
                });
    }

    private JPanel buildMemorySection() {
        JPanel card = settingsCard("set_storage.png", "💾", t("label.memoryJvm"));
        GridBagConstraints tc = baseConstraints();

        ensureMemorySliderBindings();

        tc.gridx = 0; tc.gridy = 1; tc.gridwidth = 3; tc.fill = GridBagConstraints.HORIZONTAL;
        JLabel xmsLabel = new JLabel(t("label.xmsMemory"));
        xmsLabel.setForeground(TEXT_SECONDARY);
        xmsLabel.setFont(xmsLabel.getFont().deriveFont(Font.PLAIN, 12f));
        card.add(xmsLabel, tc);

        tc = baseConstraints(); tc.gridx = 0; tc.gridy = 2; tc.gridwidth = 3;
        tc.fill = GridBagConstraints.HORIZONTAL; tc.weightx = 1.0;
        card.add(minMemorySlider, tc);

        tc = baseConstraints(); tc.gridx = 0; tc.gridy = 3; tc.gridwidth = 3;
        tc.fill = GridBagConstraints.HORIZONTAL;
        tc.insets = new Insets(14, 0, 0, 0);
        JLabel xmxLabel = new JLabel(t("label.xmxMemory"));
        xmxLabel.setForeground(TEXT_SECONDARY);
        xmxLabel.setFont(xmxLabel.getFont().deriveFont(Font.PLAIN, 12f));
        card.add(xmxLabel, tc);

        tc = baseConstraints(); tc.gridx = 0; tc.gridy = 4; tc.gridwidth = 3;
        tc.fill = GridBagConstraints.HORIZONTAL; tc.weightx = 1.0;
        card.add(maxMemorySlider, tc);

        return wrapCard(card);
    }

    private void ensureMemorySliderBindings() {
        if (memorySlidersBound) {
            return;
        }
        memorySlidersBound = true;
        // Sliders drive the existing spinners so save/load code stays unchanged.
        minMemorySlider.addChangeListener(v -> minMemorySpinner.setValue(v));
        maxMemorySlider.addChangeListener(v -> maxMemorySpinner.setValue(v));
        minMemorySpinner.addChangeListener(e -> {
            int v = ((Number) minMemorySpinner.getValue()).intValue();
            if (minMemorySlider.getValue() != v) {
                minMemorySlider.setValue(v);
            }
        });
        maxMemorySpinner.addChangeListener(e -> {
            int v = ((Number) maxMemorySpinner.getValue()).intValue();
            if (maxMemorySlider.getValue() != v) {
                maxMemorySlider.setValue(v);
            }
        });
    }

