    private JPanel buildLauncherChangelogPanel() {
        JPanel panel = transparentPanel(new BorderLayout(0, 6));
        JLabel title = new JLabel(t("label.latestChangelog"));
        title.setFont(title.getFont().deriveFont(Font.BOLD, 12f));
        panel.add(title, BorderLayout.NORTH);

        launcherChangelogPane.setEditable(false);
        launcherChangelogPane.setOpaque(false);
        launcherChangelogPane.setText(changelogHtml(t("message.loadingChangelog")));
        launcherChangelogPane.setCaretPosition(0);
        launcherChangelogPane.addHyperlinkListener(e -> {
            if (e.getEventType() == javax.swing.event.HyperlinkEvent.EventType.ACTIVATED
                    && e.getURL() != null) {
                BrowserUtil.openUrl(e.getURL().toString());
            }
        });
        styleEditorPane(launcherChangelogPane);
        launcherChangelogScroll.setPreferredSize(new Dimension(420, 150));
        launcherChangelogScroll.setMinimumSize(new Dimension(260, 110));
        launcherChangelogScroll.setOpaque(false);
        launcherChangelogScroll.getViewport().setOpaque(false);
        launcherChangelogScroll.setBorder(BorderFactory.createLineBorder(BORDER));
        panel.add(launcherChangelogScroll, BorderLayout.CENTER);
        loadLatestLauncherChangelog();
        return panel;
    }

    private void loadLatestLauncherChangelog() {
        launcherChangelogPane.setText(changelogHtml(t("message.loadingChangelog")));
        launcherChangelogPane.setCaretPosition(0);
        new SwingWorker<GitHubUpdater.UpdateRelease, Void>() {
            @Override
            protected GitHubUpdater.UpdateRelease doInBackground() {
                GitHubUpdater.UpdateRelease release = GitHubUpdater.fetchLatestRelease(
                        new HttpService(), GitHubUpdater.detectPackageType());
                String notes = GitHubUpdater.translateReleaseNotes(
                        new HttpService(), release.description(), language());
                return new GitHubUpdater.UpdateRelease(
                        release.version(), release.pageUrl(), release.asset(), notes);
            }

            @Override
            protected void done() {
                try {
                    GitHubUpdater.UpdateRelease release = get();
                    String notes = release.description() == null || release.description().isBlank()
                            ? t("message.noChangelog")
                            : release.description();
                    launcherChangelogPane.setText(changelogHtml(
                            t("label.latestRelease") + " " + release.version() + "\n\n" + notes
                                    + "\n\n" + release.pageUrl()));
                } catch (Exception ex) {
                    launcherChangelogPane.setText(changelogHtml(t("message.changelogUnavailable")));
                }
                launcherChangelogPane.setCaretPosition(0);
            }
        }.execute();
    }

    private String changelogHtml(String text) {
        String escaped = escapeChangelogHtml(text == null ? "" : text)
                .replace("\r\n", "\n")
                .replace("\n", "<br>");
        return "<html><body style='font-family:Dialog,Segoe UI,sans-serif;font-size:11px;color:#eef2f8;background:transparent;'>"
                + escaped + "</body></html>";
    }

    private static String escapeChangelogHtml(String text) {
        return text.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;");
    }

