    /** Wraps a settings card so it aligns to the left within the scrollable right-hand pane. */
    private JPanel wrapCard(JPanel card) {
        // Use a panel that fills the full viewport width (no clipping on the right)
        JPanel column = new JPanel(new BorderLayout());
        column.setOpaque(false);
        column.add(card, BorderLayout.NORTH);
        JPanel padded = new JPanel(new BorderLayout());
        padded.setOpaque(false);
        padded.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
        padded.add(column, BorderLayout.CENTER);
        return padded;
    }

    private JTabbedPane buildTabs() {
        JTabbedPane tabs = new JTabbedPane();
        tabs.setOpaque(false);
        tabs.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        tabs.setFont(tabs.getFont().deriveFont(Font.BOLD, 12f));
        tabs.setUI(new BasicTabbedPaneUI() {
            @Override
            protected void paintContentBorder(Graphics g, int tabPlacement, int selectedIndex) {
                // Keep the tab content area transparent so the wallpaper remains visible.
            }

            @Override
            protected void paintFocusIndicator(Graphics g, int tabPlacement, Rectangle[] rects, int tabIndex,
                                               Rectangle iconRect, Rectangle textRect, boolean isSelected) {
                // The selected tab background is enough focus feedback in this compact launcher UI.
            }

            @Override
            protected void paintTabBackground(Graphics g, int tabPlacement, int tabIndex, int x, int y, int w, int h,
                                              boolean isSelected) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                // Solid light-gray background for tabs (selected and unselected)
                g2.setColor(SURFACE_SOLID);
                g2.fillRoundRect(x + 4, y + 4, w - 8, h - 6, 12, 12);
                if (isSelected) {
                    // keep small accent bar for the selected tab
                    g2.setColor(ACCENT);
                    g2.fillRoundRect(x + 14, y + h - 5, w - 28, 3, 3, 3);
                }
                g2.dispose();
            }

            @Override
            protected void paintText(Graphics g, int tabPlacement, Font font, FontMetrics metrics, int tabIndex,
                                     String title, Rectangle textRect, boolean isSelected) {
                g.setFont(font);
                // Use primary text color for readability on solid gray background
                g.setColor(TEXT_PRIMARY);
                g.drawString(title, textRect.x, textRect.y + metrics.getAscent());
            }

            @Override
            protected int calculateTabHeight(int tabPlacement, int tabIndex, int fontHeight) {
                return super.calculateTabHeight(tabPlacement, tabIndex, fontHeight) + 2;
            }

            @Override
            protected int calculateTabWidth(int tabPlacement, int tabIndex, FontMetrics metrics) {
                return super.calculateTabWidth(tabPlacement, tabIndex, metrics) + 12;
            }
        });
        tabs.addTab(t("tab.play"), buildPlayPanel());
        // Skins panel moved into Settings tab (do not add top-level skins tab)
        // tabs.addTab(t("tab.skins"), buildSkinsPanel());
        tabs.addTab(t("tab.settings"), buildSettingsPanel());
        tabs.addTab(t("tab.log"), buildLogPanel());
        return tabs;
    }

