    private void configureModSourceButton(JToggleButton button, String source, String... icons) {
        button.setToolTipText(source);
        button.getAccessibleContext().setAccessibleName(source);
        button.setIcon(LauncherAssets.readScaledIcon(settings.gameDirectory(), 28, 28, icons));
        button.addActionListener(e -> {
            if (!source.equals(modSourceCombo.getSelectedItem())) {
                modSourceCombo.setSelectedItem(source);
            }
        });
    }

