    /** Builds the Modrinth-style pill-tab row for content type selection. */
    private JPanel buildModTypePillRow() {
        AnimatedPillTabRow row = new AnimatedPillTabRow(6, 8);
        row.setBorder(BorderFactory.createEmptyBorder(0, 14, 0, 14));
        String[] labels = {"Mods", "Modpacks", "Resource Packs", "Data Packs", "Shaders"};
        PillTabButton activeButton = null;
        for (int i = 0; i < MOD_TYPE_KEYS.length; i++) {
            final String key = MOD_TYPE_KEYS[i];
            // Same PillTabButton used for the "All instances" / "Modpacks" tabs in the
            // library screen: it fully owns its own paint/opacity and is tagged with
            // msc.keepDefaultStyle, so global theme restyling passes (styleComponentTree /
            // applyDarkTranslucentTheme) can never clobber it back to a plain white square,
            // in either the light or the dark theme.
            PillTabButton pill = new PillTabButton(labels[i]);
            pill.putClientProperty("msc.externalActiveIndicator", Boolean.TRUE);
            boolean active = key.equals(modContentTypeCombo.getSelectedItem());
            pill.setActive(active);
            if (active) {
                activeButton = pill;
            }
            pill.addActionListener(e -> {
                modContentTypeCombo.setSelectedItem(key);
                updateModTypePillActiveStates();
                reloadModCatalogFromFirstPage();
            });
            modTypePillButtons[i] = pill;
            row.add(pill);
        }
        if (activeButton != null) {
            row.setActiveButton(activeButton, false);
        }
        return row;
    }

    /** Syncs each mod-type pill's active/inactive paint state with the current selection. */
    private void updateModTypePillActiveStates() {
        for (int i = 0; i < MOD_TYPE_KEYS.length; i++) {
            JButton b = modTypePillButtons[i];
            if (b instanceof PillTabButton pillButton) {
                pillButton.setActive(MOD_TYPE_KEYS[i].equals(modContentTypeCombo.getSelectedItem()));
                if (pillButton.isActive() && pillButton.getParent() instanceof AnimatedPillTabRow animatedRow) {
                    animatedRow.setActiveButton(pillButton, true);
                }
            }
        }
        updateModTargetProfileVisibility();
    }

    private void updateModTargetProfileVisibility() {
        boolean visible = !"Modpacks".equals(modContentTypeCombo.getSelectedItem());
        modTargetProfileLabel.setVisible(visible);
        modTargetProfileCombo.setVisible(visible);
        Container parent = modTargetProfileCombo.getParent();
        if (parent != null) {
            parent.revalidate();
            parent.repaint();
        }
    }

    /**
     * Shows/hides DataPacks and Shaders pills depending on the selected mod source.
     * CurseForge doesn't support these content types, so we hide them there.
     * Indices: 0=Mods, 1=Modpacks, 2=ResourcePacks, 3=DataPacks, 4=Shaders
     */
    private void updateModTypePillsForSource() {
        boolean isCurseForge = "CurseForge".equals(modSourceCombo.getSelectedItem());
        // DataPacks = index 3, Shaders = index 4
        for (int i = 3; i <= 4; i++) {
            if (modTypePillButtons[i] != null) {
                modTypePillButtons[i].setVisible(!isCurseForge);
            }
        }
        // If current selection is one of the hidden types, switch to Mods
        if (isCurseForge) {
            String current = (String) modContentTypeCombo.getSelectedItem();
            if ("DataPacks".equals(current) || "Shaders".equals(current)) {
                modContentTypeCombo.setSelectedItem("Mods");
                updateModTypePillActiveStates();
            }
        }
    }

    /** Builds the beautiful in-panel install overlay (version + loader picker). */
    private JPanel buildModInstallOverlay() {
        installVersionModel = new DefaultListModel<>();
        installVersionList = new JList<>(installVersionModel);
        installVersionList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        installVersionList.setOpaque(false);
        installVersionList.setForeground(MR_TEXT);
        installVersionList.setFont(installVersionList.getFont().deriveFont(14f));
        installVersionList.setFixedCellHeight(32);
        installVersionList.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int idx, boolean sel, boolean focus) {
                JLabel lbl = (JLabel) super.getListCellRendererComponent(list, value, idx, sel, focus);
                lbl.setBorder(BorderFactory.createEmptyBorder(4, 12, 4, 12));
                lbl.setOpaque(true);
                if (sel) {
                    lbl.setBackground(MR_ACCENT);
                    lbl.setForeground(Color.WHITE);
                } else {
                    lbl.setBackground(idx % 2 == 0 ? MR_CARD : (MR_LIGHT_ACTIVE ? new Color(218, 220, 228) : new Color(38, 38, 44)));
                    lbl.setForeground(MR_TEXT);
                }
                return lbl;
            }
        });

        installLoaderCombo = new SupportedLoaderComboBox();
        installLoaderCombo.installCompatibilityRenderer();
        installVersionList.addListSelectionListener(e -> {
            if (!e.getValueIsAdjusting()) {
                refreshInstallOverlayLoaderChoices(installLoaderCombo.selectedLoader());
            }
        });

        // Keep this action identical to the install action on the project card.
        installConfirmButton = new DownloadArrowButton();
        installConfirmButton.setToolTipText(t("button.install"));

        installCancelButton = new JButton(t("button.cancel")) {
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(getModel().isPressed() ? MR_CARD.darker() : getModel().isRollover() ? (MR_LIGHT_ACTIVE ? new Color(210, 212, 220) : new Color(55,55,62)) : MR_CARD);
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 16, 16);
                g2.setColor(MR_BORDER);
                g2.drawRoundRect(0, 0, getWidth()-1, getHeight()-1, 16, 16);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        installCancelButton = modernIcon(installCancelButton, "btn_install_cancel");
        installCancelButton.setForeground(MR_TEXT);
        installCancelButton.setFont(installCancelButton.getFont().deriveFont(Font.BOLD, 13f));
        installCancelButton.setOpaque(false);
        installCancelButton.setContentAreaFilled(false);
        installCancelButton.setBorderPainted(false);
        installCancelButton.setFocusPainted(false);
        installCancelButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        installCancelButton.setBorder(BorderFactory.createEmptyBorder(10, 20, 10, 20));

        // The overlay card itself
        JPanel overlay = new JPanel() {
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                // Dark scrim behind card
                g2.setColor(new Color(0, 0, 0, 160));
                g2.fillRect(0, 0, getWidth(), getHeight());
                g2.dispose();
            }
            @Override public boolean isOpaque() { return false; }
        };
        overlay.setLayout(new GridBagLayout()); // centers the inner card

        JPanel card = new JPanel(new BorderLayout(0, 14)) {
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(MR_LIGHT_ACTIVE ? new Color(255, 255, 255, 250) : new Color(28, 28, 33, 245));
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 24, 24);
                g2.setColor(MR_BORDER);
                g2.drawRoundRect(0, 0, getWidth()-1, getHeight()-1, 24, 24);
                g2.dispose();
            }
            @Override public boolean isOpaque() { return false; }
        };
        card.setBorder(BorderFactory.createEmptyBorder(24, 24, 20, 24));
        card.setPreferredSize(new Dimension(440, 360));

        JLabel titleLbl = new JLabel(t("dialog.chooseMinecraftVersion"));
        titleLbl.setFont(titleLbl.getFont().deriveFont(Font.BOLD, 18f));
        titleLbl.setForeground(MR_TEXT);
        installProjectTitleLabel = new JLabel();
        installProjectTitleLabel.setForeground(MR_TEXT_DIM);
        installProjectTitleLabel.setFont(installProjectTitleLabel.getFont().deriveFont(13f));
        JPanel headerPnl = transparentPanel(new GridLayout(2, 1, 0, 4));
        headerPnl.add(titleLbl);
        headerPnl.add(installProjectTitleLabel);
        card.add(headerPnl, BorderLayout.NORTH);

        JScrollPane vScroll = new JScrollPane(installVersionList);
        vScroll.setOpaque(false);
        vScroll.getViewport().setOpaque(false);
        vScroll.setBorder(BorderFactory.createLineBorder(MR_BORDER, 1, true));
        card.add(vScroll, BorderLayout.CENTER);

        JPanel south = transparentPanel(new BorderLayout(0, 10));
        JPanel loaderRow = transparentPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
        JLabel loaderLbl = new JLabel(t("label.loader") + ":");
        loaderLbl.setForeground(MR_TEXT_DIM);
        loaderRow.add(loaderLbl);
        loaderRow.add(installLoaderCombo);
        south.add(loaderRow, BorderLayout.NORTH);
        JPanel btnRow = transparentPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0));
        btnRow.add(installCancelButton);
        btnRow.add(installConfirmButton);
        south.add(btnRow, BorderLayout.SOUTH);
        card.add(south, BorderLayout.SOUTH);

        GridBagConstraints gc = new GridBagConstraints();
        gc.fill = GridBagConstraints.NONE;
        gc.anchor = GridBagConstraints.CENTER;
        overlay.add(card, gc);

        installCancelButton.addActionListener(e -> hideModInstallOverlay());
        installConfirmButton.addActionListener(e -> {
            hideModInstallOverlay();
            if (pendingInstallAction != null) pendingInstallAction.run();
        });
        overlay.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(
                KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "closeModInstallOverlay");
        overlay.getActionMap().put("closeModInstallOverlay", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) {
                hideModInstallOverlay();
            }
        });
        overlay.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(
                KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "confirmModInstallOverlay");
        overlay.getActionMap().put("confirmModInstallOverlay", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) {
                if (installConfirmButton != null && installConfirmButton.isEnabled()) {
                    installConfirmButton.doClick();
                }
            }
        });
        return overlay;
    }

    private void showModInstallOverlay(String title, ModInstallCompatibility compatibility,
                                       String preferredVersion,
                                       boolean showLoader, String currentLoader, Runnable onConfirm) {
        if (modInstallOverlayPanel == null) return;
        activeInstallCompatibility = compatibility == null
                ? ModInstallCompatibility.builder().build() : compatibility;
        activeInstallShowsLoader = showLoader;
        if (installProjectTitleLabel != null) {
            installProjectTitleLabel.setText(ui("Installing: ", "Установка: ", "Installation : ",
                    "Installazione: ", "インストール: ", "Instalare: ", "正在安装：")
                    + (title == null ? "" : title));
        }
        List<String> versions = activeInstallCompatibility.gameVersions();
        // populate version list
        installVersionModel.removeAllElements();
        for (String v : versions) installVersionModel.addElement(v);
        int prefIdx = versions.indexOf(preferredVersion);
        installVersionList.setSelectedIndex(prefIdx >= 0 ? prefIdx : 0);
        installVersionList.ensureIndexIsVisible(installVersionList.getSelectedIndex());
        // populate loader
        installLoaderCombo.setVisible(showLoader);
        installLoaderCombo.getParent().setVisible(showLoader);
        if (showLoader) {
            refreshInstallOverlayLoaderChoices(currentLoader);
        }
        // override confirm listener (remove old ones first)
        for (java.awt.event.ActionListener al : installConfirmButton.getActionListeners()) {
            installConfirmButton.removeActionListener(al);
        }
        installConfirmButton.addActionListener(e -> {
            String chosenVersion = installVersionList.getSelectedValue();
            String chosenLoader = showLoader ? installLoaderCombo.selectedLoader() : "";
            lastOverlayChosenVersion = chosenVersion == null ? "" : chosenVersion;
            lastOverlayChosenLoader  = chosenLoader;
            hideModInstallOverlay();
            if (!lastOverlayChosenVersion.isBlank()) onConfirm.run();
        });
        // make overlay fill the layered pane and show it on top
        if (modInstallLayeredPane != null) {
            modInstallOverlayPanel.setBounds(0, 0,
                    modInstallLayeredPane.getWidth(), modInstallLayeredPane.getHeight());
        }
        modInstallOverlayPanel.setVisible(true);
        setModInstallOverlayBlocked(true);
        if (modInstallLayeredPane != null) {
            modInstallLayeredPane.revalidate();
            modInstallLayeredPane.repaint();
        }
        SwingUtilities.invokeLater(() -> installVersionList.requestFocusInWindow());
    }

    private void refreshInstallOverlayLoaderChoices(String preferredLoader) {
        if (installLoaderCombo == null || !activeInstallShowsLoader) {
            if (installConfirmButton != null) {
                installConfirmButton.setEnabled(true);
            }
            return;
        }
        String version = installVersionList == null ? "" : installVersionList.getSelectedValue();
        installLoaderCombo.setChoices(activeInstallCompatibility.loaderChoices(version), preferredLoader);
        if (installConfirmButton != null) {
            installConfirmButton.setEnabled(installLoaderCombo.hasSupportedLoader());
        }
    }

    private void hideModInstallOverlay() {
        if (modInstallOverlayPanel != null) {
            modInstallOverlayPanel.setVisible(false);
            setModInstallOverlayBlocked(false);
            if (modInstallLayeredPane != null) {
                modInstallLayeredPane.repaint();
            }
        }
    }

    private void setModInstallOverlayBlocked(boolean blocked) {
        boolean enabled = !blocked && !launcherBusy;
        modSearchResults.setEnabled(enabled);
        modSourceCombo.setEnabled(enabled);
        modContentTypeCombo.setEnabled(enabled);
        modGameVersionCombo.setEnabled(enabled);
        modLoaderCombo.setEnabled(enabled && modContentNeedsLoader());
        modTargetProfileCombo.setEnabled(enabled);
        if (blocked) {
            installModButton.setEnabled(false);
        } else {
            boolean modrinth = "Modrinth".equals(modSourceCombo.getSelectedItem());
            boolean curseforge = "CurseForge".equals(modSourceCombo.getSelectedItem());
            installModButton.setEnabled(enabled && (modrinth
                    || (curseforge && curseForgeService != null && curseForgeService.isConfigured())));
        }
    }

    private boolean modContentNeedsLoader() {
        String type = String.valueOf(modContentTypeCombo.getSelectedItem());
        return !"Modpacks".equals(type) && !"ResourcePacks".equals(type)
                && !"DataPacks".equals(type) && !"Shaders".equals(type);
    }

