        c.gridy = row;
        panel.add(new JLabel(label), c);

        c.gridx = 1;
        c.weightx = 1;
        c.fill = GridBagConstraints.HORIZONTAL;
        panel.add(field, c);

        c.gridx = 2;
        c.weightx = 0;
        c.fill = GridBagConstraints.NONE;
        JButton button = new JButton(buttonText);
        button.addActionListener(e -> choosePath(field, directoriesOnly));
        panel.add(button, c);
