    private void installOverlayLayer() {
        overlayLayer = new OverlayLayer();
        overlayLayer.setVisible(false);
        getLayeredPane().add(overlayLayer, JLayeredPane.POPUP_LAYER);
        getLayeredPane().addComponentListener(new java.awt.event.ComponentAdapter() {
            @Override
            public void componentResized(java.awt.event.ComponentEvent e) {
                if (overlayLayer != null) {
                    overlayLayer.setBounds(0, 0, getLayeredPane().getWidth(), getLayeredPane().getHeight());
                    overlayLayer.relayoutContent();
                }
            }
        });
        overlayLayer.setBounds(0, 0, getLayeredPane().getWidth(), getLayeredPane().getHeight());
    }

