    /**
     * Windows 8.1 Update and Windows 10 reveal a compact close bar when the
     * pointer touches the top edge of a full-screen Store application.
     */
    private void installMetroSystemTitleBar(JLayeredPane layers) {
        metroTopRevealStrip = new JPanel();
        metroTopRevealStrip.setOpaque(false);
        metroTopRevealStrip.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { setMetroSystemTitleBarOpen(true); }
            @Override public void mouseExited(MouseEvent e) { scheduleMetroSystemTitleBarClose(); }
        });

        metroSystemTitleBar = new JPanel(new BorderLayout()) {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setPaint(new GradientPaint(0, 0, new Color(250, 250, 250),
                        0, getHeight(), new Color(225, 225, 225)));
                g2.fillRect(0, 0, getWidth(), getHeight());
                g2.setColor(new Color(145, 145, 145));
                g2.drawLine(0, getHeight() - 1, getWidth(), getHeight() - 1);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        metroSystemTitleBar.setOpaque(false);
        metroSystemTitleBar.setBorder(BorderFactory.createEmptyBorder(0, 12, 0, 0));
        MouseAdapter titleBarHover = new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { setMetroSystemTitleBarOpen(true); }
            @Override public void mouseExited(MouseEvent e) { scheduleMetroSystemTitleBarClose(); }
        };
        metroSystemTitleBar.addMouseListener(titleBarHover);

        JLabel title = new JLabel(LauncherEdition.current().displayName());
        title.setForeground(new Color(32, 32, 32));
        title.setFont(title.getFont().deriveFont(Font.PLAIN, 12f));
        title.addMouseListener(titleBarHover);
        metroSystemTitleBar.add(title, BorderLayout.CENTER);

        JButton close = new JButton("×");
        close.setToolTipText(ui("Close", "Закрыть", "Fermer", "Chiudi", "閉じる", "Închide", "关闭"));
        close.setPreferredSize(new Dimension(48, 32));
        close.setForeground(new Color(35, 35, 35));
        close.setBackground(new Color(235, 235, 235));
        close.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 22));
        close.setFocusable(false);
        close.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
        close.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        close.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) {
                setMetroSystemTitleBarOpen(true);
                close.setBackground(new Color(232, 17, 35));
                close.setForeground(Color.WHITE);
            }

            @Override public void mouseExited(MouseEvent e) {
                close.setBackground(new Color(235, 235, 235));
                close.setForeground(new Color(35, 35, 35));
                scheduleMetroSystemTitleBarClose();
            }
        });
        close.addActionListener(e -> dispatchEvent(
                new WindowEvent(this, WindowEvent.WINDOW_CLOSING)));
        metroSystemTitleBar.add(close, BorderLayout.EAST);

        layers.add(metroTopRevealStrip, JLayeredPane.DRAG_LAYER);
        layers.add(metroSystemTitleBar, JLayeredPane.DRAG_LAYER);
        layers.moveToFront(metroTopRevealStrip);
        layers.moveToFront(metroSystemTitleBar);
    }

    private JButton metroNavButton(String text, String iconFile, String tooltip) {
        return metroNavButton(text, iconFile, tooltip, null);
    }

    private JButton metroNavButton(String text, String iconFile, String tooltip, Runnable action) {
        JButton button = new JButton(text);
        ImageIcon icon = iconFile == null ? null : loadMetroNavIcon(iconFile);
        if (icon != null) {
            button.setIcon(icon);
        }
        button.setToolTipText(tooltip);
        button.setPreferredSize(new Dimension(74, 58));
        button.setForeground(Color.WHITE);
        button.setFont(button.getFont().deriveFont(Font.BOLD, 30f));
        button.setFocusPainted(false);
        button.setBorder(BorderFactory.createEmptyBorder());
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (button.getParent() == metroEdgeNavPanel) {
                    setMetroEdgeNavOpen(true);
                }
            }

            @Override
            public void mouseExited(MouseEvent e) {
                if (button.getParent() == metroEdgeNavPanel) {
                    scheduleMetroEdgeNavClose();
                }
            }
        });
        button.setUI(new javax.swing.plaf.basic.BasicButtonUI() {
            @Override
            public void paint(Graphics g, JComponent c) {
                AbstractButton b = (AbstractButton) c;
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                ButtonModel model = b.getModel();
                Color fill = model.isPressed() ? new Color(10, 86, 132, 226)
                        : model.isRollover() ? new Color(36, 142, 204, 220)
                        : new Color(18, 80, 124, 198);
                int arc = 24;
                g2.setColor(new Color(0, 0, 0, 62));
                g2.fillRoundRect(3, 5, c.getWidth() - 6, c.getHeight() - 8, arc, arc);
                g2.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 92),
                        0, c.getHeight(), fill));
                g2.fillRoundRect(1, 1, c.getWidth() - 3, c.getHeight() - 4, arc, arc);
                g2.setColor(new Color(210, 246, 255, model.isRollover() ? 210 : 145));
                g2.drawRoundRect(1, 1, c.getWidth() - 4, c.getHeight() - 5, arc, arc);
                Icon icon = b.getIcon();
                if (icon != null) {
                    int ix = (c.getWidth() - icon.getIconWidth()) / 2;
                    int iy = (c.getHeight() - icon.getIconHeight()) / 2;
                    icon.paintIcon(c, g2, ix, iy);
                } else {
                    g2.setColor(b.isEnabled() ? Color.WHITE : new Color(255, 255, 255, 90));
                    g2.setFont(b.getFont());
                    FontMetrics fm = g2.getFontMetrics();
                    g2.drawString(b.getText(), (c.getWidth() - fm.stringWidth(b.getText())) / 2,
                            (c.getHeight() + fm.getAscent() - fm.getDescent()) / 2);
                }
                g2.dispose();
            }
        });
        if (action != null) {
            button.addActionListener(e -> action.run());
        }
        return button;
    }

    private ImageIcon loadMetroNavIcon(String filename) {
        BufferedImage source = LauncherAssets.readImage(settings.gameDirectory(), "nav/" + filename, filename);
        if (source == null) {
            return null;
        }
        int size = 42;
        BufferedImage rounded = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = rounded.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.setClip(new java.awt.geom.Ellipse2D.Float(0, 0, size, size));
        double scale = Math.min(size / (double) source.getWidth(), size / (double) source.getHeight());
        int drawW = Math.max(1, (int) Math.round(source.getWidth() * scale));
        int drawH = Math.max(1, (int) Math.round(source.getHeight() * scale));
        int dx = (size - drawW) / 2;
        int dy = (size - drawH) / 2;
        g2.drawImage(source, dx, dy, drawW, drawH, null);
        g2.dispose();
        return new ImageIcon(rounded);
    }

    private void updateMetroEdgeNavBounds() {
        if (metroHoverStrip == null || metroEdgeNavPanel == null) {
            return;
        }
        JLayeredPane layers = getLayeredPane();
        int w = layers.getWidth();
        int h = layers.getHeight();
        int panelW = 104;
        int panelH = 292;
        metroHoverStrip.setBounds(Math.max(0, w - 32), 0, 32, h);
        int x = metroEdgeNavOpen ? w - panelW - 12 : w - 2;
        metroEdgeNavPanel.setBounds(x, Math.max(20, h / 2 - panelH / 2), panelW, panelH);
        if (metroTopBackButton != null) {
            metroTopBackButton.setBounds(24, Math.max(92, h - 86), 54, 54);
        }
    }

    private void updateMetroSystemTitleBarBounds() {
        if (metroTopRevealStrip == null || metroSystemTitleBar == null) {
            return;
        }
        int width = getLayeredPane().getWidth();
        int barHeight = 32;
        metroTopRevealStrip.setBounds(0, 0, width, 4);
        metroSystemTitleBar.setBounds(0,
                metroSystemTitleBarOpen ? 0 : -barHeight, width, barHeight);
    }

    private void setMetroSystemTitleBarOpen(boolean open) {
        if (metroSystemTitleBar == null || metroSystemTitleBarOpen == open) {
            return;
        }
        if (open && metroSystemTitleBarCloseTimer != null) {
            metroSystemTitleBarCloseTimer.stop();
        }
        metroSystemTitleBarOpen = open;
        int start = metroSystemTitleBar.getY();
        int target = open ? 0 : -metroSystemTitleBar.getHeight();
        int animationId = ++metroSystemTitleBarAnimationId;
        runProgressAnimation(110, progress -> {
            if (animationId == metroSystemTitleBarAnimationId) {
                int y = start + (int) Math.round((target - start) * progress);
                metroSystemTitleBar.setLocation(0, y);
            }
        }, () -> {
            if (animationId == metroSystemTitleBarAnimationId) {
                metroSystemTitleBar.setLocation(0, target);
            }
        });
    }

    private void scheduleMetroSystemTitleBarClose() {
        if (metroSystemTitleBarCloseTimer != null) {
            metroSystemTitleBarCloseTimer.stop();
        }
        metroSystemTitleBarCloseTimer = new Timer(280, e -> {
            if (!isPointerOverMetroSystemTitleBar()) {
                setMetroSystemTitleBarOpen(false);
            }
            metroSystemTitleBarCloseTimer.stop();
        });
        metroSystemTitleBarCloseTimer.setRepeats(false);
        metroSystemTitleBarCloseTimer.start();
    }

    private boolean isPointerOverMetroSystemTitleBar() {
        try {
            Point pointer = MouseInfo.getPointerInfo().getLocation();
            return componentContainsScreenPoint(metroSystemTitleBar, pointer)
                    || componentContainsScreenPoint(metroTopRevealStrip, pointer);
        } catch (RuntimeException ex) {
            return false;
        }
    }

    private void setMetroEdgeNavOpen(boolean open) {
        if (metroEdgeNavPanel == null) {
            return;
        }
        if (open && metroEdgeNavCloseTimer != null && metroEdgeNavCloseTimer.isRunning()) {
            metroEdgeNavCloseTimer.stop();
        }
        metroEdgeNavOpen = open;
        JLayeredPane layers = getLayeredPane();
        int panelW = 104;
        int target = open ? layers.getWidth() - panelW - 12 : layers.getWidth() - 2;
        int start = metroEdgeNavPanel.getX();
        if (start == target) {
            return;
        }
        int animationId = ++metroEdgeNavAnimationId;
        runProgressAnimation(130, progress -> {
            if (animationId != metroEdgeNavAnimationId) {
                return;
            }
            int x = start + (int) Math.round((target - start) * progress);
            metroEdgeNavPanel.setLocation(x, metroEdgeNavPanel.getY());
        }, () -> {
            if (animationId == metroEdgeNavAnimationId) {
                metroEdgeNavPanel.setLocation(target, metroEdgeNavPanel.getY());
            }
        });
    }

    private void scheduleMetroEdgeNavClose() {
        if (metroEdgeNavCloseTimer != null && metroEdgeNavCloseTimer.isRunning()) {
            metroEdgeNavCloseTimer.stop();
        }
        metroEdgeNavCloseTimer = new Timer(220, e -> {
            if (!isPointerOverMetroEdgeNav()) {
                setMetroEdgeNavOpen(false);
            }
            metroEdgeNavCloseTimer.stop();
        });
        metroEdgeNavCloseTimer.setRepeats(false);
        metroEdgeNavCloseTimer.start();
    }

    private boolean isPointerOverMetroEdgeNav() {
        try {
            Point pointer = MouseInfo.getPointerInfo().getLocation();
            return componentContainsScreenPoint(metroEdgeNavPanel, pointer)
                    || componentContainsScreenPoint(metroHoverStrip, pointer);
        } catch (RuntimeException ex) {
            return false;
        }
    }

    private boolean componentContainsScreenPoint(Component component, Point screenPoint) {
        if (component == null || !component.isShowing()) {
            return false;
        }
        Point origin = component.getLocationOnScreen();
        Rectangle bounds = new Rectangle(origin.x, origin.y, component.getWidth(), component.getHeight());
        return bounds.contains(screenPoint);
    }

    private void updateMetroBackNavButton() {
        boolean overlayVisible = overlayLayer != null && overlayLayer.isVisible();
        boolean mainTilesVisible = SCREEN_MAIN.equals(currentScreen()) && !metroShowingParams && !settingsOverlayActive;
        boolean backVisible = isMetroUi()
                && !overlayVisible
                && !mainTilesVisible;
        if (metroBackNavButton != null) {
            metroBackNavButton.setVisible(backVisible);
            metroBackNavButton.setEnabled(backVisible);
            metroBackNavButton.repaint();
        }
        if (metroTopBackButton != null) {
            metroTopBackButton.setVisible(backVisible);
            metroTopBackButton.setEnabled(backVisible);
            metroTopBackButton.repaint();
        }
    }

    /**
     * Shows {@code content} centered in a rounded card, dimming the rest of the
     * window behind it. Use {@link #hideOverlay()} (or click outside / the
     * overlay's own close affordances) to dismiss it.
     */
    private void showOverlay(JComponent content, int preferredWidth, int preferredHeight) {
        if (overlayLayer == null) return;
        overlayLayer.setBounds(0, 0, getLayeredPane().getWidth(), getLayeredPane().getHeight());
        overlayLayer.showContent(content, preferredWidth, preferredHeight);
    }

    private void showFullscreenOverlay(JComponent content) {
        if (overlayLayer == null) return;
        overlayLayer.setBounds(0, 0, getLayeredPane().getWidth(), getLayeredPane().getHeight());
        overlayLayer.showFullscreenContent(content);
    }

    private void hideOverlay() {
        if (overlayLayer != null) {
            overlayLayer.hideContent();
        }
    }

    /**
     * Full-window glass pane: paints a dark scrim and centers a rounded card
     * containing whatever content is passed to {@link #showContent}.
     */
    private final class OverlayLayer extends JPanel {
        private final JPanel card = new JPanel(new BorderLayout());
        private boolean fullscreenContent;

        private OverlayLayer() {
            super(null); // manual positioning of the centered card
            setOpaque(false);
            card.setOpaque(false);
            card.setVisible(false);
            add(card);

            // Click on the scrim (outside the card) dismisses the overlay.
            addMouseListener(new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    if (!card.getBounds().contains(e.getPoint())) {
                        hideContent();
                    }
                }
            });
        }

        private void showContent(JComponent content, int preferredWidth, int preferredHeight) {
            fullscreenContent = false;
            card.removeAll();
            JPanel rounded = new RoundedCardPanel(
                    Boolean.TRUE.equals(content.getClientProperty("msc.classicGlassOverlay")));
            rounded.setLayout(new BorderLayout());
            rounded.add(content, BorderLayout.CENTER);
            card.add(rounded, BorderLayout.CENTER);
            int w = Math.min(preferredWidth, Math.max(320, getWidth() - 60));
            int h = Math.min(preferredHeight, Math.max(240, getHeight() - 60));
            card.setBounds((getWidth() - w) / 2, (getHeight() - h) / 2, w, h);
            card.setVisible(true);
            setVisible(true);
            revalidate();
            repaint();
            SwingUtilities.invokeLater(() -> {
                if (content.isFocusable()) content.requestFocusInWindow();
            });
        }

        private void showFullscreenContent(JComponent content) {
            fullscreenContent = true;
            card.removeAll();
            JPanel rounded = new RoundedCardPanel();
            rounded.setLayout(new BorderLayout());
            rounded.add(content, BorderLayout.CENTER);
            card.add(rounded, BorderLayout.CENTER);
            card.setVisible(true);
            relayoutContent();
            setVisible(true);
            revalidate();
            repaint();
            SwingUtilities.invokeLater(() -> {
                if (content.isFocusable()) content.requestFocusInWindow();
            });
        }

        private void relayoutContent() {
            if (!fullscreenContent) {
                return;
            }
            int margin = 16;
            int w = Math.max(320, getWidth() - margin * 2);
            int h = Math.max(240, getHeight() - margin * 2);
            card.setBounds(margin, margin, w, h);
        }

        private void hideContent() {
            fullscreenContent = false;
            instanceDetailsLaunchButton = null;
            setVisible(false);
            card.setVisible(false);
            card.removeAll();
            revalidate();
            repaint();
            // Если закрывался оверлей настроек (хоть через крестик, хоть кликом
            // мимо окна), возвращаем подсветку боковой панели на ту вкладку,
            // с которой настройки были открыты, а не оставляем её снятой.
            if (settingsOverlayActive) {
                settingsOverlayActive = false;
                setActiveSidebarButton(sidebarIndexBeforeSettings);
            }
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            if (!isVisible()) return;
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(8, 9, 11, 150));
            g2.fillRect(0, 0, getWidth(), getHeight());
            g2.dispose();
        }
    }

    /** Rounded, bordered surface used as the body of in-window overlay dialogs. Follows the active theme. */
    private static final class RoundedCardPanel extends JPanel {
        private static final int CARD_ARC = 30;
        private final boolean glass;

        private RoundedCardPanel() {
            this(false);
        }

        private RoundedCardPanel(boolean glass) {
            this.glass = glass;
            setOpaque(false);
            setBorder(BorderFactory.createEmptyBorder(3, 3, 3, 3));
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(0, 0, 0, MR_LIGHT_ACTIVE ? 35 : 90));
            g2.fill(new RoundRectangle2D.Float(2, 4, getWidth() - 4, getHeight() - 4, CARD_ARC, CARD_ARC));
            RoundRectangle2D.Float body = new RoundRectangle2D.Float(
                    0, 0, getWidth() - 2, getHeight() - 2, CARD_ARC, CARD_ARC);
            if (glass) {
                g2.setColor(new Color(
                        SURFACE_SOLID.getRed(), SURFACE_SOLID.getGreen(), SURFACE_SOLID.getBlue(), 178));
                g2.fill(body);
                Shape oldClip = g2.getClip();
                g2.clip(body);
                g2.setPaint(new GradientPaint(
                        0, 0, new Color(255, 255, 255, 34),
                        0, Math.max(1, getHeight() * 0.48f), new Color(255, 255, 255, 0)));
                g2.fillRect(0, 0, getWidth(), Math.max(1, getHeight() / 2));
                g2.setClip(oldClip);
                g2.setColor(new Color(205, 220, 240, 72));
            } else {
                g2.setColor(SURFACE_SOLID);
                g2.fill(body);
                g2.setColor(MR_LIGHT_ACTIVE ? new Color(0, 0, 0, 30) : new Color(180, 195, 220, 40));
            }
            g2.draw(new RoundRectangle2D.Float(
                    0.5f, 0.5f, getWidth() - 3f, getHeight() - 3f, CARD_ARC, CARD_ARC));
            g2.dispose();
            super.paintComponent(g);
        }

        @Override
        protected void paintChildren(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.clip(new RoundRectangle2D.Float(
                    1,
                    1,
                    Math.max(0, getWidth() - 3f),
                    Math.max(0, getHeight() - 3f),
                    CARD_ARC,
                    CARD_ARC
            ));
            super.paintChildren(g2);
            g2.dispose();
        }
    }

    private void styleMenuItem(javax.swing.JMenuItem item) {
        item.setBackground(MR_CARD);
        item.setForeground(MR_TEXT);
        item.setFont(item.getFont().deriveFont(Font.PLAIN, 13f));
        item.setBorder(BorderFactory.createEmptyBorder(6, 14, 6, 14));
        item.setOpaque(true);
        item.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { item.setBackground(MR_BORDER); }
            @Override public void mouseExited(MouseEvent e)  { item.setBackground(MR_CARD); }
        });
    }

    /** Switches the current selected skin to classic or slim model and re-uploads if Microsoft or Ely.by account. */
    private void changeSkinType(boolean slim) {
        SkinTileData current = selectedSkinTile != null ? selectedSkinTile : defaultSkinTiles().get(0);
        // Update local tile
        selectedSkinTile = new SkinTileData(current.name(), current.image(), slim, current.source(), current.fingerprint());
        previewSkinPanel.setSkin(selectedSkinTile.image(), currentCapeImage, slim);
        rebuildSkinsGridFromCache();
        if (!hasMicrosoftServicesAccount() && !hasElyByAccount()) return;
        String variant = slim ? "SLIM" : "CLASSIC";
        // Re-upload skin with new variant if it's a real file-backed skin
        if (current.source() != null) {
            try {
                java.nio.file.Path path = java.nio.file.Paths.get(current.source());
                if (java.nio.file.Files.isRegularFile(path)) {
                    runTask(ui("Change skin type", "Изменить тип скина", "Changer le type de skin", "Cambia tipo skin", "スキンタイプを変更", "Schimbă tipul skinului", "更改皮肤类型"), () -> {
                        if (hasMicrosoftServicesAccount()) {
                            postMultipartWithFreshMicrosoftToken(SKINS_URL, path, java.util.Map.of("variant", variant), uiProgress());
                        } else {
                            postSkinToElyBy(path, variant, uiProgress());
                        }
                        return ui("Change skin type", "Изменить тип скина", "Changer le type de skin", "Cambia tipo skin", "スキンタイプを変更", "Schimbă tipul skinului", "更改皮肤类型");
                    }, ignored -> refreshSkinsPanel());
                    return;
                }
            } catch (Exception ignored) {}
        }
        JOptionPane.showMessageDialog(this,
                ui("Type changed locally. Upload the skin to the server to apply it.",
                        "Тип изменён локально. Загрузите скин на сервер для применения.",
                        "Le type a été modifié localement. Téléversez le skin sur le serveur pour l'appliquer.",
                        "Tipo modificato localmente. Carica la skin sul server per applicarla.",
                        "タイプはローカルで変更されました。適用するにはスキンをサーバーへアップロードしてください。",
                        "Tipul a fost schimbat local. Încarcă skinul pe server pentru aplicare.",
                        "类型已在本地更改。请将皮肤上传到服务器以应用。"),
                ui("Skin type", "Тип скина", "Type de skin", "Tipo skin", "スキンタイプ", "Tip skin", "皮肤类型"), JOptionPane.INFORMATION_MESSAGE);
    }

