    private void applyUiStyle() {
        styleComponentTree(wallpaperPanel);
        if (settingsPanel != null) {
            styleComponentTree(settingsPanel);
        }
        Color summaryBg = useDarkText() ? new Color(200, 210, 230) : new Color(42, 47, 56);
        styleAccountLabel();
        apiSummaryLabel.setOpaque(false);
        apiSummaryLabel.setForeground(useDarkText() ? MR_TEXT_LIGHT : Color.WHITE);
        stylePill(memorySummaryLabel, summaryBg, TEXT_SECONDARY);
        launcherTitleLabel.setForeground(useDarkText() ? MR_TEXT_LIGHT : Color.WHITE);
        statusLabel.setForeground(useDarkText() ? MR_TEXT_LIGHT : Color.WHITE);
        styleVersionList(installedVersionsList);
        styleVersionList(apiVersionsList);
        styleVersionList(settingsVersionsList);
        styleVersionPane(installedVersionsScroll, t("label.installedVersion"));
        styleVersionPane(apiVersionsScroll, t("label.installVersion"));
        styleVersionPane(settingsVersionsScroll, t("label.installedVersion"));

        // Ensure combo boxes show formatted labels for the selected item as well
        installedVersions.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value instanceof InstalledVersionEntry entry) {
                    label.setText(displayLabelFor(entry.kind(), entry.id()));
                } else {
                    label.setText(value == null ? "" : value.toString());
                }
                label.setOpaque(true);
                label.setBackground(isSelected ? SELECT_BG : FIELD_BG);
                label.setForeground(TEXT_PRIMARY);
                label.setBorder(BorderFactory.createEmptyBorder(4, 7, 4, 7));
                return label;
            }
        });
        apiVersions.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value instanceof VersionInstallOption option) {
                    label.setText(optionText(option));
                } else {
                    label.setText(value == null ? "" : value.toString());
                }
                label.setOpaque(true);
                label.setBackground(isSelected ? SELECT_BG : FIELD_BG);
                label.setForeground(TEXT_PRIMARY);
                label.setBorder(BorderFactory.createEmptyBorder(4, 7, 4, 7));
                return label;
            }
        });

        // make main action buttons slightly larger and semi-transparent
        launchButton.setFont(launchButton.getFont().deriveFont(Font.BOLD, 12f));
        styleMainActionButtons();
        // ensure scrollbars are styled after components are created
        if (installedVersionsScroll != null) styleScrollBar(installedVersionsScroll.getVerticalScrollBar());
        if (apiVersionsScroll != null) styleScrollBar(apiVersionsScroll.getVerticalScrollBar());
        if (settingsVersionsScroll != null) styleScrollBar(settingsVersionsScroll.getVerticalScrollBar());
        if (modGalleryScroll != null) styleScrollBar(modGalleryScroll.getHorizontalScrollBar());

        logArea.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 12));
        progressBar.setForeground(ACCENT);
        progressBar.setBackground(new Color(224, 224, 224));
        progressBar.setBorder(BorderFactory.createEmptyBorder(3, 3, 3, 3));
        showSkinSecondLayerCheck.setForeground(useDarkText() ? MR_TEXT_LIGHT : TEXT_PRIMARY);
        modSearchResults.setBackground(new Color(0, 0, 0, 0));
        modSearchResults.setSelectionBackground(new Color(0, 0, 0, 0));
        modSearchResults.setSelectionForeground(TEXT_PRIMARY);
        modResultCountLabel.setForeground(MR_LIGHT_ACTIVE ? TEXT_PRIMARY : new Color(232, 238, 242));
        selectedModTitleLabel.setForeground(TEXT_PRIMARY);
        selectedModMetaLabel.setForeground(TEXT_SECONDARY);
        refreshModDetailsStyle();
        // Do not force a global dark surface so the wallpaper remains visible.
        if (isLinux()) {
            applyLinuxDarkComponentFixes(wallpaperPanel);
        }
    }

    /**
     * Re-applies the current Modrinth dark/light palette to the already-built
     * UI in place, without restarting the launcher. Used when the user switches
     * between modrinth-dark and modrinth-light while staying in the modern UI;
     * switching to/from the legacy ("msc") UI family still needs a restart since
     * those screens are built differently.
     */
    private void applyThemeLive() {
        applyThemePalette(settings.theme());
        installGlobalUiDefaults();
        applyUiStyle();
        styleComponentTree(wallpaperPanel);
        if (settingsPanel != null) {
            styleComponentTree(settingsPanel);
        }
        refreshPillTabButtons(wallpaperPanel);
        if (settingsPanel != null) {
            refreshPillTabButtons(settingsPanel);
        }
        revalidate();
        repaint();
    }

    /**
     * Applies a language change inside the current frame. Shared controls are
     * retitled in place; navigation/settings surfaces are rebuilt because many of
     * their headings are plain labels created from translations at build time.
     */
    private void applyLanguageLive() {
        installLanguageFontDefaults(language());
        installGlobalUiDefaults();
        applyLocalizedText();

        if (isModernUi() && !isMetroUi()) {
            rebuildSidebarPanel();
            updateModernSection(SCREEN_MAIN.equals(currentScreen())
                    ? ui("Home", "Главная", "Accueil", "Home", "ホーム", "Acasă", "主页")
                    : metroSnapScreenTitle(currentScreen()));
            if (settingsOverlayActive) {
                JPanel content = buildModernSettingsContent();
                loadSettingsIntoForm();
                int overlayW = Math.min(820, Math.max(640, getWidth() - 100));
                int overlayH = Math.min(580, Math.max(400, getHeight() - 80));
                showOverlay(content, overlayW, overlayH);
                setActiveSidebarButton(5);
            }
        } else if (isMetroUi()) {
            rebuildMetroLocalizedSurfaces();
        } else {
            rebuildClassicSettingsScreenForLanguage();
        }

        applyUiStyle();
        refreshPillTabButtons(wallpaperPanel);
        revalidate();
        repaint();
    }

    private void rebuildClassicSettingsScreenForLanguage() {
        int selectedSettingsTab = settingsTabs == null ? 0 : Math.max(0, settingsTabs.getSelectedIndex());
        boolean settingsVisible = SCREEN_SETTINGS.equals(currentScreen());
        if (settingsPanel != null) {
            screenPanel.remove(settingsPanel);
        }
        settingsPanel = buildSettingsScreen();
        screenPanel.add(settingsPanel, SCREEN_SETTINGS);
        loadSettingsIntoForm();
        if (settingsTabs != null && settingsTabs.getTabCount() > 0) {
            settingsTabs.setSelectedIndex(Math.min(selectedSettingsTab, settingsTabs.getTabCount() - 1));
        }
        if (settingsVisible) {
            screenLayout.show(screenPanel, SCREEN_SETTINGS);
        }
    }

    private void rebuildMetroLocalizedSurfaces() {
        if (metroTileCanvas != null) {
            metroTileCanvas.removeAll();
            populateMetroTileCanvas(metroTileCanvas);
            metroTileCanvas.revalidate();
            metroTileCanvas.repaint();
        }
        if (metroParamsScreen != null) {
            metroParamsScreen.removeAll();
            metroParamsScreen.add(buildMetroParamsSection(), BorderLayout.CENTER);
            metroParamsScreen.revalidate();
            metroParamsScreen.repaint();
        }
        updateMetroBackNavButton();
        setMetroSettingsSnapMode(metroSettingsSnapMode);
    }

    /**
     * PillTabButton (library "All instances"/"Modpacks" tabs, the mods/modpacks
     * content-type pills, etc.) fully owns its own paint and is deliberately
     * skipped by styleComponentTree()/applyDarkTranslucentTheme() so global
     * restyle passes can never knock it back to a plain white square. That same
     * protection means it never picks up a live theme switch on its own, so we
     * walk the tree here and refresh each one explicitly.
     */
    private void refreshPillTabButtons(Component component) {
        if (component instanceof PillTabButton pill) {
            pill.refreshPalette();
        }
        if (component instanceof Container container) {
            for (Component child : container.getComponents()) {
                refreshPillTabButtons(child);
            }
        }
    }

    private void styleVersionList(JList<?> list) {
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setSelectionBackground(SELECT_BG);
        list.setSelectionForeground(Color.WHITE);
        list.setForeground(TEXT_PRIMARY);
        // Keep the list itself transparent so wallpaper and parent panel show through; individual cells draw their own highlights.
        list.setOpaque(false);
        list.setBackground(new Color(0, 0, 0, 0));
        // prototype cell value removed to avoid generic type issues; width is adjusted programmatically
    }

    private void styleVersionPane(JScrollPane scrollPane, String title) {
        if (scrollPane == null) {
            return;
        }
        scrollPane.setOpaque(false);
        scrollPane.getViewport().setOpaque(false);
        scrollPane.setBorder(new RoundedTitledBorder(
                title,
                new Font(Font.SANS_SERIF, Font.PLAIN, 10),
                new Color(222, 228, 236),
                new Color(238, 238, 238, 112),
                ARC + 8
        ));
        // ensure scrollbar UI applied
        styleScrollBar(scrollPane.getVerticalScrollBar());
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
    }

