    private void styleFooterButton(JButton button, int minWidth) {
        if (button instanceof ColoredPillButton) {
            button.setFont(button.getFont().deriveFont(Font.BOLD, 11f));
            Dimension preferred = button.getPreferredSize();
            button.setPreferredSize(new Dimension(Math.max(preferred.width, minWidth), Math.max(preferred.height, 30)));
            return;
        }
        prepareTranslucentButton(button);
        button.setFont(button.getFont().deriveFont(Font.BOLD, 11f));
        button.setMargin(new Insets(3, 10, 3, 10));
        button.setBorder(BorderFactory.createEmptyBorder(3, 10, 3, 10));
        Dimension preferred = button.getPreferredSize();
        button.setPreferredSize(new Dimension(Math.max(preferred.width, minWidth), Math.max(preferred.height, 28)));
    }

