    /**
     * Wraps a single child component and hard-clips everything it paints
     * (background, the child's own painting, any look-and-feel border or
     * focus ring, even the combo box's invisible arrow button) to a fully
     * rounded pill shape. Used so the account switcher can never show a
     * sharp/square corner no matter what the wrapped component tries to
     * paint internally.
     */
    private static final class PillClipPanel extends JPanel {
        private PillClipPanel(JComponent content) {
            super(new BorderLayout());
            setOpaque(false);
            add(content, BorderLayout.CENTER);
        }

        @Override
        public void paint(Graphics g) {
            int w = getWidth(), h = getHeight(), arc = h;
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            // Use clip() to intersect with existing clip rather than replacing it,
            // ensuring the pill shape is always respected even when the L&F tries
            // to paint outside our rounded region.
            g2.clip(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
            super.paint(g2);
            g2.dispose();
        }
    }

    /**
     * Row renderer for the account-switcher pill: a small circular badge
     * (coloured by account provider) plus the username, drawn in one compact
     * line for the closed field and with an extra dim provider label for the
     * open dropdown rows. Selected/hovered rows get a fully rounded pill
     * highlight instead of a plain rectangle, and unselected rows paint no
     * background at all — so the whole switcher, list included, is drawn by
     * the app's own interface rather than the default Swing combo box look.
     */
    private static final class AccountRowRenderer extends JPanel implements ListCellRenderer<Account> {
        private boolean rowSelected;
        private String initial = "?";
        private String name = "";
        private String typeText = "";
        private Color badgeColor = MR_TEXT_DIM;

        private AccountRowRenderer() {
            setOpaque(false);
            setFont(new Font("Segoe UI", Font.PLAIN, 13));
        }

        @Override
        public Dimension getPreferredSize() {
            return new Dimension(190, 42);
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends Account> list, Account value, int index,
                                                      boolean isSelected, boolean cellHasFocus) {
            rowSelected = isSelected;
            if (value != null) {
                name = value.username() == null ? "" : value.username();
                typeText = value.typeLabel();
                initial = name.isBlank() ? "?" : String.valueOf(Character.toUpperCase(name.charAt(0)));
                badgeColor = switch (value.type()) {
                    case MICROSOFT -> new Color(70, 150, 240);
                    case ELY_BY    -> new Color(170, 130, 240);
                    default        -> new Color(110, 116, 128);
                };
            } else {
                name = "";
                typeText = "";
                initial = "?";
                badgeColor = MR_TEXT_DIM;
            }
            return this;
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth(), h = getHeight();
            boolean compact = h < 34;

            if (rowSelected) {
                g2.setColor(ACCENT);
                g2.fill(new RoundRectangle2D.Float(4, 2, Math.max(0, w - 8), Math.max(0, h - 4), h, h));
            }

            if (compact) {
                // Свёрнутое поле: маленькая цветная точка-индикатор + имя в одну строку.
                int dotD = 8, dx = 10, dy = (h - dotD) / 2;
                g2.setColor(badgeColor);
                g2.fillOval(dx, dy, dotD, dotD);
                g2.setColor(rowSelected ? Color.WHITE : MR_TEXT);
                g2.setFont(getFont().deriveFont(Font.PLAIN, 13f));
                FontMetrics fm = g2.getFontMetrics();
                int ty = (h + fm.getAscent() - fm.getDescent()) / 2;
                g2.drawString(name, dx + dotD + 8, ty);
            } else {
                // Открытый список: круглый бейдж с инициалом + имя + подпись провайдера.
                int bd = Math.max(14, Math.min(h - 14, 26)), bx = 10, by = (h - bd) / 2;
                g2.setColor(badgeColor);
                g2.fillOval(bx, by, bd, bd);
                g2.setColor(Color.WHITE);
                g2.setFont(getFont().deriveFont(Font.BOLD, 11f));
                FontMetrics bfm = g2.getFontMetrics();
                g2.drawString(initial, bx + (bd - bfm.stringWidth(initial)) / 2,
                        by + (bd + bfm.getAscent() - bfm.getDescent()) / 2);

                int tx = bx + bd + 10;
                g2.setColor(rowSelected ? Color.WHITE : MR_TEXT);
                g2.setFont(getFont().deriveFont(Font.PLAIN, 13f));
                g2.drawString(name, tx, h / 2 - 2);

                g2.setColor(rowSelected ? new Color(255, 255, 255, 200) : MR_TEXT_DIM);
                g2.setFont(getFont().deriveFont(Font.PLAIN, 10f));
                g2.drawString(typeText, tx, h / 2 + 13);
            }
            g2.dispose();
        }
    }

    private void styleTabbedPane(JTabbedPane tabbedPane) {
        tabbedPane.setOpaque(false);
        tabbedPane.setForeground(TEXT_PRIMARY);
        tabbedPane.setBackground(new Color(20, 22, 27));
        tabbedPane.setUI(new BasicTabbedPaneUI() {
            @Override
            protected void paintContentBorder(Graphics g, int tabPlacement, int selectedIndex) {
            }

            @Override
            protected void paintFocusIndicator(Graphics g, int tabPlacement, Rectangle[] rects, int tabIndex,
                                               Rectangle iconRect, Rectangle textRect, boolean isSelected) {
            }

            @Override
            protected void paintTabBackground(Graphics g, int tabPlacement, int tabIndex, int x, int y, int w, int h,
                                              boolean isSelected) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(isSelected ? new Color(56, 62, 72) : new Color(25, 28, 34));
                g2.fillRoundRect(x + 4, y + 4, w - 8, h - 6, 8, 8);
                if (isSelected) {
                    g2.setColor(ACCENT);
                    g2.fillRoundRect(x + 12, y + h - 5, w - 24, 3, 3, 3);
                }
                g2.dispose();
            }

            @Override
            protected void paintText(Graphics g, int tabPlacement, Font font, FontMetrics metrics, int tabIndex,
                                     String title, Rectangle textRect, boolean isSelected) {
                g.setFont(font);
                g.setColor(TEXT_PRIMARY);
                g.drawString(title, textRect.x, textRect.y + metrics.getAscent());
            }
        });
    }

    private void styleList(JList<?> list) {
        list.setOpaque(true);
        list.setBackground(FIELD_BG);
        list.setForeground(TEXT_PRIMARY);
        list.setSelectionBackground(SELECT_BG);
        list.setSelectionForeground(Color.WHITE);
    }

    private void styleButton(JButton button) {
        // PillTabButton (library top tabs) fully owns its own paint/opacity
        // logic; never let the generic restyling pass touch it.
        if (button instanceof PillTabButton) {
            return;
        }
        // IconNavButton (mods pagination arrows) likewise owns its paint entirely
        // and recomputes its own colors live, so leave it alone too.
        if (button instanceof IconNavButton) {
            return;
        }
        // Skip buttons that already have the modern pill style applied
        if (Boolean.TRUE.equals(button.getClientProperty("msc.pillStyle"))) {
            return;
        }
        if (Boolean.TRUE.equals(button.getClientProperty("msc.keepOptionStyle"))) {
            return;
        }
        // Respect buttons that already have a custom background set elsewhere
        Color defaultBtnBg = UIManager.getColor("Button.background");
        boolean hasCustomBg = button.getBackground() != null && !button.getBackground().equals(defaultBtnBg);
        Object keepStyle = button.getClientProperty("msc.keepDefaultStyle");
        if (Boolean.TRUE.equals(keepStyle)) {
            button.setOpaque(false);
            button.setContentAreaFilled(false);
            button.setBorderPainted(false);
            button.setFocusPainted(false);
            return;
        }
        if (hasCustomBg) {
            // Keep the explicit background, but ensure readable foreground and sensible chrome
            if (isLightColor(button.getBackground())) {
                button.setForeground(TEXT_PRIMARY);
            } else {
                button.setForeground(BUTTON_TEXT);
            }
            button.setOpaque(true);
            button.setFocusPainted(false);
            // add a subtle border so dark-on-dark or light-on-light remains legible
            if (button.getBorder() == null || button.getBorder() instanceof javax.swing.plaf.UIResource) {
                Color borderCol = isLightColor(button.getBackground())
                        ? new Color(0, 0, 0, 40)
                        : new Color(180, 195, 220, 45);
                button.setBorder(BorderFactory.createLineBorder(borderCol));
            }
        } else {
            // Apply the translucent styled button used throughout the launcher
            prepareTranslucentButton(button);
        }

        button.setMargin(new Insets(4, 12, 4, 12));
        button.setBorder(BorderFactory.createEmptyBorder(4, 12, 4, 12));
        Dimension preferred = button.getPreferredSize();
        button.setPreferredSize(new Dimension(Math.max(preferred.width, 112), Math.max(preferred.height, 30)));
    }

    private void prepareTranslucentButton(JButton button) {
        // Keep a stable UI delegate and paint a translucent rounded button
        button.updateUI();
        button.setUI(new TranslucentButtonUI());
        // Use non-opaque so the translucent rounded shape is visible; the UI paints the full background.
        button.setOpaque(false);
        button.setContentAreaFilled(false);
        button.setBorderPainted(false);
        button.setFocusPainted(false);
        button.setRolloverEnabled(true);
        button.setBackground(MR_LIGHT_ACTIVE ? MR_CARD : BUTTON_BG);
        button.setForeground(MR_LIGHT_ACTIVE ? MR_TEXT : BUTTON_TEXT);
    }

    private void stylePill(JLabel label, Color background, Color foreground) {
        label.setOpaque(true);
        label.setBackground(background);
        label.setForeground(foreground);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 12f));
        Color borderCol = isLightColor(background)
                ? new Color(0, 0, 0, 35)
                : new Color(180, 195, 220, 45);
        label.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(borderCol),
                BorderFactory.createEmptyBorder(6, 10, 6, 10)
        ));
    }

    /**
     * JSplitPane never got covered by styleComponentTree()/applyDarkTranslucentTheme() —
     * setOpaque(false) on the split pane itself does nothing for its divider,
     * which is a separate internal component the L&F paints on its own (plain
     * white/light-gray on Windows). That's the vertical light stripe that used
     * to show through between the mod list and the details panel. Installing a
     * divider that paints the current theme background fixes it for both themes.
     */
    private void styleSplitPane(JSplitPane split) {
        split.setOpaque(false);
        split.setBorder(BorderFactory.createEmptyBorder());
        split.setDividerSize(6);
        split.setContinuousLayout(true);
        split.setUI(new javax.swing.plaf.basic.BasicSplitPaneUI() {
            @Override
            public javax.swing.plaf.basic.BasicSplitPaneDivider createDefaultDivider() {
                return new javax.swing.plaf.basic.BasicSplitPaneDivider(this) {
                    @Override
                    public void paint(Graphics g) {
                        g.setColor(WINDOW_BG);
                        g.fillRect(0, 0, getWidth(), getHeight());
                        super.paint(g);
                    }
                };
            }
        });
    }

    private void styleScrollBar(JScrollBar scrollBar) {
        if (scrollBar == null) {
            return;
        }
        scrollBar.setOpaque(false);
        scrollBar.setUnitIncrement(16);
        // install a minimal transparent UI for a slim, modern scrollbar
        scrollBar.setUI(new javax.swing.plaf.basic.BasicScrollBarUI() {
            private final int THUMB_SIZE = 8;
            @Override
            protected void paintTrack(Graphics g, JComponent c, Rectangle trackBounds) {
                // transparent track
            }

            @Override
            protected void paintThumb(Graphics g, JComponent c, Rectangle thumbBounds) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                // gradient translucent thumb for nicer look
                g2.setPaint(new java.awt.GradientPaint(thumbBounds.x, thumbBounds.y, new Color(180, 195, 220, 120),
                        thumbBounds.x + thumbBounds.width, thumbBounds.y + thumbBounds.height, new Color(180, 195, 220, 60)));
                int arc = THUMB_SIZE;
                g2.fillRoundRect(thumbBounds.x + 2, thumbBounds.y + 2, Math.max(THUMB_SIZE, thumbBounds.width - 4), Math.max(THUMB_SIZE, thumbBounds.height - 4), arc, arc);
                g2.dispose();
            }

            @Override
            protected Dimension getMinimumThumbSize() {
                return new Dimension(THUMB_SIZE, THUMB_SIZE);
            }

            @Override
            protected JButton createDecreaseButton(int orientation) {
                return createZeroButton();
            }

            @Override
            protected JButton createIncreaseButton(int orientation) {
                return createZeroButton();
            }

            private JButton createZeroButton() {
                JButton b = new JButton();
                b.setPreferredSize(new Dimension(0, 0));
                b.setMinimumSize(new Dimension(0, 0));
                b.setMaximumSize(new Dimension(0, 0));
                b.setOpaque(false);
                b.setBorder(null);
                return b;
            }
        });
        // reduce preferred width so thumb appears slim
        if (scrollBar.getOrientation() == Adjustable.VERTICAL) {
            scrollBar.setPreferredSize(new Dimension(12, Integer.MAX_VALUE));
            scrollBar.setUnitIncrement(14);
        } else {
            scrollBar.setPreferredSize(new Dimension(Integer.MAX_VALUE, 12));
        }
    }

    private void wireActions() {
        styleAccountSelectorAsPill();
        accountSelector.putClientProperty("msc.pillStyle", Boolean.TRUE);
        accountSelector.addActionListener(e -> selectAccountFromMenu());
        accountsButton.addActionListener(e -> showSettingsScreen());
        openSettingsButton.addActionListener(e -> showSettingsScreen());
        openModsButton.addActionListener(e -> showModsScreen());
        openSkinsButton.addActionListener(e -> showSkinsScreen());
        backFromSkinsButton.addActionListener(e -> showMainScreen());
        openLibrariesButton.addActionListener(e -> showLibraryScreen());
        backToMainButton.addActionListener(e -> showMainScreen());
        backFromModsButton.addActionListener(e -> {
            // В Classic UI (MSC) кнопки "Библиотека" в сайдбаре нет, поэтому переход
            // на экран инстансов оставлял пользователя без возможности вернуться назад.
            // Для классического интерфейса кнопка "Играть" в модах теперь ведёт на
            // главный экран лаунчера; в Modern UI поведение остаётся прежним.
            if (isModernUi()) {
                showLibraryScreen();
            } else {
                showMainScreen();
            }
        });
        refreshButton.addActionListener(e -> {
            saveSettingsFromForm();
            refreshInstalledVersions();
            refreshApiVersions();
        });
        addVersionFilterListeners();
        addSettingsAutoSaveListeners();
        installButton.addActionListener(e -> {
            VersionInstallOption option = selectedInstallOption();
            if (option == null) {
                JOptionPane.showMessageDialog(this, t("message.selectInstallVersion"), t("task.installSelected"), JOptionPane.WARNING_MESSAGE);
                return;
            }
            // Не позволяем повторно скачивать ту же версию с тем же загрузчиком, если она уже установлена.
            if (blockDuplicateInstall(option.versionId(), option.kind())) {
                return;
            }
            // Forge + OptiFine на Minecraft 1.13+ — ручной выбор сборок (см. installLoaderVersion).
            // Версии до 1.13 и все остальные загрузчики продолжают ставиться как раньше, автоматически.
            if (option.kind() == InstallKind.FORGE_OPTIFINE && VersionSort.compareVersions(option.versionId(), "1.13") >= 0) {
                installLoaderVersion(option.versionId(), option.kind(), t("task.installSelected"), this::refreshInstalledVersions);
                return;
            }
            runTask(t("task.installSelected"), () -> installSelectedOption(option), ignored -> refreshInstalledVersions());
        });
        launchButton.addActionListener(e -> {
            if (isMinecraftRunning()) {
                stopRunningMinecraft();
                return;
            }
            saveSettingsFromForm();
            String version = selectedInstalledVersion();
            if (version == null) {
                JOptionPane.showMessageDialog(this, t("message.selectInstalledVersion"), t("dialog.noVersion"), JOptionPane.WARNING_MESSAGE);
                return;
            }
            if (account.type() == Account.Type.OFFLINE || !usernameField.getText().trim().equals(account.username())) {
                account = Account.offline(usernameField.getText().trim().isEmpty() ? "Player" : usernameField.getText().trim());
                AccountStore.save(account);
                refreshAccountMenu();
                updateAccountLabel();
            }
            runTask(tf("task.launch", version), () -> {
                modContentInstaller.repairInstalledModpack(version, settings, uiProgress());
                String launchVersion = modLoaderUpdateService.updateBeforeLaunch(version, settings, uiProgress());
                Process process = launcher.launch(launchVersion, settings, account, uiProgress());
                log(t("log.minecraftStarted"));
                return new LaunchResult(process, launchVersion);
            }, result -> {
                if (result instanceof LaunchResult launchResult) {
                    refreshInstalledVersions();
                    registerRunningMinecraft(launchResult.process(), launchResult.profileId());
                    hideLauncherUntilMinecraftExit(launchResult.process(), launchResult.profileId());
                }
            });
        });
        microsoftLoginButton.addActionListener(e -> startMicrosoftLogin());
        elyByLoginButton.addActionListener(e -> startElyByLogin());
        openGameDirButton.addActionListener(e -> openGameDirectory());
        saveSettingsButton.addActionListener(e -> {
            saveSettingsFromForm();
            applyWallpaperFromForm(); // update wallpaper only on explicit save, in EDT
            account = account.type() == Account.Type.OFFLINE ? Account.offline(settings.username()) : account;
            AccountStore.save(account);
            refreshAccountMenu();
            updateAccountLabel();
            log(t("log.settingsSaved"));
        });
        refreshSettingsButton.addActionListener(e -> {
            applyLauncherRefresh();
        });
        modSearchButton.addActionListener(e -> {
            modSearchSuggestionsDismissed = true;
            hideModSearchSuggestions();
            modPageIndex = 0;
            searchModContent();
        });
        modPrevPageButton.addActionListener(e -> changeModPage(-1));
        modNextPageButton.addActionListener(e -> changeModPage(1));
        installModButton.addActionListener(e -> installSelectedModContent());
        checkModUpdatesButton.addActionListener(e -> checkSelectedTargetModUpdates());
        rollbackModUpdatesButton.addActionListener(e -> confirmRollbackSelectedModUpdates());
        createModBuildButton.addActionListener(e -> showCreateModBuildDialog());
        modTargetProfileCombo.addActionListener(e -> {
            if (!updatingModTargetProfileCombo) {
                syncModFiltersFromTargetProfile();
            }
        });
        modSourceCombo.addActionListener(e -> {
            modrinthSourceButton.setSelected("Modrinth".equals(modSourceCombo.getSelectedItem()));
            curseForgeSourceButton.setSelected("CurseForge".equals(modSourceCombo.getSelectedItem()));
            reloadModCatalogFromFirstPage();
            updateModTypePillsForSource();
        });
        modContentTypeCombo.addActionListener(e -> {
            updateModTypePillActiveStates();
            reloadModCatalogFromFirstPage();
        });
        modLoaderCombo.addActionListener(e -> reloadModCatalogFromFirstPage());
    }

    private void applyLauncherRefresh() {
        try {
            saveSettingsFromForm();
            if (account.type() == Account.Type.OFFLINE) {
                account = Account.offline(settings.username());
                AccountStore.save(account);
            } else {
                AccountStore.select(account);
            }
            log(t("log.settingsRefreshed"));
            restartFrame();
        } catch (Exception ex) {
            log(tf("log.settingsSaveFailed", ex.getMessage()));
            JOptionPane.showMessageDialog(this, ex.getMessage(), t("dialog.error"), JOptionPane.ERROR_MESSAGE);
        }
    }

    private void showSettingsScreen() {
        closeAccountPopup();
        updateModernSection(t("tab.settings"));
        if (isMetroUi()) {
            if (routeMetroScreenToSnapWorkspace(SCREEN_SETTINGS)) {
                setActiveSidebarButton(5);
                revalidate();
                repaint();
                return;
            }
            showMetroParamsScreen();
            return;
        }
        if (!isModernUi()) {
            screenLayout.show(screenPanel, SCREEN_SETTINGS);
            animateInterfaceScreen(SCREEN_SETTINGS);
            if (settingsTabs != null) settingsTabs.setSelectedIndex(0);
            revalidate();
            repaint();
            return;
        }
        // Modern UI: show settings as an overlay on top of the current screen.
        // Запоминаем, какая вкладка была активна, чтобы при закрытии настроек
        // подсветка вернулась на неё, а не пропала совсем.
        if (activeSidebarIndex != 5) {
            sidebarIndexBeforeSettings = activeSidebarIndex >= 0 ? activeSidebarIndex : 0;
        }
        settingsOverlayActive = true;
        JPanel content = buildModernSettingsContent();
        loadSettingsIntoForm();
        int overlayW = Math.min(820, Math.max(640, getWidth() - 100));
        int overlayH = Math.min(580, Math.max(400, getHeight() - 80));
        showOverlay(content, overlayW, overlayH);
        setActiveSidebarButton(5);
    }

