    // ── Избранное: хранение и переключение ───────────────────────────────────
    private java.nio.file.Path favoritesFilePath() {
        return settings.gameDirectory().resolve("launcher_favorites.txt");
    }

    private Path recentLaunchesFilePath() {
        return settings.gameDirectory().resolve("launcher_recent_launches.txt");
    }

    private Map<String, Long> loadRecentLaunches() {
        Map<String, Long> launches = new java.util.LinkedHashMap<>();
        try {
            Path path = recentLaunchesFilePath();
            if (!Files.isRegularFile(path)) {
                return launches;
            }
            for (String line : Files.readAllLines(path, java.nio.charset.StandardCharsets.UTF_8)) {
                int separator = line.lastIndexOf('|');
                if (separator <= 0) continue;
                try {
                    launches.put(line.substring(0, separator), Long.parseLong(line.substring(separator + 1)));
                } catch (NumberFormatException ignored) {
                }
            }
        } catch (IOException ex) {
            log(nr("Could not load recent launches: ", "Не удалось загрузить недавние запуски: ") + ex.getMessage());
        }
        return launches;
    }

    private void recordRecentLaunch(String profileId) {
        if (profileId == null || profileId.isBlank()) return;
        Map<String, Long> launches = loadRecentLaunches();
        launches.put(profileId, System.currentTimeMillis());
        java.util.List<Map.Entry<String, Long>> ordered = new ArrayList<>(launches.entrySet());
        ordered.sort(Map.Entry.<String, Long>comparingByValue().reversed());
        java.util.List<String> lines = ordered.stream().limit(20)
                .map(entry -> entry.getKey() + "|" + entry.getValue()).toList();
        try {
            Files.createDirectories(recentLaunchesFilePath().getParent());
            Files.write(recentLaunchesFilePath(), lines, java.nio.charset.StandardCharsets.UTF_8);
        } catch (IOException ex) {
            log(nr("Could not save recent launches: ", "Не удалось сохранить недавние запуски: ") + ex.getMessage());
        }
        refreshRecentVersions();
    }

    private void loadFavorites() {
        favoriteInstances.clear();
        try {
            java.nio.file.Path p = favoritesFilePath();
            if (java.nio.file.Files.exists(p)) {
                for (String line : java.nio.file.Files.readAllLines(p, java.nio.charset.StandardCharsets.UTF_8)) {
                    String s = line.trim();
                    if (!s.isEmpty()) favoriteInstances.add(s);
                }
            }
        } catch (Exception ex) {
            log(nr("Could not load favorites: ", "Не удалось загрузить избранное: ") + ex.getMessage());
        }
    }

    private void saveFavorites() {
        try {
            java.nio.file.Path p = favoritesFilePath();
            java.nio.file.Files.createDirectories(p.getParent());
            java.nio.file.Files.write(p, favoriteInstances, java.nio.charset.StandardCharsets.UTF_8);
        } catch (Exception ex) {
            log(nr("Could not save favorites: ", "Не удалось сохранить избранное: ") + ex.getMessage());
        }
    }

    private boolean isFavoriteInstance(String id) {
        return favoriteInstances.contains(id);
    }

    // ── Библиотека: ручной порядок карточек (перетаскивание мышью) ──────────
    private java.nio.file.Path libraryOrderFilePath() {
        return settings.gameDirectory().resolve("launcher_library_order.txt");
    }

    private void loadLibraryOrder() {
        libraryOrderIds.clear();
        libraryManualOrder = false;
        try {
            java.nio.file.Path p = libraryOrderFilePath();
            if (java.nio.file.Files.exists(p)) {
                boolean first = true;
                for (String line : java.nio.file.Files.readAllLines(p, java.nio.charset.StandardCharsets.UTF_8)) {
                    String s = line.trim();
                    if (first) {
                        libraryManualOrder = "manual:true".equals(s);
                        first = false;
                        continue;
                    }
                    if (!s.isEmpty()) libraryOrderIds.add(s);
                }
            }
        } catch (Exception ex) {
            log(nr("Could not load library order: ", "Не удалось загрузить порядок библиотеки: ") + ex.getMessage());
        }
    }

    private void saveLibraryOrder() {
        try {
            java.nio.file.Path p = libraryOrderFilePath();
            java.nio.file.Files.createDirectories(p.getParent());
            java.util.List<String> lines = new java.util.ArrayList<>();
            lines.add(libraryManualOrder ? "manual:true" : "manual:false");
            lines.addAll(libraryOrderIds);
            java.nio.file.Files.write(p, lines, java.nio.charset.StandardCharsets.UTF_8);
        } catch (Exception ex) {
            log(nr("Could not save library order: ", "Не удалось сохранить порядок библиотеки: ") + ex.getMessage());
        }
    }

    /** Синхронизирует список ручного порядка с реально установленными версиями:
     *  удаляет отсутствующие id и дописывает новые в конец. */
    private void syncLibraryOrderIds(java.util.List<InstalledVersionEntry> allEntries) {
        java.util.LinkedHashSet<String> currentIds = new java.util.LinkedHashSet<>();
        for (InstalledVersionEntry e : allEntries) currentIds.add(e.id());
        libraryOrderIds.removeIf(id -> !currentIds.contains(id));
        for (String id : currentIds) {
            if (!libraryOrderIds.contains(id)) libraryOrderIds.add(id);
        }
    }

    /** Меняет местами две версии в библиотеке по их id (drag & drop мышью). */
    private void swapLibraryOrder(String draggedId, String targetId) {
        if (draggedId == null || targetId == null || draggedId.equals(targetId)) return;
        int i1 = libraryOrderIds.indexOf(draggedId);
        int i2 = libraryOrderIds.indexOf(targetId);
        if (i1 < 0 || i2 < 0) return;
        java.util.Collections.swap(libraryOrderIds, i1, i2);
        libraryManualOrder = true;
        saveLibraryOrder();
        refreshLibraryScreen();
    }

    /** Находит карточку версии библиотеки под указанной экранной точкой (для drag & drop). */
    private Component findLibraryCardAt(Point screenPt) {
        if (libraryInstanceGrid == null || !libraryInstanceGrid.isShowing()) return null;
        Point local = new Point(screenPt);
        SwingUtilities.convertPointFromScreen(local, libraryInstanceGrid);
        Component deepest = SwingUtilities.getDeepestComponentAt(libraryInstanceGrid, local.x, local.y);
        while (deepest != null && !(deepest instanceof RoundedInstanceCard) && deepest != libraryInstanceGrid) {
            deepest = deepest.getParent();
        }
        return (deepest instanceof RoundedInstanceCard) ? deepest : null;
    }

    private void toggleFavoriteInstance(String id) {
        if (favoriteInstances.contains(id)) {
            favoriteInstances.remove(id);
        } else {
            favoriteInstances.add(id);
        }
        saveFavorites();
        refreshFavoritesSection();
    }

    /** Перестраивает блок избранных версий на главной странице. */
    private void refreshFavoritesSection() {
        if (favoritesSection == null || favoritesCardsRow == null) {
            refreshMetroFavoriteTiles();
            return;
        }
        favoritesCardsRow.removeAll();
        if (favoriteInstances.isEmpty()) {
            favoritesSection.setVisible(false);
        } else {
            favoritesSection.setVisible(true);
            for (String id : favoriteInstances) {
                InstalledVersionEntry entry = new InstalledVersionEntry(id, detectInstallKindForProfile(id));
                favoritesCardsRow.add(buildInstanceCard(entry));
            }
        }
        favoritesCardsRow.revalidate();
        favoritesCardsRow.repaint();
        favoritesSection.revalidate();
        favoritesSection.repaint();
        // Уведомляем корневой контейнер чтобы пересчитался layout
        if (favoritesSection.getParent() != null) {
            favoritesSection.getParent().revalidate();
            favoritesSection.getParent().repaint();
        }
        refreshMetroFavoriteTiles();
    }

