    // ─────────────────────────────────────────────────────────────────────────
    // Library screen (Modrinth-style instance grid)
    // ─────────────────────────────────────────────────────────────────────────
    private JPanel libraryInstanceGrid;

    private JPanel buildLibraryScreen() {
        JPanel root = new JPanel(new BorderLayout(0, 0));
        root.setOpaque(false);

        // ── Top bar ──────────────────────────────────────────────────────────
        JPanel topBar = new JPanel(new BorderLayout(0, 0));
        metroLibraryTopBar = topBar;
        topBar.setOpaque(false);
        topBar.setBorder(BorderFactory.createEmptyBorder(14, 18, 0, 18));

        // Tabs row — pill-style buttons that own their own paint, so the
        // active/hover states stay stable no matter what global restyling
        // passes run afterwards.
        AnimatedPillTabRow animatedTabsRow = new AnimatedPillTabRow(6, 0);
        libraryTabsRow = animatedTabsRow;
        libraryTabsRow.setOpaque(false);
        libraryTabButtons.clear();
        String[] tabNames = {"All instances", "Modpacks", t("kind.customBuild")};
        for (int i = 0; i < tabNames.length; i++) {
            final int index = i;
            PillTabButton tab = new PillTabButton(tabNames[i]);
            tab.putClientProperty("msc.externalActiveIndicator", Boolean.TRUE);
            tab.setActive(i == 0);
            tab.addActionListener(e -> setActiveLibraryTab(index));
            libraryTabButtons.add(tab);
            libraryTabsRow.add(tab);
        }
        animatedTabsRow.setActiveButton(libraryTabButtons.get(0), false);
        topBar.add(libraryTabsRow, BorderLayout.WEST);
        metroLibraryTabsScroll = new JScrollPane();
        metroLibraryTabsScroll.setOpaque(false);
        metroLibraryTabsScroll.getViewport().setOpaque(false);
        metroLibraryTabsScroll.setBorder(BorderFactory.createEmptyBorder());
        metroLibraryTabsScroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_NEVER);
        metroLibraryTabsScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        installSmoothMetroScrolling(metroLibraryTabsScroll);

        // Sort/Group controls — triggers in one row, options expand below in same row
        JPanel controlsCol = new JPanel();
        metroLibraryControlsColumn = controlsCol;
        controlsCol.setLayout(new BoxLayout(controlsCol, BoxLayout.Y_AXIS));
        controlsCol.setOpaque(false);

        String[] sortLabels = {
                t("label.sortName"),
                ui("Last played", "Последний запуск", "Dernière utilisation", "Ultimo avvio",
                        "最後のプレイ", "Ultima utilizare", "上次游玩"),
                ui("Date created", "Дата создания", "Date de création", "Data di creazione",
                        "作成日", "Data creării", "创建日期"),
                ui("Date modified", "Дата изменения", "Date de modification", "Data di modifica",
                        "更新日", "Data modificării", "修改日期"),
                t("label.gameVersion")
        };
        String[] groupLabels = {
                t("label.groupGroup"),
                t("label.groupLoader"),
                t("label.gameVersion"),
                ui("None", "Нет", "Aucun", "Nessuno", "なし", "Fără", "无")
        };

        // Shared expanded options row (shown below triggers when either is open)
        JPanel expandedRow = new JPanel() {
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(new Color(52, 55, 63));
                g2.fillRoundRect(0, -12, getWidth(), getHeight() + 12, 14, 14);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        expandedRow.setLayout(new BoxLayout(expandedRow, BoxLayout.Y_AXIS));
        expandedRow.setOpaque(false);
        expandedRow.setMaximumSize(new Dimension(254, Integer.MAX_VALUE));
        expandedRow.setVisible(false);
        JPanel dropdownHost = new JPanel(new BorderLayout());
        metroLibraryDropdownHost = dropdownHost;
        dropdownHost.setOpaque(false);
        dropdownHost.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 6));

        // Track which dropdown is open: 0=none, 1=sort, 2=group
        int[] openDropdown = {0};

        // Build trigger pills + option pills for Sort and Group
        JPanel triggersRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        metroLibraryTriggersRow = triggersRow;
        triggersRow.setOpaque(false);

        // Helper to create a styled trigger pill button
        java.util.function.Function<String, JButton> makeTrigger = text -> {
            JButton btn = new JButton(text) {
                @Override protected void paintComponent(Graphics g) {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    int arc = 14;
                    boolean isOpen = Boolean.TRUE.equals(getClientProperty("open"));
                    Color fill = isOpen
                            ? new Color(68, 71, 80)
                            : (getModel().isRollover() ? new Color(62, 65, 74) : new Color(52, 55, 63));
                    g2.setColor(fill);
                    g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                    if (isOpen) {
                        g2.setColor(MR_ACCENT);
                        g2.setStroke(new java.awt.BasicStroke(1f));
                        g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth()-1f, getHeight()-1f, arc, arc));
                    }
                    g2.dispose();
                    super.paintComponent(g);
                }
            };
            btn.setFocusPainted(false); btn.setBorderPainted(false);
            btn.setContentAreaFilled(false); btn.setOpaque(false);
            btn.setRolloverEnabled(true);
            btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            btn.setBorder(BorderFactory.createEmptyBorder(5, 14, 5, 14));
            btn.setFont(btn.getFont().deriveFont(Font.BOLD, 14f));
            btn.setForeground(MR_TEXT);
            btn.setPreferredSize(new Dimension(254, 40));
            btn.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
            return btn;
        };

        // Helper to create an option pill button
        java.util.function.BiFunction<String, Boolean, JButton> makeOpt = (label, active) -> {
            JButton btn = new JButton(label) {
                @Override protected void paintComponent(Graphics g) {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    int arc = 0;
                    boolean on = Boolean.TRUE.equals(getClientProperty("active"));
                    if (on) {
                        g2.setColor(new Color(26, 214, 111));
                        g2.fillRect(0, 0, getWidth(), getHeight());
                    } else if (getModel().isRollover()) {
                        g2.setColor(new Color(61, 64, 72));
                        g2.fillRect(0, 0, getWidth(), getHeight());
                    }
                    g2.dispose();
                    super.paintComponent(g);
                }
            };
            btn.putClientProperty("active", active);
            btn.setFont(btn.getFont().deriveFont(active ? Font.BOLD : Font.PLAIN, 12f));
            btn.setForeground(active ? Color.BLACK : MR_TEXT_DIM);
            btn.setFocusPainted(false); btn.setBorderPainted(false);
            btn.setContentAreaFilled(false); btn.setOpaque(false);
            btn.setRolloverEnabled(true);
            btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            btn.setHorizontalAlignment(SwingConstants.LEFT);
            btn.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
            btn.setPreferredSize(new Dimension(254, 42));
            btn.setMaximumSize(new Dimension(254, 42));
            btn.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
            return btn;
        };

        // --- Sort trigger ---
        int[] sortSel = {librarySortMode};
        String sortPrefix = ui("Sort by", "Сортировка", "Trier par", "Ordina per",
                "並び順", "Sortare după", "排序方式");
        String groupPrefix = ui("Group by", "Группировка", "Grouper par", "Raggruppa per",
                "グループ", "Grupare după", "分组方式");
        String[] sortTriggerLabel = {sortPrefix + ": " + sortLabels[librarySortMode]};
        JButton sortTrigger = makeTrigger.apply(
                sortPrefix + ": " + sortLabels[librarySortMode] + "  v");
        metroLibrarySortTrigger = sortTrigger;

        // --- Group trigger ---
        int[] groupSel = {libraryGroupMode};
        JButton groupTrigger = makeTrigger.apply(
                groupPrefix + ": " + groupLabels[libraryGroupMode] + "  v");
        metroLibraryGroupTrigger = groupTrigger;

        // --- Sort option pills ---
        java.util.List<JButton> sortOpts = new java.util.ArrayList<>();
        for (int i = 0; i < sortLabels.length; i++) {
            JButton opt = makeOpt.apply(sortLabels[i], i == librarySortMode);
            final int idx = i;
            opt.addActionListener(e -> {
                sortSel[0] = idx;
                for (int j = 0; j < sortOpts.size(); j++) {
                    boolean on = (j == idx);
                    sortOpts.get(j).putClientProperty("active", on);
                    sortOpts.get(j).setFont(sortOpts.get(j).getFont().deriveFont(on ? Font.BOLD : Font.PLAIN, 12f));
                    sortOpts.get(j).setForeground(on ? Color.BLACK : MR_TEXT_DIM);
                    sortOpts.get(j).repaint();
                }
                sortTrigger.setText(sortPrefix + ": " + sortLabels[idx] + "  v");
                // collapse
                openDropdown[0] = 0;
                sortTrigger.putClientProperty("open", false); sortTrigger.repaint();
                animateLibraryFilterRow(expandedRow, false);
                librarySortMode = idx; libraryManualOrder = false; saveLibraryOrder(); refreshLibraryScreen();
            });
            sortOpts.add(opt);
        }

        // --- Group option pills ---
        java.util.List<JButton> groupOpts = new java.util.ArrayList<>();
        for (int i = 0; i < groupLabels.length; i++) {
            JButton opt = makeOpt.apply(groupLabels[i], i == libraryGroupMode);
            final int idx = i;
            opt.addActionListener(e -> {
                groupSel[0] = idx;
                for (int j = 0; j < groupOpts.size(); j++) {
                    boolean on = (j == idx);
                    groupOpts.get(j).putClientProperty("active", on);
                    groupOpts.get(j).setFont(groupOpts.get(j).getFont().deriveFont(on ? Font.BOLD : Font.PLAIN, 12f));
                    groupOpts.get(j).setForeground(on ? Color.BLACK : MR_TEXT_DIM);
                    groupOpts.get(j).repaint();
                }
                groupTrigger.setText(groupPrefix + ": " + groupLabels[idx] + "  v");
                // collapse
                openDropdown[0] = 0;
                groupTrigger.putClientProperty("open", false); groupTrigger.repaint();
                animateLibraryFilterRow(expandedRow, false);
                libraryGroupMode = idx; refreshLibraryScreen();
            });
            groupOpts.add(opt);
        }

        // --- Toggle logic ---
        sortTrigger.addActionListener(e -> {
            boolean opening = openDropdown[0] != 1;
            openDropdown[0] = opening ? 1 : 0;
            sortTrigger.putClientProperty("open", opening);
            groupTrigger.putClientProperty("open", false);
            sortTrigger.repaint(); groupTrigger.repaint();
            expandedRow.removeAll();
            if (opening) {
                for (JButton b : sortOpts) expandedRow.add(b);
                dropdownHost.removeAll();
                dropdownHost.add(expandedRow, BorderLayout.WEST);
                animateLibraryFilterRow(expandedRow, true);
            } else {
                animateLibraryFilterRow(expandedRow, false);
            }
            expandedRow.revalidate(); expandedRow.repaint();
        });

        groupTrigger.addActionListener(e -> {
            boolean opening = openDropdown[0] != 2;
            openDropdown[0] = opening ? 2 : 0;
            groupTrigger.putClientProperty("open", opening);
            sortTrigger.putClientProperty("open", false);
            sortTrigger.repaint(); groupTrigger.repaint();
            expandedRow.removeAll();
            if (opening) {
                for (JButton b : groupOpts) expandedRow.add(b);
                dropdownHost.removeAll();
                dropdownHost.add(expandedRow, BorderLayout.EAST);
                animateLibraryFilterRow(expandedRow, true);
            } else {
                animateLibraryFilterRow(expandedRow, false);
            }
            expandedRow.revalidate(); expandedRow.repaint();
        });

        triggersRow.add(sortTrigger);
        triggersRow.add(groupTrigger);

        triggersRow.setAlignmentX(Component.RIGHT_ALIGNMENT);
        int dropdownHostWidth = triggersRow.getPreferredSize().width;
        dropdownHost.setMaximumSize(new Dimension(dropdownHostWidth, Integer.MAX_VALUE));
        dropdownHost.setAlignmentX(Component.RIGHT_ALIGNMENT);
        expandedRow.setAlignmentX(Component.RIGHT_ALIGNMENT);
        controlsCol.add(triggersRow);
        controlsCol.add(dropdownHost);
        topBar.add(controlsCol, BorderLayout.EAST);

        // Search bar below tabs
        JPanel searchRow = new JPanel(new BorderLayout(0, 0));
        metroLibrarySearchRow = searchRow;
        searchRow.setOpaque(false);
        searchRow.setBorder(BorderFactory.createEmptyBorder(12, 0, 12, 0));
        RoundedTextField searchField = new RoundedTextField(14);
        searchField.setBackground(MR_CARD);
        searchField.setForeground(MR_TEXT);
        searchField.setCaretColor(MR_TEXT);
        searchField.setBorder(BorderFactory.createEmptyBorder(8, 14, 8, 14));
        searchField.putClientProperty("JTextField.placeholderText", "Search");
        searchField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override public void insertUpdate(javax.swing.event.DocumentEvent e) { filterLibraryInstances(searchField.getText()); }
            @Override public void removeUpdate(javax.swing.event.DocumentEvent e) { filterLibraryInstances(searchField.getText()); }
            @Override public void changedUpdate(javax.swing.event.DocumentEvent e) { filterLibraryInstances(searchField.getText()); }
        });
        searchRow.add(searchField, BorderLayout.CENTER);
        topBar.add(searchRow, BorderLayout.SOUTH);

        root.add(topBar, BorderLayout.NORTH);

        // ── Instance grid — vertical stack of rows (each row wraps cards) ────
        libraryInstanceGrid = new JPanel();
        libraryInstanceGrid.setLayout(new BoxLayout(libraryInstanceGrid, BoxLayout.Y_AXIS));
        libraryInstanceGrid.setOpaque(false);
        libraryInstanceGrid.setBorder(BorderFactory.createEmptyBorder(4, 6, 8, 6));

        // Wrap in an outer panel anchored to the top so rows stack downward
        // and the scrollpane's viewport tracks width correctly.
        libraryInstanceColumn = new JPanel(new BorderLayout());
        libraryInstanceColumn.setOpaque(false);
        libraryInstanceColumn.add(libraryInstanceGrid, BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(libraryInstanceColumn);
        scroll.setOpaque(false);
        scroll.getViewport().setOpaque(false);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        styleScrollBar(scroll.getVerticalScrollBar());
        root.add(scroll, BorderLayout.CENTER);

        return isMetroUi()
                ? metroScreenFrame(t("button.openLibraries"),
                ui("Installed profiles", "Установленные профили", "Profils installés", "Profili installati", "インストール済み", "Profiluri instalate", "已安装配置"),
                "library", new Color(127, 186, 0), root)
                : root;
    }

    private void setActiveLibraryTab(int index) {
        activeLibraryTab = index;
        for (int i = 0; i < libraryTabButtons.size(); i++) {
            libraryTabButtons.get(i).setActive(i == index);
        }
        if (libraryTabsRow instanceof AnimatedPillTabRow animatedTabsRow
                && index >= 0 && index < libraryTabButtons.size()) {
            animatedTabsRow.setActiveButton(libraryTabButtons.get(index), true);
        }
        refreshLibraryScreen();
    }

    private void filterLibraryInstances(String query) {
        if (libraryInstanceGrid == null) return;
        String needle = query == null ? "" : query.trim().toLowerCase();
        // libraryInstanceGrid is now BoxLayout Y_AXIS with row panels inside
        for (Component row : libraryInstanceGrid.getComponents()) {
            if (row instanceof JPanel rowPanel) {
                boolean rowHasVisible = false;
                for (Component c : rowPanel.getComponents()) {
                    if (c instanceof JComponent jc) {
                        Object id = jc.getClientProperty("msc.instanceId");
                        if (id != null) {
                            boolean visible = needle.isEmpty() || id.toString().toLowerCase().contains(needle);
                            jc.setVisible(visible);
                            if (visible) rowHasVisible = true;
                        } else {
                            jc.setVisible(true); // non-card items always visible
                            rowHasVisible = true;
                        }
                    }
                }
                // Hide header rows when no cards visible below (handled by row itself)
                if (rowPanel.getClientProperty("msc.headerRow") == Boolean.TRUE) {
                    // headers stay visible; their associated card row handles visibility
                }
            }
        }
        libraryInstanceGrid.revalidate();
        libraryInstanceGrid.repaint();
    }

    private void animateLibraryFilterRow(JPanel row, boolean show) {
        Object previous = row.getClientProperty("msc.dropdownAnimation");
        if (previous instanceof Timer running) running.stop();
        int contentHeight = 0;
        for (Component component : row.getComponents()) {
            contentHeight += component.getPreferredSize().height;
        }
        int fullHeight = Math.max(42, contentHeight);
        int start = row.isVisible() ? Math.max(0, row.getHeight()) : 0;
        int target = show ? fullHeight : 0;
        row.setVisible(true);
        if (!LinuxUiSupport.animationsEnabled()) {
            row.setPreferredSize(show ? null : new Dimension(0, 0));
            row.setVisible(show);
            row.revalidate();
            return;
        }
        long startedAt = System.currentTimeMillis();
        Timer timer = new Timer(15, null);
        timer.addActionListener(event -> {
            float progress = Math.min(1f, (System.currentTimeMillis() - startedAt) / 320f);
            int height = Math.round(start + (target - start) * smoothStep(progress));
            row.setPreferredSize(new Dimension(Math.max(1, row.getPreferredSize().width), height));
            row.revalidate();
            if (row.getParent() != null) row.getParent().revalidate();
            if (progress >= 1f) {
                timer.stop();
                row.putClientProperty("msc.dropdownAnimation", null);
                row.setPreferredSize(show ? null : new Dimension(0, 0));
                row.setVisible(show);
            }
        });
        row.putClientProperty("msc.dropdownAnimation", timer);
        timer.start();
    }

    /**
     * Pill trigger button that, when clicked, expands a row of option-pills below it.
     * Clicking the trigger again (or picking an option) collapses the row.
     *
     * Layout (Y_AXIS BoxLayout inside the returned panel):
     *   [ trigger pill: "Sort by: Name  ▾" ]
     *   [ option pills: Name | Date | Loader ]  ← hidden until expanded
     */
    private JPanel buildExpandablePillDropdown(String prefix, String initialLabel,
                                               String[] options, int activeIdx,
                                               java.util.function.IntConsumer onSelect) {
        Color DARK_ACTIVE  = MR_BORDER;
        Color DARK_HOVER   = MR_CARD;
        Color BORDER_COLOR = MR_ACCENT;

        // ── State ────────────────────────────────────────────────────────────
        int[] selectedIdx = {activeIdx};
        boolean[] expanded = {false};

        // ── Options row (hidden initially) ───────────────────────────────────
        JPanel optionsRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        optionsRow.setOpaque(false);
        optionsRow.setVisible(false);

        // ── Trigger pill ─────────────────────────────────────────────────────
        JButton trigger = new JButton() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                int arc = getHeight();
                Color fill = expanded[0] ? DARK_ACTIVE : (getModel().isRollover() ? DARK_HOVER : MR_SIDEBAR);
                g2.setColor(fill);
                g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                if (expanded[0]) {
                    g2.setColor(BORDER_COLOR);
                    g2.setStroke(new java.awt.BasicStroke(1f));
                    g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth()-1f, getHeight()-1f, arc, arc));
                }
                g2.dispose();
                super.paintComponent(g);
            }
        };
        trigger.setFocusPainted(false);
        trigger.setBorderPainted(false);
        trigger.setContentAreaFilled(false);
        trigger.setOpaque(false);
        trigger.setRolloverEnabled(true);
        trigger.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        trigger.setBorder(BorderFactory.createEmptyBorder(5, 14, 5, 14));
        trigger.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);

        java.util.function.Consumer<String> updateTriggerText = lbl -> {
            trigger.setText("<html><span style='color:#a0a0a8'>" + prefix + ":</span>"
                    + " <b>" + lbl + "</b>"
                    + "  <span style='color:#6b8cce'>&#9662;</span></html>");
        };
        updateTriggerText.accept(options[activeIdx]);
        trigger.setForeground(MR_TEXT);
        trigger.setFont(trigger.getFont().deriveFont(Font.PLAIN, 12f));

        // ── Option pills ──────────────────────────────────────────────────────
        java.util.List<JButton> optBtns = new java.util.ArrayList<>();
        for (int i = 0; i < options.length; i++) {
            final int idx = i;
            final boolean[] isActive = {i == activeIdx};
            JButton opt = new JButton(options[i]) {
                @Override
                protected void paintComponent(Graphics g) {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    int arc = getHeight();
                    if (isActive[0]) {
                        g2.setColor(DARK_ACTIVE);
                        g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                        g2.setColor(BORDER_COLOR);
                        g2.setStroke(new java.awt.BasicStroke(1f));
                        g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth()-1f, getHeight()-1f, arc, arc));
                    } else if (getModel().isRollover()) {
                        g2.setColor(DARK_HOVER);
                        g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                    }
                    g2.dispose();
                    super.paintComponent(g);
                }
            };
            opt.setFont(opt.getFont().deriveFont(isActive[0] ? Font.BOLD : Font.PLAIN, 12f));
            opt.setForeground(isActive[0] ? MR_TEXT : MR_TEXT_DIM);
            opt.setFocusPainted(false);
            opt.setBorderPainted(false);
            opt.setContentAreaFilled(false);
            opt.setOpaque(false);
            opt.setRolloverEnabled(true);
            opt.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            opt.setBorder(BorderFactory.createEmptyBorder(4, 12, 4, 12));
            opt.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
            opt.putClientProperty("isActive", isActive);
            optBtns.add(opt);
            optionsRow.add(opt);

            opt.addActionListener(e -> {
                // Update active state on all option buttons
                for (int j = 0; j < optBtns.size(); j++) {
                    boolean[] a = (boolean[]) optBtns.get(j).getClientProperty("isActive");
                    a[0] = (j == idx);
                    optBtns.get(j).setFont(optBtns.get(j).getFont().deriveFont(a[0] ? Font.BOLD : Font.PLAIN, 12f));
                    optBtns.get(j).setForeground(a[0] ? MR_TEXT : MR_TEXT_DIM);
                    optBtns.get(j).repaint();
                }
                selectedIdx[0] = idx;
                updateTriggerText.accept(options[idx]);
                trigger.repaint();
                // Collapse
                expanded[0] = false;
                optionsRow.setVisible(false);
                onSelect.accept(idx);
            });
        }

        // ── Trigger toggle ────────────────────────────────────────────────────
        trigger.addActionListener(e -> {
            expanded[0] = !expanded[0];
            optionsRow.setVisible(expanded[0]);
            trigger.repaint();
        });

        // ── Wrapper ───────────────────────────────────────────────────────────
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setOpaque(false);
        JPanel triggerRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        triggerRow.setOpaque(false);
        triggerRow.add(trigger);
        wrapper.add(triggerRow);
        wrapper.add(optionsRow);
        return wrapper;
    }

    /**
     * Builds a labelled pill-button group like "Sort by: [Name] [Date] [Loader]".
     * Active button gets a dark raised fill; inactive buttons are transparent.
     */
    private JPanel buildDarkPillGroup(String label, String[] options, int activeIdx,
                                      java.util.function.IntConsumer onSelect) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        row.setOpaque(false);

        JLabel lbl = new JLabel(label);
        lbl.setForeground(MR_TEXT_DIM);
        lbl.setFont(lbl.getFont().deriveFont(Font.PLAIN, 12f));
        lbl.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
        row.add(lbl);

        // Active pill fill — dark raised look in dark theme, light raised look in light theme
        Color DARK_ACTIVE_FILL = MR_LIGHT_ACTIVE ? new Color(222, 224, 230) : new Color(55, 58, 66);
        Color DARK_HOVER_FILL  = MR_LIGHT_ACTIVE ? new Color(232, 234, 238) : new Color(44, 46, 53);

        java.util.List<JButton> btns = new java.util.ArrayList<>();
        for (int i = 0; i < options.length; i++) {
            final int idx = i;
            final boolean[] active = {i == activeIdx};
            JButton btn = new JButton(options[i]) {
                @Override
                protected void paintComponent(Graphics g) {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    int arc = getHeight();
                    if (active[0]) {
                        g2.setColor(DARK_ACTIVE_FILL);
                        g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                        g2.setColor(MR_LIGHT_ACTIVE ? new Color(190, 193, 202) : new Color(80, 84, 95));
                        g2.setStroke(new java.awt.BasicStroke(1f));
                        g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth()-1f, getHeight()-1f, arc, arc));
                    } else if (getModel().isRollover()) {
                        g2.setColor(DARK_HOVER_FILL);
                        g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                    }
                    g2.dispose();
                    super.paintComponent(g);
                }
            };
            btn.setFont(btn.getFont().deriveFont(active[0] ? Font.BOLD : Font.PLAIN, 12f));
            btn.setForeground(active[0] ? MR_TEXT : MR_TEXT_DIM);
            btn.setFocusPainted(false);
            btn.setBorderPainted(false);
            btn.setContentAreaFilled(false);
            btn.setOpaque(false);
            btn.setRolloverEnabled(true);
            btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            btn.setBorder(BorderFactory.createEmptyBorder(5, 12, 5, 12));
            btn.putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
            btn.putClientProperty("active", active);
            btns.add(btn);

            btn.addActionListener(e -> {
                for (int j = 0; j < btns.size(); j++) {
                    boolean[] a = (boolean[]) btns.get(j).getClientProperty("active");
                    a[0] = (j == idx);
                    btns.get(j).setFont(btns.get(j).getFont().deriveFont(a[0] ? Font.BOLD : Font.PLAIN, 12f));
                    btns.get(j).setForeground(a[0] ? MR_TEXT : MR_TEXT_DIM);
                    btns.get(j).repaint();
                }
                onSelect.accept(idx);
            });

            row.add(btn);
        }
        return row;
    }

    private void styleRoundedCombo(JComboBox<String> combo, int width) {
        combo.setForeground(MR_TEXT);
        combo.setBackground(MR_CARD);
        combo.setPreferredSize(new Dimension(width, 34));
        combo.setBorder(BorderFactory.createEmptyBorder(2, 16, 2, 28));
        combo.setFocusable(false);
        // Dark renderer so popup list also uses dark, violet-accented colors.
        combo.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value,
                                                          int index, boolean isSelected, boolean cellHasFocus) {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                setBackground(isSelected ? ACCENT : MR_CARD);
                setForeground(isSelected ? Color.WHITE : MR_TEXT);
                setBorder(BorderFactory.createEmptyBorder(6, 14, 6, 14));
                setOpaque(true);
                return this;
            }
        });
        // Belt-and-suspenders: force popup UI dark even if the platform L&F
        // ignores our custom ComboPopup (covers edge cases on some JREs).
        combo.addPopupMenuListener(new javax.swing.event.PopupMenuListener() {
            @Override public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e) {
                Object popup = combo.getUI().getAccessibleChild(combo, 0);
                if (popup instanceof javax.swing.plaf.basic.ComboPopup cp) {
                    cp.getList().setBackground(MR_CARD);
                    cp.getList().setForeground(MR_TEXT);
                    cp.getList().setSelectionBackground(ACCENT);
                    cp.getList().setSelectionForeground(Color.WHITE);
                    JComponent popupComp = (JComponent) popup;
                    popupComp.setBorder(BorderFactory.createLineBorder(ACCENT));
                    popupComp.setBackground(MR_CARD);
                    Component scroller = cp.getList().getParent();
                    while (scroller != null && !(scroller instanceof JScrollPane)) scroller = scroller.getParent();
                    if (scroller instanceof JScrollPane sp) {
                        sp.setOpaque(true);
                        sp.getViewport().setOpaque(true);
                        sp.getViewport().setBackground(MR_CARD);
                        sp.setBorder(BorderFactory.createEmptyBorder());
                    }
                }
            }
            @Override public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e) {}
            @Override public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e) {}
        });
    }

    /**
     * Renders a player name the way Minecraft draws nameplates: a bold,
     * unhinted pixel-style font with a 1px dark drop-shadow offset, no
     * antialiasing so the glyph edges stay crisp/pixelated like the game's
     * own font renderer.
     */
    private static final class MinecraftNicknameLabel extends JComponent {
        private static final Color SHADOW = new Color(63, 63, 63);
        private static final Color FILL = Color.WHITE;
        private String text;

        private MinecraftNicknameLabel(String text) {
            this.text = text == null ? "" : text;
            setOpaque(false);
            setFont(pixelFont());
            setAlignmentX(Component.CENTER_ALIGNMENT);
        }

        void setText(String text) {
            this.text = text == null ? "" : text;
            revalidate();
            repaint();
        }

        private static Font pixelFont() {
            // Monospaced + bold most closely mimics Minecraft's blocky glyph
            // proportions without needing a bundled .ttf asset.
            return new Font(Font.MONOSPACED, Font.BOLD, 20);
        }

        @Override
        public Dimension getPreferredSize() {
            FontMetrics fm = getFontMetrics(getFont());
            return new Dimension(fm.stringWidth(text) + 4, fm.getHeight() + 4);
        }

        @Override
        public Dimension getMaximumSize() {
            return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            // Deliberately no antialiasing — Minecraft's bitmap font is crisp/pixelated.
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
            g2.setFont(getFont());
            FontMetrics fm = g2.getFontMetrics();
            int textWidth = fm.stringWidth(text);
            int x = Math.max(0, (getWidth() - textWidth) / 2);
            int y = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
            g2.setColor(SHADOW);
            g2.drawString(text, x + 2, y + 2);
            g2.setColor(FILL);
            g2.drawString(text, x, y);
            g2.dispose();
        }
    }


    /**
     * Fully custom rounded "pill"-button style combo box that paints as one
     * seamless dark surface — label and chevron share the same fill, so
     * there's no separate arrow chip/button glued on the side. The popup
     * list is forced dark too, regardless of platform look-and-feel.
     */
    private static final class RoundedComboBox<E> extends JComboBox<E> {
        private boolean hover = false;

        private RoundedComboBox(E[] items) {
            super(items);
            setOpaque(false);
            setFocusable(false);
            setBorder(BorderFactory.createEmptyBorder());
            addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mouseEntered(java.awt.event.MouseEvent e) { hover = true; repaint(); }
                @Override public void mouseExited(java.awt.event.MouseEvent e) { hover = false; repaint(); }
            });
        }

        @Override
        public void updateUI() {
            setUI(new RoundedComboBoxUI());
            setBorder(BorderFactory.createEmptyBorder());
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth(), h = getHeight(), arc = h;
            boolean open = isPopupVisible();
            Color fill = open
                    ? new Color(22, 36, 58, 185)
                    : (hover
                    ? new Color(20, 32, 52, 172)
                    : new Color(MR_CARD.getRed(), MR_CARD.getGreen(), MR_CARD.getBlue(), 145));
            g2.setColor(fill);
            g2.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
            g2.setColor(open || hover ? ACCENT : MR_BORDER);
            g2.setStroke(new java.awt.BasicStroke(open ? 1.6f : 1f));
            g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, arc, arc));
            // Chevron painted directly on the pill — no separate button chip.
            int cx = w - 16, cy = h / 2;
            g2.setColor(ACCENT);
            java.awt.geom.Path2D.Float chevron = new java.awt.geom.Path2D.Float();
            chevron.moveTo(cx - 4.5f, cy - 2f);
            chevron.lineTo(cx, cy + 3f);
            chevron.lineTo(cx + 4.5f, cy - 2f);
            g2.setStroke(new java.awt.BasicStroke(1.8f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
            g2.draw(chevron);
            g2.dispose();
            // Prevent LAF from painting a white/default background rectangle on top.
            Color prevBg = getBackground();
            setBackground(new Color(0, 0, 0, 0));
            super.paintComponent(g);
            setBackground(prevBg);
        }

        private final class RoundedComboBoxUI extends javax.swing.plaf.basic.BasicComboBoxUI {
            @Override
            protected JButton createArrowButton() {
                // Zero-footprint — the chevron is painted by the combo's own
                // paintComponent, so there's nothing separate to click on.
                JButton invisible = new JButton();
                invisible.setOpaque(false);
                invisible.setContentAreaFilled(false);
                invisible.setBorderPainted(false);
                invisible.setFocusPainted(false);
                invisible.setBorder(BorderFactory.createEmptyBorder());
                invisible.setPreferredSize(new Dimension(0, 0));
                return invisible;
            }

            @Override
            public void paint(Graphics g, JComponent c) {
                // Background already painted by RoundedComboBox.paintComponent.
                super.paint(g, c);
            }

            @Override
            protected ComboBoxEditor createEditor() {
                return super.createEditor();
            }

            @Override
            public void paintCurrentValueBackground(Graphics g, Rectangle bounds, boolean hasFocus) {
                // RoundedComboBox paints the complete glass surface itself. The native
                // background is rectangular and used to cover the loader button.
            }

            @Override
            public void paintCurrentValue(Graphics g, java.awt.Rectangle bounds, boolean hasFocus) {
                Object item = comboBox.getSelectedItem();
                String text = item == null ? "" : item.toString();
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);
                Font font = comboBox.getFont() != null ? comboBox.getFont() : g2.getFont();
                g2.setFont(font);
                FontMetrics fm = g2.getFontMetrics();
                int x = bounds.x + 2, y = bounds.y + (bounds.height + fm.getAscent() - fm.getDescent()) / 2;
                int colonIdx = text.indexOf(':');
                if (colonIdx >= 0) {
                    String prefix = text.substring(0, colonIdx + 1) + " ";
                    String value  = text.substring(colonIdx + 1).trim();
                    g2.setColor(MR_TEXT_DIM);
                    g2.drawString(prefix, x, y);
                    int prefixW = fm.stringWidth(prefix);
                    g2.setColor(ACCENT);
                    g2.drawString(value, x + prefixW, y);
                } else {
                    g2.setColor(comboBox.getForeground());
                    g2.drawString(text, x, y);
                }
                g2.dispose();
            }

            @Override
            protected javax.swing.plaf.basic.ComboPopup createPopup() {
                javax.swing.plaf.basic.BasicComboPopup popup = new javax.swing.plaf.basic.BasicComboPopup(comboBox) {
                    @Override
                    protected JScrollPane createScroller() {
                        JScrollPane sp = new JScrollPane(list,
                                javax.swing.ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
                                javax.swing.ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
                        sp.setOpaque(false);
                        sp.getViewport().setOpaque(false);
                        sp.setBorder(BorderFactory.createEmptyBorder());
                        styleScrollBarStatic(sp.getVerticalScrollBar());
                        return sp;
                    }

                    @Override
                    protected void paintComponent(Graphics g) {
                        Graphics2D g2 = (Graphics2D) g.create();
                        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                        int w = getWidth();
                        int h = getHeight();
                        g2.setColor(new Color(
                                MR_CARD.getRed(), MR_CARD.getGreen(), MR_CARD.getBlue(), 208));
                        g2.fill(new RoundRectangle2D.Float(0, 0, w, h, 20, 20));
                        g2.setPaint(new GradientPaint(
                                0, 0, new Color(255, 255, 255, 24),
                                0, Math.max(1, h / 2f), new Color(255, 255, 255, 0)));
                        g2.fill(new RoundRectangle2D.Float(1, 1, Math.max(0, w - 2), Math.max(0, h - 2), 19, 19));
                        g2.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 135));
                        g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f,
                                Math.max(0, w - 1f), Math.max(0, h - 1f), 20, 20));
                        g2.dispose();
                    }
                };
                popup.setOpaque(false);
                popup.setBackground(new Color(0, 0, 0, 0));
                popup.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));
                popup.getList().setOpaque(false);
                popup.getList().setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
                popup.getList().setForeground(MR_TEXT);
                popup.getList().setFixedCellHeight(26);
                popup.getList().setSelectionBackground(new Color(
                        ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 150));
                popup.getList().setSelectionForeground(Color.WHITE);
                popup.getList().setCellRenderer(new DefaultListCellRenderer() {
                    @Override
                    public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                                  boolean isSelected, boolean cellHasFocus) {
                        JLabel label = (JLabel) super.getListCellRendererComponent(
                                list, value, index, isSelected, cellHasFocus);
                        label.setOpaque(isSelected);
                        label.setBackground(isSelected
                                ? new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 150)
                                : new Color(0, 0, 0, 0));
                        label.setForeground(isSelected ? Color.WHITE : MR_TEXT);
                        label.setBorder(BorderFactory.createEmptyBorder(4, 9, 4, 9));
                        return label;
                    }
                });
                return popup;
            }
        }
    }

    /**
     * Dark "pill" combo used for game-version selection. The whole control —
     * label and chevron — paints as a single seamless surface (no separate
     * arrow chip/button), with an accent-colored chevron that just sits
     * inside the same fill, plus a fully dark popup list with a custom
     * scrollbar so the version dropdown never flashes the native light L&F.
     */
    private static final class VersionPillComboBox<E> extends JComboBox<E> {
        private boolean hover = false;

        private VersionPillComboBox() {
            super();
            setOpaque(false);
            setFocusable(false);
            addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mouseEntered(java.awt.event.MouseEvent e) { hover = true; repaint(); }
                @Override public void mouseExited(java.awt.event.MouseEvent e) { hover = false; repaint(); }
            });
        }

        @Override
        public void updateUI() {
            setUI(new VersionPillComboUI());
            setFont(getFont() != null ? getFont() : UIManager.getFont("ComboBox.font"));
            setBorder(BorderFactory.createEmptyBorder(0, 16, 0, 34));
            setForeground(MR_TEXT);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth(), h = getHeight();
            boolean open = isPopupVisible();
            Color fill = open ? new Color(38, 34, 54) : (hover ? new Color(34, 31, 46) : new Color(22, 20, 30));
            g2.setColor(fill);
            g2.fill(new RoundRectangle2D.Float(0, 0, w, h, h, h));
            // Accent edge — thicker / glowing when open, subtle violet hairline otherwise.
            g2.setColor(open ? MR_VERSION_ACCENT : new Color(70, 62, 96));
            g2.setStroke(new java.awt.BasicStroke(open ? 1.6f : 1f));
            g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, h, h));
            // Chevron — drawn directly on the same surface, no separate button chip.
            int cx = w - 18, cy = h / 2;
            g2.setColor(MR_VERSION_ACCENT);
            java.awt.geom.Path2D.Float chevron = new java.awt.geom.Path2D.Float();
            chevron.moveTo(cx - 5, cy - 2.5);
            chevron.lineTo(cx, cy + 3.5);
            chevron.lineTo(cx + 5, cy - 2.5);
            g2.setStroke(new java.awt.BasicStroke(2f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
            g2.draw(chevron);
            g2.dispose();
            Color prevBg = getBackground();
            setBackground(new Color(0, 0, 0, 0));
            super.paintComponent(g);
            setBackground(prevBg);
        }

        private final class VersionPillComboUI extends javax.swing.plaf.basic.BasicComboBoxUI {
            @Override
            protected JButton createArrowButton() {
                // Invisible zero-footprint button — the chevron is painted by
                // the combo itself, so there is no separate clickable chip.
                JButton invisible = new JButton();
                invisible.setOpaque(false);
                invisible.setContentAreaFilled(false);
                invisible.setBorderPainted(false);
                invisible.setFocusPainted(false);
                invisible.setBorder(BorderFactory.createEmptyBorder());
                invisible.setPreferredSize(new Dimension(0, 0));
                return invisible;
            }

            @Override
            public void paintCurrentValueBackground(Graphics g, Rectangle bounds, boolean hasFocus) {
                // Background already painted by VersionPillComboBox.paintComponent.
            }

            @Override
            protected ComboBoxEditor createEditor() {
                return super.createEditor();
            }

            @Override
            protected javax.swing.plaf.basic.ComboPopup createPopup() {
                javax.swing.plaf.basic.BasicComboPopup popup = new javax.swing.plaf.basic.BasicComboPopup(comboBox) {
                    @Override
                    protected JScrollPane createScroller() {
                        JScrollPane sp = new JScrollPane(list,
                                javax.swing.ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
                                javax.swing.ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
                        sp.setOpaque(true);
                        sp.setBackground(MR_CARD);
                        sp.getViewport().setOpaque(true);
                        sp.getViewport().setBackground(MR_CARD);
                        sp.setBorder(BorderFactory.createEmptyBorder());
                        styleScrollBarStatic(sp.getVerticalScrollBar());
                        return sp;
                    }
                };
                popup.setBackground(MR_CARD);
                popup.setBorder(BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(MR_VERSION_ACCENT, 1),
                        BorderFactory.createEmptyBorder(4, 0, 4, 0)));
                popup.getList().setBackground(MR_CARD);
                popup.getList().setForeground(MR_TEXT);
                popup.getList().setSelectionBackground(MR_VERSION_ACCENT);
                popup.getList().setSelectionForeground(Color.WHITE);
                popup.getList().setFont(comboBox.getFont());
                popup.getList().setCellRenderer(new DefaultListCellRenderer() {
                    @Override
                    public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                                  boolean isSelected, boolean cellHasFocus) {
                        super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                        setBackground(isSelected ? MR_VERSION_ACCENT : new Color(26, 23, 34));
                        setForeground(isSelected ? Color.WHITE : MR_TEXT);
                        setBorder(BorderFactory.createEmptyBorder(6, 16, 6, 16));
                        setOpaque(true);
                        return this;
                    }
                });
                return popup;
            }
        }
    }

    /** Minimal static scrollbar dark-styling helper shared by custom popups. */
    private static void styleScrollBarStatic(JScrollBar bar) {
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(8, 8));
        bar.setUI(new javax.swing.plaf.basic.BasicScrollBarUI() {
            @Override protected void configureScrollBarColors() {}
            @Override protected JButton createDecreaseButton(int o) { return zeroButton(); }
            @Override protected JButton createIncreaseButton(int o) { return zeroButton(); }
            private JButton zeroButton() {
                JButton b = new JButton();
                b.setPreferredSize(new Dimension(0, 0));
                return b;
            }
            @Override protected void paintTrack(Graphics g, JComponent c, Rectangle r) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setColor(new Color(26, 23, 34));
                g2.fillRect(r.x, r.y, r.width, r.height);
                g2.dispose();
            }
            @Override protected void paintThumb(Graphics g, JComponent c, Rectangle r) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(new Color(110, 98, 150));
                g2.fillRoundRect(r.x + 1, r.y, r.width - 2, r.height, 4, 4);
                g2.dispose();
            }
        });
    }

    /** Text field with a fully rounded translucent background, matching the rest of the flat UI. */
    private static final class RoundedTextField extends JTextField {
        private final int arc;
        private RoundedTextField(int arc) {
            this.arc = arc;
            setOpaque(false);
        }
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(getBackground());
            g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
            g2.setColor(MR_BORDER);
            g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f, arc, arc));
            g2.dispose();
            super.paintComponent(g);
            Object placeholder = getClientProperty("JTextField.placeholderText");
            if (placeholder != null && getText().isEmpty()) {
                Graphics2D placeholderGraphics = (Graphics2D) g.create();
                placeholderGraphics.setRenderingHint(
                        RenderingHints.KEY_TEXT_ANTIALIASING,
                        RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                placeholderGraphics.setFont(getFont());
                FontMetrics metrics = placeholderGraphics.getFontMetrics();
                Insets insets = getInsets();
                int y = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
                placeholderGraphics.setColor(new Color(
                        TEXT_SECONDARY.getRed(), TEXT_SECONDARY.getGreen(), TEXT_SECONDARY.getBlue(), 155));
                placeholderGraphics.drawString(placeholder.toString(), insets.left, y);
                placeholderGraphics.dispose();
            }
        }
    }

    /**
     * Oval iOS/Android-style toggle switch used throughout the Modern UI
     * settings window in place of plain checkboxes. Extends {@link JCheckBox}
     * so all existing selection/listener/save-load code (isSelected(),
     * setSelected(), addItemListener()) keeps working unchanged — only the
     * painting is replaced.
     */
    /**
     * Custom drawn memory slider — a sleek modern horizontal track+thumb
     * that replaces the plain JSpinner for Xms / Xmx settings.
     * Values snap to multiples of {@code step} MB.
     */
    private static class MemorySlider extends JComponent {
        private int value;
        private final int min, max, step;
        private boolean dragging;
        private int dragStartX;
        private int dragStartValue;
        private final java.util.List<java.util.function.Consumer<Integer>> listeners = new java.util.ArrayList<>();

        MemorySlider(int value, int min, int max, int step) {
            this.value = clamp(value, min, max);
            this.min = min;
            this.max = max;
            this.step = step;
            setPreferredSize(new Dimension(220, 36));
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setOpaque(false);
            setFocusable(true);

            MouseAdapter ma = new MouseAdapter() {
                @Override public void mousePressed(MouseEvent e) {
                    dragging = true;
                    dragStartX = e.getX();
                    dragStartValue = MemorySlider.this.value;
                    requestFocusInWindow();
                    updateFromX(e.getX());
                }
                @Override public void mouseDragged(MouseEvent e) { updateFromX(e.getX()); }
                @Override public void mouseReleased(MouseEvent e) { dragging = false; }
            };
            addMouseListener(ma);
            addMouseMotionListener(ma);
            addKeyListener(new java.awt.event.KeyAdapter() {
                @Override public void keyPressed(java.awt.event.KeyEvent e) {
                    int delta = 0;
                    if (e.getKeyCode() == java.awt.event.KeyEvent.VK_LEFT  || e.getKeyCode() == java.awt.event.KeyEvent.VK_DOWN)  delta = -step;
                    if (e.getKeyCode() == java.awt.event.KeyEvent.VK_RIGHT || e.getKeyCode() == java.awt.event.KeyEvent.VK_UP)    delta = +step;
                    if (delta != 0) setValue(MemorySlider.this.value + delta);
                }
            });
        }

        private void updateFromX(int mx) {
            int trackPad = 14;
            int trackW = getWidth() - trackPad * 2;
            double ratio = Math.max(0.0, Math.min(1.0, (double)(mx - trackPad) / trackW));
            int raw = min + (int)Math.round(ratio * (max - min));
            // Snap to step
            int snapped = Math.round((float)(raw - min) / step) * step + min;
            setValue(clamp(snapped, min, max));
        }

        void setValue(int v) {
            int clamped = clamp(v, min, max);
            if (clamped == value) return;
            value = clamped;
            repaint();
            for (var l : listeners) l.accept(value);
        }

        int getValue() { return value; }

        void addChangeListener(java.util.function.Consumer<Integer> l) { listeners.add(l); }

        private static int clamp(int v, int lo, int hi) { return Math.max(lo, Math.min(hi, v)); }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

            int w = getWidth(), h = getHeight();
            boolean metro = Boolean.TRUE.equals(getClientProperty("msc.metroSlider"));
            int trackH = metro ? 14 : 5;
            int trackPad = 14;
            int trackW = w - trackPad * 2;
            int trackY = h / 2 - trackH / 2 + 6;

            double ratio = (double)(value - min) / (max - min);
            int thumbX = trackPad + (int)(ratio * trackW);
            int thumbR = metro ? 0 : 9;

            // Track background
            g2.setColor(metro ? new Color(31, 27, 39) : MR_LIGHT_ACTIVE ? new Color(200, 202, 210) : new Color(45, 48, 58));
            if (metro) {
                g2.fillRect(trackPad, trackY, trackW, trackH);
                g2.setColor(new Color(126, 78, 156, 90));
                g2.drawRect(trackPad, trackY, Math.max(0, trackW - 1), Math.max(0, trackH - 1));
            } else {
                g2.fillRoundRect(trackPad, trackY, trackW, trackH, trackH, trackH);
            }

            // Filled portion
            Color accent = metro ? new Color(150, 82, 190) : new Color(31, 135, 232);
            g2.setColor(accent);
            if (metro) {
                g2.fillRect(trackPad, trackY, Math.max(0, thumbX - trackPad), trackH);
                int thumbW = dragging || isFocusOwner() ? 18 : 14;
                int thumbH = trackH + 12;
                g2.setColor(dragging || isFocusOwner() ? new Color(205, 142, 238) : new Color(181, 104, 220));
                g2.fillRect(thumbX - thumbW / 2, trackY - 6, thumbW, thumbH);
                g2.setColor(new Color(248, 226, 255, 95));
                g2.drawRect(thumbX - thumbW / 2, trackY - 6, Math.max(0, thumbW - 1), Math.max(0, thumbH - 1));
            } else {
                g2.fillRoundRect(trackPad, trackY, thumbX - trackPad, trackH, trackH, trackH);

                // Thumb shadow
                g2.setColor(new Color(0, 0, 0, 60));
                g2.fillOval(thumbX - thumbR + 1, trackY - thumbR + trackH/2 + 2, thumbR*2, thumbR*2);

                // Thumb glow when focused/dragging
                if (isFocusOwner() || dragging) {
                    g2.setColor(new Color(31, 135, 232, 40));
                    g2.fillOval(thumbX - thumbR - 4, trackY - thumbR + trackH/2 - 4, (thumbR+4)*2, (thumbR+4)*2);
                }

                // Thumb
                g2.setColor(Color.WHITE);
                g2.fillOval(thumbX - thumbR, trackY - thumbR + trackH/2, thumbR*2, thumbR*2);
                g2.setColor(new Color(31, 135, 232));
                g2.setStroke(new BasicStroke(1.5f));
                g2.drawOval(thumbX - thumbR, trackY - thumbR + trackH/2, thumbR*2, thumbR*2);
                g2.setStroke(new BasicStroke(1f));
            }

            // Value label above thumb
            String label = value + " MB";
            Font f = getFont().deriveFont(Font.BOLD, 11f);
            g2.setFont(f);
            FontMetrics fm = g2.getFontMetrics();
            int lw = fm.stringWidth(label);
            int lx = Math.max(0, Math.min(thumbX - lw/2, w - lw));
            g2.setColor(metro ? new Color(226, 214, 236) : MR_LIGHT_ACTIVE ? new Color(60, 65, 78) : new Color(200, 210, 225));
            g2.drawString(label, lx, trackY - 4);

            g2.dispose();
        }
    }

    /**
     * A JPanel that implements Scrollable so it always fills the viewport width,
     * preventing horizontal overflow in settings scroll panes.
     */
    private static class ScrollablePanel extends JPanel implements javax.swing.Scrollable {
        ScrollablePanel(java.awt.LayoutManager layout) { super(layout); }
        ScrollablePanel() { super(); }
        @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
        @Override public int getScrollableUnitIncrement(Rectangle vr, int o, int d) { return 16; }
        @Override public int getScrollableBlockIncrement(Rectangle vr, int o, int d) { return 64; }
        @Override public boolean getScrollableTracksViewportWidth()  { return true; }
        @Override public boolean getScrollableTracksViewportHeight() { return false; }
    }

    /** Combo box that displays every known loader but rejects red, unsupported entries. */
    private final class SupportedLoaderComboBox
            extends JComboBox<ModInstallCompatibility.LoaderChoice> {
        private boolean updatingChoices;

        private SupportedLoaderComboBox() {
            super();
            putClientProperty("msc.compatibilityLoader", Boolean.TRUE);
            setPreferredSize(new Dimension(190, 32));
            installThemedLoaderUi();
            installCompatibilityRenderer();
            installSupportedKeyboardNavigation();
        }

        private void installThemedLoaderUi() {
            setUI(new javax.swing.plaf.basic.BasicComboBoxUI() {
                @Override
                protected JButton createArrowButton() {
                    JButton arrow = new JButton() {
                        @Override
                        protected void paintComponent(Graphics g) {
                            Graphics2D g2 = (Graphics2D) g.create();
                            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                                    RenderingHints.VALUE_ANTIALIAS_ON);
                            Color surface = isMetroUi() ? metroShiftColor(metroThemeColor(), -24)
                                    : isModernUi() ? MR_CARD : FIELD_BG;
                            if (getModel().isPressed()) {
                                surface = surface.darker();
                            } else if (getModel().isRollover()) {
                                surface = metroShiftColor(surface, 14);
                            }
                            g2.setColor(surface);
                            g2.fillRect(0, 0, getWidth(), getHeight());
                            g2.setColor(isMetroUi() ? metroAeroAccent(metroThemeColor())
                                    : isModernUi() ? MR_ACCENT : FOCUS);
                            int cx = getWidth() / 2;
                            int cy = getHeight() / 2;
                            java.awt.geom.Path2D.Float chevron = new java.awt.geom.Path2D.Float();
                            chevron.moveTo(cx - 4, cy - 2);
                            chevron.lineTo(cx, cy + 3);
                            chevron.lineTo(cx + 4, cy - 2);
                            g2.setStroke(new BasicStroke(1.8f,
                                    BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                            g2.draw(chevron);
                            g2.dispose();
                        }
                    };
                    arrow.setOpaque(false);
                    arrow.setContentAreaFilled(false);
                    arrow.setBorderPainted(false);
                    arrow.setFocusPainted(false);
                    arrow.setRolloverEnabled(true);
                    arrow.setPreferredSize(new Dimension(30, 30));
                    return arrow;
                }

                @Override
                public void paintCurrentValueBackground(Graphics g, Rectangle bounds,
                                                        boolean hasFocus) {
                    Color surface = isMetroUi() ? metroShiftColor(metroThemeColor(), -28)
                            : isModernUi() ? MR_CARD : FIELD_BG;
                    g.setColor(surface);
                    g.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                }
            });
            setOpaque(true);
            setBackground(isMetroUi() ? metroShiftColor(metroThemeColor(), -28)
                    : isModernUi() ? MR_CARD : FIELD_BG);
            setForeground(isModernUi() ? MR_TEXT : TEXT_PRIMARY);
            setBorder(BorderFactory.createLineBorder(isMetroUi()
                    ? new Color(255, 255, 255, 90) : MR_BORDER));
            setFocusable(false);
        }

        private void installSupportedKeyboardNavigation() {
            getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(
                    KeyStroke.getKeyStroke(KeyEvent.VK_DOWN, 0), "nextSupportedLoader");
            getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(
                    KeyStroke.getKeyStroke(KeyEvent.VK_UP, 0), "previousSupportedLoader");
            getActionMap().put("nextSupportedLoader", new AbstractAction() {
                @Override public void actionPerformed(ActionEvent e) {
                    selectSupportedLoader(1);
                }
            });
            getActionMap().put("previousSupportedLoader", new AbstractAction() {
                @Override public void actionPerformed(ActionEvent e) {
                    selectSupportedLoader(-1);
                }
            });
        }

        private void selectSupportedLoader(int direction) {
            int count = getItemCount();
            if (count == 0) {
                return;
            }
            int selected = Math.max(0, getSelectedIndex());
            for (int step = 1; step <= count; step++) {
                int index = Math.floorMod(selected + direction * step, count);
                ModInstallCompatibility.LoaderChoice choice = getItemAt(index);
                if (choice != null && choice.supported()) {
                    setSelectedIndex(index);
                    return;
                }
            }
        }

        private void installCompatibilityRenderer() {
            setRenderer(new DefaultListCellRenderer() {
                @Override
                public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                              boolean selected, boolean focus) {
                    JLabel label = (JLabel) super.getListCellRendererComponent(
                            list, value, index, selected, focus);
                    ModInstallCompatibility.LoaderChoice choice = value instanceof ModInstallCompatibility.LoaderChoice c
                            ? c : null;
                    String loader = choice == null ? "" : loaderDisplayName(choice.id());
                    label.setText(choice != null && !choice.supported()
                            ? loader + "  —  " + ui("Unsupported", "Не поддерживается",
                            "Non pris en charge", "Non supportato", "未対応",
                            "Neacceptat", "不支持")
                            : loader);
                    label.setBorder(BorderFactory.createEmptyBorder(5, 10, 5, 10));
                    label.setOpaque(true);
                    if (choice != null && !choice.supported()) {
                        boolean light = isModernUi() && MR_LIGHT_ACTIVE;
                        label.setBackground(light ? new Color(255, 226, 229)
                                : new Color(92, 31, 39));
                        label.setForeground(light ? new Color(166, 30, 45)
                                : new Color(255, 171, 179));
                        label.setEnabled(false);
                    } else {
                        label.setEnabled(true);
                        if (selected) {
                            label.setBackground(isMetroUi() ? metroThemeColor()
                                    : isModernUi() ? MR_ACCENT : SELECT_BG);
                            label.setForeground(Color.WHITE);
                        } else {
                            label.setBackground(isModernUi() ? MR_CARD : SURFACE_SOLID);
                            label.setForeground(isModernUi() ? MR_TEXT : TEXT_PRIMARY);
                        }
                    }
                    return label;
                }
            });
        }

        private void setChoices(List<ModInstallCompatibility.LoaderChoice> choices,
                                String preferredLoader) {
            updatingChoices = true;
            try {
                removeAllItems();
                ModInstallCompatibility.LoaderChoice first = null;
                ModInstallCompatibility.LoaderChoice preferred = null;
                String wanted = preferredLoader == null ? "" : preferredLoader.trim();
                for (ModInstallCompatibility.LoaderChoice choice : choices) {
                    addItem(choice);
                    if (choice.supported()) {
                        if (first == null) {
                            first = choice;
                        }
                        if (choice.id().equalsIgnoreCase(wanted)) {
                            preferred = choice;
                        }
                    }
                }
                super.setSelectedItem(preferred == null ? first : preferred);
                installCompatibilityRenderer();
            } finally {
                updatingChoices = false;
            }
        }

        private boolean hasSupportedLoader() {
            for (int index = 0; index < getItemCount(); index++) {
                ModInstallCompatibility.LoaderChoice choice = getItemAt(index);
                if (choice != null && choice.supported()) {
                    return true;
                }
            }
            return false;
        }

        private String selectedLoader() {
            Object selected = getSelectedItem();
            return selected instanceof ModInstallCompatibility.LoaderChoice choice && choice.supported()
                    ? choice.id() : "";
        }

        @Override
        public void setSelectedItem(Object item) {
            if (!updatingChoices && item instanceof ModInstallCompatibility.LoaderChoice choice
                    && !choice.supported()) {
                Toolkit.getDefaultToolkit().beep();
                return;
            }
            super.setSelectedItem(item);
        }

        private String loaderDisplayName(String id) {
            return switch (id == null ? "" : id.toLowerCase(java.util.Locale.ROOT)) {
                case "fabric" -> "Fabric";
                case "forge" -> "Forge";
                case "neoforge" -> "NeoForge";
                case "quilt" -> "Quilt";
                default -> id == null ? "" : id;
            };
        }
    }

    private static class ToggleSwitch extends JCheckBox {
        private float animPos; // 0 = off, 1 = on (animated)
        private float highlightPos; // 0 = normal, 1 = highlighted (animated)
        private javax.swing.Timer animTimer;
        private javax.swing.Timer highlightTimer;

        private ToggleSwitch(String text) {
            super(text);
            setOpaque(false);
            setFocusPainted(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setIconTextGap(10);
            setHorizontalAlignment(SwingConstants.LEFT);
            animPos = isSelected() ? 1f : 0f;
            setIcon(new Icon() {
                @Override public int getIconWidth() { return 44; }
                @Override public int getIconHeight() { return 24; }
                @Override public void paintIcon(Component c, Graphics g, int x, int y) {
                    paintTrack(g, x, y);
                }
            });
            addItemListener(e -> animateTo(isSelected() ? 1f : 0f));
            addMouseListener(new MouseAdapter() {
                @Override public void mouseEntered(MouseEvent e) {
                    animateHighlightTo(1f);
                }

                @Override public void mouseExited(MouseEvent e) {
                    animateHighlightTo(0f);
                }
            });
        }

        private void animateTo(float target) {
            if (!LinuxUiSupport.animationsEnabled()) {
                animPos = target;
                repaint();
                return;
            }
            if (animTimer != null && animTimer.isRunning()) animTimer.stop();
            animTimer = new javax.swing.Timer(12, null);
            animTimer.addActionListener(e -> {
                float step = 0.18f;
                if (Math.abs(animPos - target) <= step) {
                    animPos = target;
                    animTimer.stop();
                } else {
                    animPos += (target > animPos) ? step : -step;
                }
                repaint();
            });
            animTimer.start();
        }

        private void animateHighlightTo(float target) {
            if (!LinuxUiSupport.animationsEnabled()) {
                highlightPos = target;
                repaint();
                return;
            }
            if (highlightTimer != null && highlightTimer.isRunning()) highlightTimer.stop();
            highlightTimer = new javax.swing.Timer(12, null);
            highlightTimer.addActionListener(e -> {
                float step = 0.16f;
                if (Math.abs(highlightPos - target) <= step) {
                    highlightPos = target;
                    highlightTimer.stop();
                } else {
                    highlightPos += (target > highlightPos) ? step : -step;
                }
                repaint();
            });
            highlightTimer.start();
        }

        private void paintTrack(Graphics g, int x, int y) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int w = 44, h = 24;
            boolean metro = Boolean.TRUE.equals(getClientProperty("msc.metroToggle"));
            Color trackOn = metro ? new Color(146, 82, 190) : MR_ACCENT;
            Color trackOff = metro ? new Color(35, 31, 44) : MR_BORDER;
            Color knob = Color.WHITE;

            // Interpolate track color between off/on for a smooth color transition.
            float p = animPos;
            int r = (int) (trackOff.getRed()   + (trackOn.getRed()   - trackOff.getRed())   * p);
            int gC = (int) (trackOff.getGreen() + (trackOn.getGreen() - trackOff.getGreen()) * p);
            int b = (int) (trackOff.getBlue()  + (trackOn.getBlue()  - trackOff.getBlue())  * p);
            g2.setColor(new Color(r, gC, b));
            if (metro) {
                g2.fillRect(x, y + 2, w, h - 4);
                g2.setColor(new Color(126, 78, 156, 110));
                g2.drawRect(x, y + 2, w - 1, h - 5);
            } else {
                g2.fillRoundRect(x, y, w, h, h, h);
            }

            if (highlightPos > 0f && isEnabled()) {
                int alpha = (int) (55 + 95 * highlightPos);
                Color glow = isSelected() ? trackOn : new Color(210, 216, 226);
                g2.setColor(new Color(glow.getRed(), glow.getGreen(), glow.getBlue(), Math.min(150, alpha)));
                g2.setStroke(new BasicStroke(1.5f + 1.5f * highlightPos));
                if (metro) {
                    g2.drawRect(x - 1, y + 1, w + 1, h - 3);
                } else {
                    g2.drawRoundRect(x - 1, y - 1, w + 1, h + 1, h + 2, h + 2);
                    g2.setColor(new Color(255, 255, 255, (int) (28 * highlightPos)));
                    g2.fillRoundRect(x + 2, y + 2, w - 4, Math.max(1, h / 2 - 2), h - 4, h - 4);
                }
            }

            if (!isEnabled()) {
                g2.setColor(new Color(0, 0, 0, 70));
                if (metro) {
                    g2.fillRect(x, y + 2, w, h - 4);
                } else {
                    g2.fillRoundRect(x, y, w, h, h, h);
                }
            }

            // Knob
            int knobD = h - 4;
            int knobX = x + 2 + (int) ((w - knobD - 4) * p);
            int knobY = y + 2;
            if (metro) {
                int knobW = 12;
                int knobH = h;
                int metroKnobX = x + 3 + (int) ((w - knobW - 6) * p);
                g2.setColor(isSelected() ? new Color(222, 172, 244) : new Color(238, 232, 244));
                g2.fillRect(metroKnobX, y, knobW, knobH);
                g2.setColor(new Color(255, 255, 255, 90));
                g2.drawRect(metroKnobX, y, knobW - 1, knobH - 1);
            } else {
                g2.setColor(new Color(0, 0, 0, 35));
                g2.fillOval(knobX, knobY + 1, knobD, knobD);
                g2.setColor(knob);
                g2.fillOval(knobX, knobY, knobD, knobD);
            }
            g2.dispose();
        }
    }

    /**
     * Simple solid rounded button used where image-skinned modern buttons would
     * hide the text shape or clash with compact screens.
     */
    private static class ColoredPillButton extends JButton {
        private Color baseFill;
        private final Color textColor;
        private static final Color PIXEL_DARK = new Color(18, 18, 18);
        private static final Color PIXEL_SHADOW = new Color(0, 0, 0, 86);
        private static final Color PIXEL_HIGHLIGHT = new Color(255, 255, 255, 74);

        private ColoredPillButton(String text, Color baseFill, Color textColor) {
            super(text);
            this.baseFill = baseFill;
            this.textColor = textColor;
            setFont(getFont().deriveFont(Font.BOLD, 13f));
            setBackground(baseFill);
            setForeground(textColor);
            setFocusPainted(false);
            setBorderPainted(false);
            setContentAreaFilled(false);
            setOpaque(false);
            setRolloverEnabled(true);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setBorder(BorderFactory.createEmptyBorder(9, 18, 9, 18));
            putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
            putClientProperty("msc.pillStyle", Boolean.TRUE);
            // This button is transparent. Repaint its parent as the rollover state
            // changes so translucent Metro surfaces behind it are restored first.
            getModel().addChangeListener(e -> {
                Container parent = getParent();
                if (parent != null) {
                    parent.repaint(getX(), getY(), getWidth(), getHeight());
                }
            });
        }

        private void setBaseFill(Color baseFill) {
            this.baseFill = baseFill;
            setBackground(baseFill);
            repaint();
        }

        @Override
        public void updateUI() {
            setUI(new javax.swing.plaf.basic.BasicButtonUI());
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            int x = 3;
            int y = 3;
            int w = Math.max(1, getWidth() - 6);
            int h = Math.max(1, getHeight() - 7);
            ButtonModel model = getModel();
            Color fill = model.isPressed() && model.isArmed()
                    ? darken(baseFill, 28)
                    : model.isRollover() ? brighten(baseFill, 20) : baseFill;
            if (!isEnabled()) {
                fill = new Color(120, 126, 136);
            }

            int pressOffset = model.isPressed() && model.isArmed() ? 2 : 0;
            y += pressOffset;
            g2.setColor(PIXEL_SHADOW);
            g2.fillRect(x + 2, y + 3, w, h);
            g2.setColor(fill);
            g2.fillRect(x, y, w, h);
            g2.setColor(PIXEL_DARK);
            g2.drawRect(x, y, w - 1, h - 1);
            g2.drawRect(x + 1, y + 1, Math.max(1, w - 3), Math.max(1, h - 3));
            g2.setColor(PIXEL_HIGHLIGHT);
            g2.drawLine(x + 2, y + 2, x + w - 3, y + 2);
            g2.drawLine(x + 2, y + 2, x + 2, y + h - 3);
            g2.setColor(new Color(0, 0, 0, model.isRollover() ? 92 : 66));
            g2.drawLine(x + 2, y + h - 3, x + w - 3, y + h - 3);
            g2.drawLine(x + w - 3, y + 2, x + w - 3, y + h - 3);
            if (model.isRollover() && isEnabled()) {
                g2.setColor(new Color(255, 255, 255, 28));
                g2.fillRect(x + 3, y + 3, Math.max(1, w - 6), Math.max(1, h / 2 - 3));
            }
            paintActionIcon(g2, x, y, h);
            paintButtonText(g2);
            g2.dispose();
        }

        @Override
        public boolean contains(int x, int y) {
            return x >= 0 && y >= 0 && x < getWidth() && y < getHeight();
        }

        private void paintButtonText(Graphics2D g2) {
            String text = getText();
            if (text == null || text.isBlank()) {
                return;
            }
            Insets insets = getInsets();
            FontMetrics fm = g2.getFontMetrics(getFont());
            boolean hasActionIcon = getClientProperty("msc.actionIcon") instanceof String;
            int iconSpace = hasActionIcon ? 24 : 0;
            int availableW = Math.max(0, getWidth() - insets.left - insets.right - iconSpace);
            String drawn = text;
            while (drawn.length() > 1 && fm.stringWidth(drawn) > availableW) {
                drawn = drawn.substring(0, drawn.length() - 1).trim();
            }
            if (!drawn.equals(text) && drawn.length() > 1) {
                drawn = drawn.substring(0, Math.max(1, drawn.length() - 1)).trim() + "…";
            }
            int x = insets.left + iconSpace + Math.max(0, availableW - fm.stringWidth(drawn)) / 2;
            int y = (getHeight() - fm.getHeight()) / 2 + fm.getAscent();
            g2.setFont(getFont());
            g2.setColor(isEnabled() ? textColor : new Color(235, 238, 242, 175));
            g2.drawString(drawn, x, y);
        }

        private void paintActionIcon(Graphics2D g2, int buttonX, int buttonY, int buttonH) {
            Object icon = getClientProperty("msc.actionIcon");
            if (!(icon instanceof String iconName)) {
                return;
            }
            int size = 16;
            int cx = buttonX + getInsets().left + 7;
            int cy = buttonY + buttonH / 2;
            g2.setColor(Color.WHITE);
            if ("stop".equals(iconName)) {
                g2.setStroke(new BasicStroke(2f));
                g2.drawOval(cx - size / 2, cy - size / 2, size, size);
                int square = 7;
                g2.fillRect(cx - square / 2, cy - square / 2, square, square);
            } else {
                int h = 13;
                int w = 11;
                int[] xs = {cx - w / 2, cx - w / 2, cx + w / 2};
                int[] ys = {cy - h / 2, cy + h / 2, cy};
                g2.fillPolygon(xs, ys, 3);
            }
        }

        private static Color brighten(Color c, int amount) {
            return new Color(Math.min(255, c.getRed() + amount),
                    Math.min(255, c.getGreen() + amount),
                    Math.min(255, c.getBlue() + amount));
        }

        private static Color darken(Color c, int amount) {
            return new Color(Math.max(0, c.getRed() - amount),
                    Math.max(0, c.getGreen() - amount),
                    Math.max(0, c.getBlue() - amount));
        }
    }

    private static final class RoundLaunchButton extends JButton {
        private Color baseFill = new Color(50, 185, 90);

        private RoundLaunchButton() {
            setText("");
            setPreferredSize(new Dimension(42, 42));
            setMinimumSize(new Dimension(42, 42));
            setMaximumSize(new Dimension(42, 42));
            setFocusPainted(false);
            setBorderPainted(false);
            setContentAreaFilled(false);
            setOpaque(false);
            setRolloverEnabled(true);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setBorder(BorderFactory.createEmptyBorder());
            putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
        }

        private void setBaseFill(Color baseFill) {
            this.baseFill = baseFill;
            repaint();
        }

        @Override
        public void updateUI() {
            setUI(new javax.swing.plaf.basic.BasicButtonUI());
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int size = Math.min(getWidth(), getHeight()) - 6;
            int x = (getWidth() - size) / 2;
            int y = (getHeight() - size) / 2;
            ButtonModel model = getModel();
            Color fill = model.isPressed() && model.isArmed()
                    ? ColoredPillButton.darken(baseFill, 28)
                    : model.isRollover() ? ColoredPillButton.brighten(baseFill, 18) : baseFill;
            if (!isEnabled()) {
                fill = new Color(120, 126, 136);
            }

            g2.setColor(new Color(0, 0, 0, 88));
            if (LinuxUiSupport.isLinux()) g2.fillRect(x + 2, y + 3, size, size);
            else g2.fillOval(x + 2, y + 3, size, size);
            g2.setColor(fill);
            if (LinuxUiSupport.isLinux()) g2.fillRect(x, y, size, size);
            else g2.fillOval(x, y, size, size);
            g2.setColor(new Color(255, 255, 255, model.isRollover() ? 80 : 50));
            if (LinuxUiSupport.isLinux()) g2.drawRect(x + 1, y + 1, size - 3, size - 3);
            else g2.drawOval(x + 1, y + 1, size - 3, size - 3);

            int cx = getWidth() / 2;
            int cy = getHeight() / 2;
            g2.setColor(Color.WHITE);
            Object icon = getClientProperty("msc.actionIcon");
            if ("stop".equals(icon)) {
                float ccx = getWidth() / 2f;
                float ccy = getHeight() / 2f;
                float circle = 20f;
                g2.setStroke(new BasicStroke(2.2f));
                g2.draw(new java.awt.geom.Ellipse2D.Float(ccx - circle / 2f, ccy - circle / 2f, circle, circle));
                float square = 6.5f;
                g2.fill(new java.awt.geom.Rectangle2D.Float(ccx - square / 2f, ccy - square / 2f, square, square));
            } else {
                int h = 16;
                int w = 13;
                int[] xs = {cx - w / 2 + 1, cx - w / 2 + 1, cx + w / 2 + 2};
                int[] ys = {cy - h / 2, cy + h / 2, cy};
                g2.fillPolygon(xs, ys, 3);
            }
            g2.dispose();
        }

        @Override
        public boolean contains(int x, int y) {
            if (LinuxUiSupport.isLinux()) {
                return x >= 0 && y >= 0 && x < getWidth() && y < getHeight();
            }
            int size = Math.min(getWidth(), getHeight()) - 6;
            int cx = getWidth() / 2;
            int cy = getHeight() / 2;
            int r = size / 2;
            int dx = x - cx;
            int dy = y - cy;
            return dx * dx + dy * dy <= r * r;
        }
    }

    private static final class PixelXButton extends JButton {
        private PixelXButton() {
            setText("");
            setPreferredSize(new Dimension(24, 24));
            setMinimumSize(new Dimension(24, 24));
            setMaximumSize(new Dimension(24, 24));
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
            setRolloverEnabled(true);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setBorder(BorderFactory.createEmptyBorder());
            putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
        }

        @Override
        public void updateUI() {
            setUI(new javax.swing.plaf.basic.BasicButtonUI());
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            if (getModel().isRollover()) {
                g2.setColor(MR_LIGHT_ACTIVE ? new Color(0, 0, 0, 22) : new Color(255, 255, 255, 18));
                g2.fillRect(3, 3, getWidth() - 6, getHeight() - 6);
            }
            String[] rows = {
                    "100000001",
                    "010000010",
                    "001000100",
                    "000101000",
                    "000010000",
                    "000101000",
                    "001000100",
                    "010000010",
                    "100000001"
            };
            int pixel = 1;
            int startX = (getWidth() - rows[0].length() * pixel) / 2;
            int startY = (getHeight() - rows.length * pixel) / 2;
            Color color = MR_LIGHT_ACTIVE ? new Color(80, 84, 94) : new Color(178, 182, 192);
            if (getModel().isPressed() && getModel().isArmed()) {
                color = MR_LIGHT_ACTIVE ? new Color(40, 44, 52) : new Color(230, 234, 242);
            } else if (getModel().isRollover()) {
                color = MR_LIGHT_ACTIVE ? new Color(45, 50, 60) : new Color(215, 220, 230);
            }
            g2.setColor(color);
            for (int row = 0; row < rows.length; row++) {
                for (int col = 0; col < rows[row].length(); col++) {
                    if (rows[row].charAt(col) == '1') {
                        g2.fillRect(startX + col * pixel, startY + row * pixel, pixel, pixel);
                    }
                }
            }
            g2.dispose();
        }
    }

    /**
     * Flat pill-shaped action button (used for "Create new instance",
     * "Create instance", "Back", etc.) with clean hover/press feedback that
     * doesn't rely on the platform button UI, so it always looks consistent.
     */
    private static class PillActionButton extends JButton {
        private final boolean primary;

        private PillActionButton(String text, boolean primary) {
            super(text);
            this.primary = primary;
            setFont(getFont().deriveFont(primary ? Font.BOLD : Font.PLAIN, 13f));
            setFocusPainted(false);
            setBorderPainted(false);
            setContentAreaFilled(false);
            setOpaque(false);
            setRolloverEnabled(true);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setForeground(primary ? new Color(18, 20, 22) : MR_TEXT);
            setBorder(BorderFactory.createEmptyBorder(9, 18, 9, 18));
            putClientProperty("msc.keepDefaultStyle", Boolean.TRUE);
        }

        @Override
        public void updateUI() {
            setUI(new javax.swing.plaf.basic.BasicButtonUI());
            setOpaque(false);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            // If a custom PNG icon has been attached via modernIcon(), let the
            // icon fully represent the button: skip drawing the default pill
            // background/border entirely (otherwise it shows through/around
            // the image, especially on hover) and just paint the icon itself.
            if (getIcon() != null) {
                Graphics2D iconG = (Graphics2D) g.create();
                iconG.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                int arc = Math.max(8, getHeight());
                iconG.setClip(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
                super.paintComponent(iconG);
                iconG.dispose();
                return;
            }
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int arc = LinuxUiSupport.buttonArc(getHeight());
            ButtonModel model = getModel();
            Color fill;
            if (primary) {
                fill = model.isPressed() ? MR_ACCENT.darker() : (model.isRollover() ? brighten(MR_ACCENT, 14) : MR_ACCENT);
            } else {
                fill = model.isPressed() ? new Color(20, 22, 26) : (model.isRollover() ? new Color(50, 53, 60) : MR_CARD);
            }
            // Clip everything (including the text painted by super) to the pill shape
            g2.setClip(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
            g2.setColor(fill);
            g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
            if (!primary) {
                g2.setColor(MR_BORDER);
                g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f, arc, arc));
            }
            super.paintComponent(g2);
            g2.dispose();
        }

        private static Color brighten(Color c, int amt) {
            return new Color(Math.min(255, c.getRed() + amt), Math.min(255, c.getGreen() + amt), Math.min(255, c.getBlue() + amt));
        }
    }

