    /** Rebuilds the singleplayer worlds list inside {@code listPanel} from the saves/ folder. */
    private void populateWorldsList(JPanel listPanel, Path saves, InstalledVersionEntry entry) {
        listPanel.removeAll();
        java.util.List<Path> worlds = new java.util.ArrayList<>();
        if (Files.isDirectory(saves)) {
            try (var stream = Files.list(saves)) {
                stream.filter(Files::isDirectory)
                        .filter(p -> Files.isRegularFile(p.resolve("level.dat")))
                        .sorted((a, b) -> Long.compare(lastModifiedMillisQuiet(b), lastModifiedMillisQuiet(a)))
                        .forEach(worlds::add);
            } catch (IOException ignored) {
            }
        }
        if (worlds.isEmpty()) {
            JLabel empty = new JLabel(nr("No worlds found", "Миры не найдены"), JLabel.CENTER);
            empty.setForeground(MR_TEXT_DIM);
            empty.setFont(empty.getFont().deriveFont(Font.PLAIN, 13f));
            empty.setAlignmentX(Component.CENTER_ALIGNMENT);
            empty.setBorder(BorderFactory.createEmptyBorder(24, 0, 0, 0));
            listPanel.add(empty);
        } else {
            for (Path world : worlds) {
                listPanel.add(buildWorldRow(world, entry));
                listPanel.add(Box.createVerticalStrut(6));
            }
        }
        listPanel.revalidate();
        listPanel.repaint();
    }

    private long lastModifiedMillisQuiet(Path p) {
        try {
            return Files.getLastModifiedTime(p).toMillis();
        } catch (IOException e) {
            return 0L;
        }
    }

    /** Builds a single world row with a quick-launch "Играть" button (vanilla Quick Play). */
    private JPanel buildWorldRow(Path worldDir, InstalledVersionEntry entry) {
        String worldName = worldDir.getFileName().toString();

        JPanel row = glassPanel(new BorderLayout(10, 0), MR_CARD, MR_BORDER);
        row.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(MR_BORDER, 1),
                BorderFactory.createEmptyBorder(8, 12, 8, 10)));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 54));

        JPanel info = transparentPanel(new BorderLayout(0, 2));
        JLabel nameLbl = new JLabel("\uD83C\uDF0D  " + worldName);
        nameLbl.setFont(nameLbl.getFont().deriveFont(Font.BOLD, 13f));
        nameLbl.setForeground(MR_TEXT);
        JLabel subLbl = new JLabel(nr("Played ", "Играли ") + formatRelativeTime(lastModifiedMillisQuiet(worldDir)));
        subLbl.setFont(subLbl.getFont().deriveFont(Font.PLAIN, 11f));
        subLbl.setForeground(MR_TEXT_DIM);
        info.add(nameLbl, BorderLayout.NORTH);
        info.add(subLbl, BorderLayout.SOUTH);
        row.add(info, BorderLayout.CENTER);

        JButton playBtn = new ColoredPillButton("▶  " + t("tab.play"), new Color(50, 185, 90), Color.WHITE);
        playBtn.setToolTipText(nr("Launch directly into this world", "Запустить сразу в этот мир"));
        playBtn.addActionListener(e -> {
            hideOverlay();
            selectInstalledVersion(entry.id());
            if (account.type() == Account.Type.OFFLINE || !usernameField.getText().trim().equals(account.username())) {
                account = Account.offline(usernameField.getText().trim().isEmpty() ? "Player" : usernameField.getText().trim());
                AccountStore.save(account);
                refreshAccountMenu();
                updateAccountLabel();
            }
            runTask(tf("task.launch", entry.id()), () -> {
                modContentInstaller.repairInstalledModpack(entry.id(), settings, uiProgress());
                String launchVersion = modLoaderUpdateService.updateBeforeLaunch(entry.id(), settings, uiProgress());
                Process process = launcher.launchWorld(launchVersion, settings, account, uiProgress(), worldName);
                log(t("log.minecraftStarted"));
                return new LaunchResult(process, launchVersion);
            }, result -> {
                if (result instanceof LaunchResult launchResult) {
                    refreshInstalledVersions();
                    registerRunningMinecraft(launchResult.process(), launchResult.profileId());
                    hideLauncherUntilMinecraftExit(launchResult.process(), launchResult.profileId());
                }
            });
        });

        JPanel right = transparentPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        right.add(playBtn);
        row.add(right, BorderLayout.EAST);
        return row;
    }

    /** Formats a past timestamp as a short Russian relative-time string ("3 часа назад"). */
    private String formatRelativeTime(long millis) {
        if (millis <= 0) return nr("long ago", "давно");
        long diff = System.currentTimeMillis() - millis;
        long seconds = diff / 1000, minutes = seconds / 60, hours = minutes / 60, days = hours / 24;
        if (days > 0) return days + (language() == AppLanguage.RU ? (days == 1 ? " день назад" : days < 5 ? " дня назад" : " дней назад") : (days == 1 ? " day ago" : " days ago"));
        if (hours > 0) return hours + (language() == AppLanguage.RU ? (hours == 1 ? " час назад" : hours < 5 ? " часа назад" : " часов назад") : (hours == 1 ? " hour ago" : " hours ago"));
        if (minutes > 0) return minutes + (language() == AppLanguage.RU ? (minutes == 1 ? " минуту назад" : minutes < 5 ? " минуты назад" : " минут назад") : (minutes == 1 ? " minute ago" : " minutes ago"));
        return nr("just now", "только что");
    }

    private JPanel buildInstanceLogsPanel() {
        JPanel panel = transparentPanel(new BorderLayout(0, 8));
        JTextArea logCopy = new JTextArea(logArea.getText());
        logCopy.setEditable(false);
        logCopy.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 11));
        logCopy.setBackground(new Color(16, 18, 22));
        logCopy.setForeground(new Color(180, 195, 210));
        logCopy.setCaretColor(MR_TEXT);
        JScrollPane sp = new JScrollPane(logCopy);
        sp.setOpaque(false);
        sp.getViewport().setOpaque(false);
        sp.setBorder(BorderFactory.createLineBorder(MR_BORDER));
        styleScrollBar(sp.getVerticalScrollBar());
        panel.add(sp, BorderLayout.CENTER);
        logArea.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            private void sync() {
                SwingUtilities.invokeLater(() -> {
                    if (!panel.isShowing()) {
                        return;
                    }
                    int oldLength = logCopy.getDocument().getLength();
                    String current = logArea.getText();
                    if (current.length() != oldLength || !current.equals(logCopy.getText())) {
                        logCopy.setText(current);
                        logCopy.setCaretPosition(logCopy.getDocument().getLength());
                    }
                });
            }
            @Override public void insertUpdate(javax.swing.event.DocumentEvent e) { sync(); }
            @Override public void removeUpdate(javax.swing.event.DocumentEvent e) { sync(); }
            @Override public void changedUpdate(javax.swing.event.DocumentEvent e) { sync(); }
        });
        // Full-text copy button: selecting/Ctrl+C inside the JTextArea can be finicky for some
        // users (focus stealing, tiny scroll viewport, etc.) — a single button that puts the
        // whole log straight on the clipboard is a more reliable way to hand it over than asking
        // the person to manually select text in a small embedded log view.
        JPanel copyRow = transparentPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
        PillActionButton copyAll = modernIcon(new PillActionButton(nr("Copy log", "Скопировать лог"), false), "btn_copy_log");
        copyAll.addActionListener(e -> {
            try {
                java.awt.datatransfer.StringSelection selection = new java.awt.datatransfer.StringSelection(logArea.getText());
                java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);
                copyAll.setText(nr("Copied ✓", "Скопировано ✓"));
            } catch (Exception ex) {
                copyAll.setText(nr("Clipboard error", "Ошибка буфера обмена"));
            }
            javax.swing.Timer resetLabel = new javax.swing.Timer(1500, ev -> copyAll.setText(nr("Copy log", "Скопировать лог")));
            resetLabel.setRepeats(false);
            resetLabel.start();
        });
        PillActionButton saveToFile = modernIcon(new PillActionButton(nr("Save log to file", "Сохранить лог в файл"), false), "btn_save_log");
        saveToFile.addActionListener(e -> {
            try {
                Path logFile = LauncherSettings.settingsDirectory().resolve("launcher-log.txt");
                Files.writeString(logFile, logArea.getText(), StandardCharsets.UTF_8);
                DesktopUtil.openDirectory(logFile.getParent());
                saveToFile.setText(nr("Saved: ", "Сохранено: ") + logFile.getFileName());
            } catch (IOException ex) {
                saveToFile.setText(nr("Could not save: ", "Не удалось сохранить: ") + ex.getMessage());
            }
            javax.swing.Timer resetLabel = new javax.swing.Timer(3000, ev -> saveToFile.setText(nr("Save log to file", "Сохранить лог в файл")));
            resetLabel.setRepeats(false);
            resetLabel.start();
        });
        copyRow.add(copyAll);
        copyRow.add(saveToFile);
        panel.add(copyRow, BorderLayout.SOUTH);
        return panel;
    }

    private void installLiveDirectoryRefresh(JComponent owner,
                                             java.util.function.Supplier<Path> directory,
                                             Runnable refresh) {
        final long[] fingerprint = {directoryFingerprint(directory.get())};
        javax.swing.Timer timer = new javax.swing.Timer(900, e -> {
            if (!owner.isShowing()) {
                return;
            }
            long current = directoryFingerprint(directory.get());
            if (current != fingerprint[0]) {
                fingerprint[0] = current;
                refresh.run();
            }
        });
        timer.setCoalesce(true);
        owner.addHierarchyListener(e -> {
            if ((e.getChangeFlags() & java.awt.event.HierarchyEvent.SHOWING_CHANGED) == 0) {
                return;
            }
            if (owner.isShowing()) {
                fingerprint[0] = directoryFingerprint(directory.get());
                timer.start();
            } else {
                timer.stop();
            }
        });
    }

    private long directoryFingerprint(Path directory) {
        if (directory == null || !Files.isDirectory(directory)) {
            return 0L;
        }
        long value = 17L;
        try (var children = Files.list(directory)) {
            for (Path child : children.sorted().toList()) {
                value = value * 31 + child.getFileName().toString().hashCode();
                try {
                    value = value * 31 + Files.getLastModifiedTime(child).toMillis();
                    value = value * 31 + (Files.isDirectory(child) ? 1 : Files.size(child));
                } catch (IOException ignored) {
                    value = value * 31;
                }
            }
        } catch (IOException ignored) {
            return value;
        }
        return value;
    }

    private void startRealtimeFilesystemSync() {
        installedProfilesFingerprint = installedProfilesFingerprint();
        realtimeFilesystemTimer = new javax.swing.Timer(1200, e -> {
            long current = installedProfilesFingerprint();
            if (current == installedProfilesFingerprint) {
                return;
            }
            installedProfilesFingerprint = current;
            if (!launcherBusy) {
                refreshInstalledVersions();
            }
        });
        realtimeFilesystemTimer.setCoalesce(true);
        realtimeFilesystemTimer.start();
    }

    private long installedProfilesFingerprint() {
        long customProfiles = directoryFingerprint(ProfileDirectories.versionsInstallDirectory());
        long vanillaProfiles = directoryFingerprint(settings.gameDirectory().resolve("versions"));
        return customProfiles * 31L + vanillaProfiles;
    }

    /** Self-painted rounded instance tile: stable hover styling, no L&F repaint quirks. */
    private static final class RoundedInstanceCard extends JPanel {
        private boolean hovered;
        private boolean playPressed;
        // Перетаскивание мышью для смены местами версий в библиотеке.
        private boolean dragSource;    // эту карточку сейчас тащат
        private boolean dropHighlight; // над этой карточкой сейчас держат перетаскиваемую

        private RoundedInstanceCard() {
            setOpaque(false);
        }

        private void setHovered(boolean hovered) {
            this.hovered = hovered;
            repaint();
        }

        private boolean isHovered() { return hovered; }

        private void setPlayPressed(boolean pressed) {
            this.playPressed = pressed;
            repaint();
        }

        private boolean isPlayPressed() { return playPressed; }

        private void setDragSource(boolean dragSource) {
            this.dragSource = dragSource;
            repaint();
        }

        private void setDropHighlight(boolean dropHighlight) {
            this.dropHighlight = dropHighlight;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int arc = 12;
            Color fill = hovered ? (MR_LIGHT_ACTIVE ? new Color(235, 237, 245) : new Color(40, 42, 48)) : MR_CARD;
            if (dragSource) {
                // Полупрозрачная карточка-источник, пока её перетаскивают.
                g2.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.45f));
            }
            g2.setColor(fill);
            g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), arc, arc));
            Color border = dropHighlight ? new Color(80, 200, 120) : (hovered ? new Color(50, 120, 220) : MR_BORDER);
            g2.setColor(border);
            g2.setStroke(new java.awt.BasicStroke(dropHighlight ? 2.2f : 1f));
            g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1f, getHeight() - 1f, arc, arc));
            g2.dispose();
            super.paintComponent(g);
        }
    }



