    /**
     * Builds a library list tab. Each entry is {name, description, loaderTag}.
     * loaderTag: FORGE / FABRIC / OPTIFINE / NEOFORGE / QUILT / VANILLA
     */
    private JPanel buildLibraryTab(String[][] entries) {
        // Version choices per loader type
        java.util.Map<String, String[]> versionMap = new java.util.HashMap<>();
        versionMap.put("FORGE",    new String[]{"1.21.4-54.0.34","1.21.1-52.1.14","1.20.1-47.4.20","1.16.5-36.1.0","1.12.2-14.23.5.2847"});
        versionMap.put("OPTIFINE", new String[]{"HD_U_I7","HD_U_I6","HD_U_H9","HD_U_H8"});
        versionMap.put("FABRIC",   new String[]{"0.16.10","0.16.9","0.15.11"});
        versionMap.put("NEOFORGE", new String[]{"21.4.157","21.1.233","21.1.230"});
        versionMap.put("QUILT",    new String[]{"0.26.0","0.25.0"});
        versionMap.put("VANILLA",  new String[]{"1.21.4","1.21.1","1.20.1","1.19.4"});

        java.util.Map<String, Color> tagColors = new java.util.HashMap<>();
        tagColors.put("FORGE",    new Color(180, 90, 30));
        tagColors.put("OPTIFINE", new Color(40, 90, 200));
        tagColors.put("FABRIC",   new Color(50, 160, 80));
        tagColors.put("NEOFORGE", new Color(100, 90, 220));
        tagColors.put("QUILT",    new Color(180, 60, 120));
        tagColors.put("VANILLA",  new Color(100, 140, 80));

        java.util.Map<String, String> tagLabels = new java.util.HashMap<>();
        tagLabels.put("FORGE", "Forge"); tagLabels.put("OPTIFINE", "OptiFine");
        tagLabels.put("FABRIC", "Fabric"); tagLabels.put("NEOFORGE", "NeoForge");
        tagLabels.put("QUILT", "Quilt"); tagLabels.put("VANILLA", "Vanilla");

        JPanel container = new JPanel();
        container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
        container.setBackground(MR_BG);
        container.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

        for (String[] entry : entries) {
            String name = entry[0];
            String desc = entry[1];
            String tag  = entry[2];
            String[] versions = versionMap.getOrDefault(tag, new String[]{"latest"});
            Color tagColor = tagColors.getOrDefault(tag, Color.GRAY);
            String tagLabel = tagLabels.getOrDefault(tag, tag);

            JPanel row = new JPanel(new BorderLayout(10, 0));
            row.setBackground(MR_CARD);
            row.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createMatteBorder(0, 0, 1, 0, MR_BORDER),
                    BorderFactory.createEmptyBorder(10, 12, 10, 12)
            ));
            row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));

            // Left: name + description
            JPanel info = new JPanel(new GridLayout(2, 1, 0, 2));
            info.setOpaque(false);
            JLabel nameLabel = new JLabel(name);
            nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 13f));
            nameLabel.setForeground(TEXT_PRIMARY);
            JLabel descLabel = new JLabel(desc);
            descLabel.setFont(descLabel.getFont().deriveFont(Font.PLAIN, 11f));
            descLabel.setForeground(TEXT_SECONDARY);
            info.add(nameLabel);
            info.add(descLabel);
            row.add(info, BorderLayout.CENTER);

            // Right: tag badge + version combo + install button
            JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
            right.setOpaque(false);

            JLabel tagBadge = new JLabel(tagLabel);
            tagBadge.setFont(tagBadge.getFont().deriveFont(Font.BOLD, 10f));
            tagBadge.setForeground(tagColor);
            tagBadge.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createLineBorder(tagColor, 1),
                    BorderFactory.createEmptyBorder(2, 6, 2, 6)
            ));
            right.add(tagBadge);

            JComboBox<String> verCombo = new JComboBox<>(versions);
            verCombo.setPreferredSize(new Dimension(145, 26));
            verCombo.setBackground(FIELD_BG);
            verCombo.setForeground(TEXT_PRIMARY);
            right.add(verCombo);

            JButton installBtn = modernIcon(new JButton(t("button.install")), "btn_install_version");
            installBtn.setPreferredSize(new Dimension(105, 26));
            styleButton(installBtn);
            installBtn.addActionListener(ev -> {
                String selectedVersion = (String) verCombo.getSelectedItem();
                installBtn.setEnabled(false);
                installBtn.setText("...");
                String installName = name;
                String installTag  = tag;
                runTask(nr("Installing ", "Установка ") + installName, () -> {
                    switch (installTag) {
                        case "FORGE" -> {
                            String base = selectedVersion.contains("-") ? selectedVersion.split("-")[0] : selectedVersion;
                            return forgeService.installLatestForge(base, settings, uiProgress());
                        }
                        case "OPTIFINE" -> {
                            return optiFineService.installStandalone(selectedVersion, settings, uiProgress());
                        }
                        case "FABRIC" -> {
                            // use first MC version that supports this loader
                            String mcVer = "1.21.4";
                            return installer.installFabric(mcVer, settings, uiProgress());
                        }
                        case "NEOFORGE" -> {
                            String base = selectedVersion.contains("-") ? selectedVersion.split("-")[0] : selectedVersion;
                            return neoForgeService.installLatestNeoForge(base, settings, uiProgress());
                        }
                        case "QUILT" -> {
                            return installer.installQuilt("1.21.4", settings, uiProgress());
                        }
                        default -> {
                            installer.installVanilla(selectedVersion, settings, uiProgress());
                            return nr("Installed: ", "Установлено: ") + installName + " " + selectedVersion;
                        }
                    }
                }, result -> {
                    installBtn.setText("✓ " + t("status.ready"));
                    installBtn.setEnabled(true);
                    refreshInstalledVersions();
                });
            });
            right.add(installBtn);

            row.add(right, BorderLayout.EAST);
            container.add(row);
            container.add(Box.createVerticalStrut(2));
        }

        container.add(Box.createVerticalGlue());

        JScrollPane scroll = new JScrollPane(container);
        scroll.setOpaque(false);
        scroll.getViewport().setOpaque(false);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        styleScrollBar(scroll.getVerticalScrollBar());

        JPanel wrapper = new JPanel(new BorderLayout());
        wrapper.setBackground(MR_BG);
        wrapper.add(scroll, BorderLayout.CENTER);
        return wrapper;
    }

    private void ensureModCatalogLoaded() {
        if (modSearchModel.isEmpty()) {
            searchModContent();
            // Opening the Metro Mods tile should stay a clean visual transition.
            // Catalog loading continues in the background, but the global
            // top-of-window download toast is reserved for explicit operations.
            if (isMetroUi()) {
                hideDownloadToast();
            }
        } else {
            updateModPageState();
        }
    }

    private void reloadModCatalogFromFirstPage() {
        modPageIndex = 0;
        hideModSearchSuggestions();
        modSearchFeedbackLabel.setText(" ");
        modLastResultCount = 0;
        modTotalResults = 0;
        modSearchModel.removeAllElements();
        modSearchResults.clearSelection();
        clearSelectedModMedia();
        updateModResultCount();
        updateModPageState();
        updateModSourceState();
        if ((modsScreenPanelRef != null && modsScreenPanelRef.isVisible())
                || SCREEN_MODS.equals(currentScreen())) {
            searchModContent();
        }
    }

    private String currentScreen() {
        if (isMetroUi() && metroSnapWorkspace != null && metroSnapWorkspace.isSnapActive()) {
            if (metroSnapWorkspace.homePickerVisible) {
                return SCREEN_MAIN;
            }
            if (!metroSnapWorkspace.pendingScreen.isBlank()) {
                return metroSnapWorkspace.pendingScreen;
            }
            for (String screen : metroSnapWorkspace.slots) {
                if (screen != null) {
                    return screen;
                }
            }
        }
        for (Component component : screenPanel.getComponents()) {
            if (component.isVisible()) {
                if (component instanceof JComponent jc) {
                    Object screen = jc.getClientProperty("metro.screen");
                    if (screen instanceof String value && !value.isBlank()) {
                        return value;
                    }
                }
                if (component == mainPanel) {
                    return SCREEN_MAIN;
                }
                if (component == settingsPanel) {
                    return SCREEN_SETTINGS;
                }
                if (component == skinsScreenPanelRef) {
                    return SCREEN_SKINS;
                }
                if (component == libraryScreen) {
                    return SCREEN_LIBRARY;
                }
                if (component == backupsScreenPanelRef) {
                    return SCREEN_BACKUPS;
                }
            }
        }
        return "";
    }

    private void changeModPage(int delta) {
        int nextPage = modPageIndex + delta;
        if (nextPage < 0) {
            return;
        }
        int totalPages = modTotalPages();
        if (totalPages > 0 && nextPage >= totalPages) {
            return;
        }
        modPageIndex = nextPage;
        searchModContent();
    }

    private void showMainScreen() {
        updateModernSection(ui("Home", "Главная", "Accueil", "Home", "ホーム", "Acasă", "主页"));
        closeAccountPopup();
        saveSettingsQuietly();
        boolean returningFromExternalMetroScreen = isMetroUi() && !SCREEN_MAIN.equals(currentScreen());
        boolean snapHome = isMetroUi() && metroSnapWorkspace != null
                && metroSnapWorkspace.isSnapActive();
        if (snapHome) {
            metroSnapWorkspace.showHomePicker();
        } else {
            screenLayout.show(screenPanel, SCREEN_MAIN);
            animateInterfaceScreen(SCREEN_MAIN);
        }
        setActiveSidebarButton(0);
        if (isMetroUi() && metroRootPanel != null && metroTilesScreen != null) {
            if (returningFromExternalMetroScreen) {
                slideMetroCardRight(metroRootPanel, metroTilesScreen, "tiles");
                animateMetroTilesReturnIn();
            } else {
                slideMetroCard(metroRootPanel, metroTilesScreen, "tiles", false);
                animateMetroTilesIn();
            }
        }
        updateMetroBackNavButton();
        revalidate();
        repaint();
    }

    private void addVersionFilterListeners() {
        java.awt.event.ItemListener listener = e -> {
            saveSettingsFromForm();
            // Debounce: wait 400 ms after the last toggle change before refreshing,
            // so rapid clicks don't each fire a full network refresh (which caused lag).
            if (versionFilterDebounceTimer != null && versionFilterDebounceTimer.isRunning()) {
                versionFilterDebounceTimer.restart();
            } else {
                versionFilterDebounceTimer = new javax.swing.Timer(400, ev -> refreshApiVersions());
                versionFilterDebounceTimer.setRepeats(false);
                versionFilterDebounceTimer.start();
            }
        };
        showReleaseVersionsCheck.addItemListener(listener);
        showSnapshotVersionsCheck.addItemListener(listener);
        showOldBetaVersionsCheck.addItemListener(listener);
        showOldAlphaVersionsCheck.addItemListener(listener);
        showVanillaVersionsCheck.addItemListener(listener);
        showFabricVersionsCheck.addItemListener(listener);
        showForgeVersionsCheck.addItemListener(listener);
        showNeoForgeVersionsCheck.addItemListener(listener);
        showQuiltVersionsCheck.addItemListener(listener);
        showOptiFineVersionsCheck.addItemListener(listener);
        showForgeOptiFineVersionsCheck.addItemListener(listener);
    }

    private void addSettingsAutoSaveListeners() {
        FocusAdapter saveOnFocusLost = new FocusAdapter() {
            @Override
            public void focusLost(FocusEvent e) {
                saveSettingsQuietly();
            }
        };
        for (JTextField field : List.of(
                usernameField,
                clientIdField,
                microsoftRedirectUriField,
                elyByClientIdField,
                elyByClientSecretField,
                elyByRedirectUriField,
                gameDirField,
                javaPathField,
                wallpaperPathField
        )) {
            field.addFocusListener(saveOnFocusLost);
        }

        minMemorySpinner.addChangeListener(e -> saveSettingsQuietly());
        maxMemorySpinner.addChangeListener(e -> saveSettingsQuietly());
        checkForUpdatesNowButton.addActionListener(e -> GitHubUpdater.checkNow(this, language()));
        hideLauncherAfterLaunchCheck.addItemListener(e -> saveSettingsQuietly());
        modernWallpaperToggle.addItemListener(e -> {
            saveSettingsQuietly();
            applyModernWallpaperVisibility();
        });
        classicTransitionsToggle.addItemListener(e -> saveSettingsQuietly());
        modernTransitionsToggle.addItemListener(e -> saveSettingsQuietly());
        metroTransitionsToggle.addItemListener(e -> saveSettingsQuietly());
        metroAeroToggle.addItemListener(e -> {
            saveSettingsQuietly();
            repaintMetroTheme();
        });
        metroWallpaperToggle.addItemListener(e -> {
            saveSettingsQuietly();
            repaintMetroTheme();
        });
        modernAccentCombo.addActionListener(e -> {
            if (settingsFormReady && !updatingSettingsChoiceText) {
                saveSettingsFromForm();
                applyThemePalette(settings.theme());
                repaint();
            }
        });
        uiModeCombo.addActionListener(e -> {
            if (settingsFormReady && !updatingSettingsChoiceText) {
                saveSettingsFromForm();
            }
        });
        languageCombo.addActionListener(e -> {
            if (!settingsFormReady) {
                return;
            }
            AppLanguage selected = (AppLanguage) languageCombo.getSelectedItem();
            if (selected != null && selected != language()) {
                saveSettingsFromForm();
            }
        });
        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                saveSettingsQuietly();
                discordRpc.stop();
            }
        });
    }

    private void restartFrame() {
        SwingUtilities.invokeLater(() -> {
            Rectangle bounds = getBounds();
            int state = getExtendedState();
            boolean fullscreenShell = LauncherEdition.current().usesFullScreenShell();
            setVisible(false);
            discordRpc.stop();
            dispose();

            LauncherFrame frame = new LauncherFrame();
            if (!fullscreenShell) {
                frame.setBounds(bounds);
                frame.setExtendedState(state);
                frame.setVisible(true);
            } else {
                frame.showFullScreenShell();
            }
        });
    }

    private void updateModSourceState() {
        boolean modrinth = "Modrinth".equals(modSourceCombo.getSelectedItem());
        boolean curseforge = "CurseForge".equals(modSourceCombo.getSelectedItem());
        boolean modpack = "Modpacks".equals(modContentTypeCombo.getSelectedItem());
        boolean noLoader = modpack || "ResourcePacks".equals(modContentTypeCombo.getSelectedItem())
                || "DataPacks".equals(modContentTypeCombo.getSelectedItem())
                || "Shaders".equals(modContentTypeCombo.getSelectedItem());
        boolean curseEnabled = curseforge && curseForgeService != null && curseForgeService.isConfigured();
        modSearchButton.setEnabled(modrinth || curseEnabled);
        installModButton.setEnabled(modrinth || curseEnabled);
        modLoaderCombo.setEnabled(!noLoader);
        updateModPageState();
        if (modrinth) {
            modCatalogSubtitleLabel.setText(t("screen.mods.subtitle.modrinth"));
            if (modSearchModel.isEmpty()) {
                modDetailsArea.setText(t("message.modSearchHint"));
                selectedModTitleLabel.setText(t("label.selectProject"));
                selectedModMetaLabel.setText("Modrinth");
                clearSelectedModMedia();
            }
        } else if (curseforge) {
            modCatalogSubtitleLabel.setText(t("screen.mods.subtitle.curseforge"));
            if (!curseEnabled) {
                modDetailsArea.setText(t("message.curseForgeApi"));
                selectedModTitleLabel.setText("CurseForge");
                selectedModMetaLabel.setText(t("label.apiKeyRequired"));
                clearSelectedModMedia();
            } else if (modSearchModel.isEmpty()) {
                modDetailsArea.setText(t("message.modSearchHint"));
                selectedModTitleLabel.setText("CurseForge");
                selectedModMetaLabel.setText("CurseForge");
                clearSelectedModMedia();
            }
        }
    }

