    /**
     * A card-like panel that renders a "liquid glass" surface (rounded, translucent,
     * with a glossy top highlight and soft inner border) whenever Frutiger Aero is
     * active. In every other UI mode it behaves like a plain opaque panel painted
     * with {@code base}, so swapping a regular JPanel for this one is visually a
     * no-op outside of Frutiger Aero.
     */
    private static class GlassCardPanel extends JPanel {
        private final Color base;
        private final Color borderColor;
        private final int arc;

        private GlassCardPanel(LayoutManager layout, Color base, Color borderColor) {
            this(layout, base, borderColor, 18);
        }

        private GlassCardPanel(LayoutManager layout, Color base, Color borderColor, int arc) {
            super(layout);
            this.base = base;
            this.borderColor = borderColor;
            this.arc = arc;
            setOpaque(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (!FRUTIGER_ACTIVE) {
                g2.setColor(base);
                g2.fillRect(0, 0, w, h);
                g2.dispose();
                super.paintComponent(g);
                return;
            }
            RoundRectangle2D.Float shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, arc, arc);
            // Frosted glass body
            g2.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 175));
            g2.fill(shape);
            // Glossy highlight sweeping across the top third, like light hitting curved glass
            Shape oldClip = g2.getClip();
            g2.clip(shape);
            g2.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 130), 0, h * 0.55f, new Color(255, 255, 255, 0)));
            g2.fillRect(0, 0, w, (int) (h * 0.6f));
            // Subtle bottom tint for depth
            g2.setPaint(new GradientPaint(0, h * 0.7f, new Color(255, 255, 255, 0), 0, h, new Color(255, 255, 255, 40)));
            g2.fillRect(0, (int) (h * 0.7f), w, (int) (h * 0.3f) + 1);
            g2.setClip(oldClip);
            g2.dispose();
            super.paintComponent(g);
        }
    }

    private static final class WallpaperPanel extends JPanel {
        private String wallpaperPath = "";
        private java.nio.file.Path gameDirectory;
        private BufferedImage wallpaper;
        private BufferedImage defaultWallpaper;  // loaded from msc-launcher/default-wallpaper.png if present
        private BufferedImage cachedCoverImage;
        private BufferedImage cachedCoverSource;
        private int cachedCoverPanelWidth = -1;
        private int cachedCoverPanelHeight = -1;
        private boolean flatMode = false;
        private boolean aeroMode = false;
        private boolean modernWallpaperEnabled = true;

        private WallpaperPanel() {
            // This component always paints every pixel of the launcher background.
            // Marking it transparent made Swing start some descendant repaints at a
            // transparent card/tab instead, so old hover/pressed pixels could remain
            // visible through buttons. Keep one opaque painting origin for the whole
            // launcher: every button repaint now restores the wallpaper and panels
            // underneath before drawing the button's new state.
            setOpaque(true);
            setDoubleBuffered(true);
        }

        @Override
        public boolean isPaintingOrigin() {
            return true;
        }

        private void setFlatMode(boolean flatMode) {
            this.flatMode = flatMode;
            repaint();
        }

        private void setAeroMode(boolean aeroMode) {
            this.aeroMode = aeroMode;
            repaint();
        }

        /** Toggles whether the wallpaper image shows through behind Modern UI's flat screens
         *  (Home, Library, Backups, etc.) instead of the plain solid background. */
        private void setModernWallpaperEnabled(boolean modernWallpaperEnabled) {
            this.modernWallpaperEnabled = modernWallpaperEnabled;
            repaint();
        }

        /** Must be called before {@link #setWallpaperPath} so auto-discovery works. */
        private void setGameDirectory(java.nio.file.Path gameDirectory) {
            this.gameDirectory = gameDirectory;
            // Try to load a custom default backdrop from the assets folder.
            this.defaultWallpaper = LauncherAssets.readImage(
                    gameDirectory,
                    "wallpaper.png",
                    "wallpaper.jpg",
                    "default-wallpaper.png",
                    "default-wallpaper.jpg",
                    "default-background.png",
                    "default-background.jpg"
            );
            clearCoverCache();
        }

        private void setWallpaperPath(String path) {
            String normalized = path == null ? "" : path.trim();
            if (normalized.equals(wallpaperPath)) {
                return;
            }
            wallpaperPath = normalized;
            wallpaper = loadWallpaper(normalized);
            clearCoverCache();
            repaint();
        }

        private BufferedImage loadWallpaper(String path) {
            // If a concrete path was provided, use it directly.
            if (!path.isBlank()) {
                File file = new File(path);
                if (file.isFile()) {
                    try {
                        return ImageIO.read(file);
                    } catch (IOException ignored) {
                        // fall through to auto-discovery
                    }
                }
            }
            // Auto-discover wallpaper.png from the standard asset directories
            // (msc-launcher/ folder next to the JAR, next to the game directory, etc.)
            // so users can simply drop wallpaper.png there without configuring a path.
            return LauncherAssets.readImage(
                    gameDirectory,
                    "wallpaper.png",
                    "wallpaper.jpg",
                    "background.png",
                    "background.jpg"
            );
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(WINDOW_BG);
            g2.fillRect(0, 0, getWidth(), getHeight());

            if (flatMode) {
                if (aeroMode) {
                    GradientPaint sky = new GradientPaint(0, 0, new Color(150, 210, 240), 0, getHeight(), new Color(225, 245, 250));
                    g2.setPaint(sky);
                    g2.fillRect(0, 0, getWidth(), getHeight());
                    g2.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 90), 0, getHeight() / 2, new Color(255, 255, 255, 0)));
                    g2.fillRect(0, 0, getWidth(), getHeight() / 2);
                } else if (modernWallpaperEnabled) {
                    // Show the wallpaper (custom path, or the bundled Resources/wallpaper.png) behind
                    // Modern UI's flat screens too, dimmed so the light card text stays readable.
                    BufferedImage img = wallpaper != null ? wallpaper : defaultWallpaper;
                    if (img != null) {
                        drawCoverImage(g2, img);
                        g2.setColor(new Color(12, 13, 16, 165));
                        g2.fillRect(0, 0, getWidth(), getHeight());
                    }
                }
                g2.dispose();
                return;
            }

            if (wallpaper != null) {
                drawCoverImage(g2, wallpaper);
            } else if (defaultWallpaper != null) {
                drawCoverImage(g2, defaultWallpaper);
            } else {
                paintDefaultBackdrop(g2);
            }
            g2.dispose();
        }

        /** Draws {@code img} scaled to cover the panel (center-crop). */
        private void drawCoverImage(Graphics2D g2, BufferedImage img) {
            int panelWidth = getWidth();
            int panelHeight = getHeight();
            if (panelWidth <= 0 || panelHeight <= 0) {
                return;
            }
            if (cachedCoverImage == null
                    || cachedCoverSource != img
                    || cachedCoverPanelWidth != panelWidth
                    || cachedCoverPanelHeight != panelHeight) {
                cachedCoverImage = buildCoverImage(img, panelWidth, panelHeight);
                cachedCoverSource = img;
                cachedCoverPanelWidth = panelWidth;
                cachedCoverPanelHeight = panelHeight;
            }
            g2.drawImage(cachedCoverImage, 0, 0, null);
        }

        private BufferedImage buildCoverImage(BufferedImage img, int panelWidth, int panelHeight) {
            double scale = Math.max(
                    panelWidth / (double) img.getWidth(),
                    panelHeight / (double) img.getHeight()
            );
            int width = (int) Math.ceil(img.getWidth() * scale);
            int height = (int) Math.ceil(img.getHeight() * scale);
            int x = (panelWidth - width) / 2;
            int y = (panelHeight - height) / 2;
            BufferedImage scaled = new BufferedImage(panelWidth, panelHeight, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = scaled.createGraphics();
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(img, x, y, width, height, null);
            g.dispose();
            return scaled;
        }

        private void clearCoverCache() {
            cachedCoverImage = null;
            cachedCoverSource = null;
            cachedCoverPanelWidth = -1;
            cachedCoverPanelHeight = -1;
        }

        private void paintDefaultBackdrop(Graphics2D g2) {
            int h = getHeight(), w = getWidth();
            int horizon = Math.max(220, (int) (h * 0.48));
            boolean dark = WINDOW_BG.getRed() < 80;

            // Sky gradient
            if (dark) {
                java.awt.GradientPaint skyGrad = new java.awt.GradientPaint(
                        0, 0, new Color(13, 21, 35),
                        0, horizon, new Color(22, 38, 62));
                g2.setPaint(skyGrad);
            } else {
                java.awt.GradientPaint skyGrad = new java.awt.GradientPaint(
                        0, 0, new Color(92, 160, 214),
                        0, horizon, new Color(148, 201, 236));
                g2.setPaint(skyGrad);
            }
            g2.fillRect(0, 0, w, horizon);

            // Stars (dark mode only)
            if (dark) {
                java.util.Random rng = new java.util.Random(42L);
                g2.setColor(new Color(255, 255, 255, 180));
                for (int i = 0; i < 60; i++) {
                    int sx = rng.nextInt(w);
                    int sy = rng.nextInt(horizon - 30);
                    int ss = rng.nextInt(2) + 1;
                    g2.fillRect(sx, sy, ss, ss);
                }
            } else {
                paintCloud(g2, w / 6, 60, 140, 38);
                paintCloud(g2, w / 2 - 40, 110, 110, 30);
                paintCloud(g2, w - 200, 55, 160, 40);
                paintCloud(g2, (int)(w * 0.75), 100, 80, 22);
            }

            // Sun / Moon
            if (dark) {
                g2.setColor(new Color(240, 240, 200, 230));
                g2.fillOval(w - 110, 28, 36, 36);
                // moon crescent shadow
                g2.setColor(new Color(22, 38, 62));
                g2.fillOval(w - 100, 24, 34, 34);
            } else {
                g2.setColor(new Color(255, 230, 80, 220));
                g2.fillOval(w - 130, 20, 56, 56);
                g2.setColor(new Color(255, 242, 140, 100));
                g2.fillOval(w - 142, 8, 80, 80);
            }


            g2.setColor(dark ? new Color(42, 79, 58) : new Color(101, 159, 91));
            g2.fillRoundRect(-60, horizon - 38, getWidth() + 120, 98, 42, 42);
            g2.setColor(dark ? new Color(37, 67, 51) : new Color(83, 139, 77));
            g2.fillRoundRect(90, horizon - 10, getWidth() - 120, 84, 36, 36);

            g2.setColor(dark ? new Color(35, 60, 45) : new Color(118, 176, 91));
            g2.fillRect(0, horizon + 34, getWidth(), getHeight() - horizon - 34);

            int block = 34;
            for (int y = horizon + 34; y < getHeight(); y += block) {
                for (int x = 0; x < getWidth(); x += block) {
                    int shade = Math.floorMod(x / block + y / block, 4);
                    g2.setColor(dark ? switch (shade) {
                        case 0 -> new Color(31, 57, 42);
                        case 1 -> new Color(42, 70, 50);
                        case 2 -> new Color(29, 50, 39);
                        default -> new Color(36, 63, 47);
                    } : switch (shade) {
                        case 0 -> new Color(105, 166, 82);
                        case 1 -> new Color(128, 184, 96);
                        case 2 -> new Color(92, 150, 75);
                        default -> new Color(113, 171, 88);
                    });
                    g2.fillRect(x, y, block, block);
                }
            }

            g2.setColor(dark ? new Color(40, 91, 119) : new Color(82, 146, 184));
            g2.fillRoundRect((int) (getWidth() * 0.68), horizon + 86, 230, 62, 12, 12);
            g2.setColor(dark ? new Color(86, 135, 165, 170) : new Color(139, 204, 226, 170));
            g2.fillRect((int) (getWidth() * 0.68) + 16, horizon + 104, 198, 9);
        }

        private void paintCloud(Graphics2D g2, int x, int y, int width, int height) {
            g2.setColor(new Color(235, 241, 245, 218));
            g2.fillRoundRect(x, y, width, height, height, height);
            g2.fillRoundRect(x + width / 5, y - height / 2, width / 3, height, height, height);
            g2.fillRoundRect(x + width / 2, y - height / 3, width / 3, height, height, height);
        }
    }

    private interface Task {
        Object run() throws Exception;
    }

    private interface TaskSuccess {
        void accept(Object result);
    }

    private interface SupportedVersionsLoader {
        Set<String> load();
    }

    private static Rectangle versionMoreButtonBounds(Rectangle cellBounds) {
        int size = VERSION_ACTION_BUTTON_SIZE;
        int x = cellBounds.x + cellBounds.width - size - 12;
        int y = cellBounds.y + Math.max(0, (cellBounds.height - size) / 2);
        return new Rectangle(x, y, size, size);
    }

    private static Rectangle versionActionButtonBounds(Rectangle cellBounds, VersionListAction action, float progress) {
        progress = Math.max(0f, Math.min(1f, progress));
        int size = VERSION_ACTION_BUTTON_SIZE;
        int gap = VERSION_ACTION_GAP;
        int totalWidth = size * 3 + gap * 2;
        Rectangle moreBounds = versionMoreButtonBounds(cellBounds);
        int targetStartX = moreBounds.x - gap - totalWidth;
        int collapsedX = moreBounds.x;
        int targetX = targetStartX + versionActionOrder(action) * (size + gap);
        int x = collapsedX + Math.round((targetX - collapsedX) * progress);
        int y = cellBounds.y + Math.max(0, (cellBounds.height - size) / 2);
        return new Rectangle(x, y, size, size);
    }

    private static int versionActionOrder(VersionListAction action) {
        return switch (action) {
            case RENAME -> 0;
            case OPEN_FOLDER -> 1;
            case DELETE -> 2;
        };
    }

    private Color versionKindColor(InstallKind kind) {
        return switch (kind) {
            case FORGE -> new Color(232, 116, 68);
            case NEOFORGE -> new Color(241, 141, 54);
            case FABRIC -> new Color(91, 158, 220);
            case QUILT -> new Color(168, 132, 235);
            case OPTIFINE -> new Color(75, 184, 114);
            case FORGE_OPTIFINE -> new Color(236, 174, 71);
            default -> new Color(199, 210, 223);
        };
    }

    private enum VersionListAction {
        RENAME,
        OPEN_FOLDER,
        DELETE
    }

    private final class AvailableVersionList extends JList<VersionInstallOption> {
        private int hoveredIndex = -1;

        AvailableVersionList(ListModel<VersionInstallOption> model) {
            super(model);
            setCellRenderer(new AvailableVersionCellRenderer());
            setFixedCellHeight(VERSION_CELL_HEIGHT);
            setToolTipText("");

            MouseAdapter mouseHandler = new MouseAdapter() {
                @Override
                public void mouseMoved(MouseEvent e) {
                    updateHover(e.getPoint());
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    clearHover();
                }

                @Override
                public void mouseClicked(MouseEvent e) {
                    if (isEnabled() && SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 2) {
                        if (AvailableVersionList.this == classicApiVersionsList) {
                            installClassicSelectedVersion();
                        } else {
                            installButton.doClick();
                        }
                        e.consume();
                    }
                }

                @Override
                public void mousePressed(MouseEvent e) {
                    if (!isEnabled() || !SwingUtilities.isLeftMouseButton(e)) {
                        return;
                    }
                    int index = indexAt(e.getPoint());
                    if (index >= 0) {
                        setSelectedIndex(index);
                        VersionInstallOption option = getModel().getElementAt(index);
                        apiVersions.setSelectedItem(option);
                    }
                }
            };
            addMouseMotionListener(mouseHandler);
            addMouseListener(mouseHandler);
        }

        @Override
        public String getToolTipText(MouseEvent event) {
            int index = indexAt(event.getPoint());
            if (index < 0) {
                return null;
            }
            return optionText(getModel().getElementAt(index));
        }

        private void updateHover(Point point) {
            int oldIndex = hoveredIndex;
            hoveredIndex = indexAt(point);
            if (oldIndex != hoveredIndex) {
                repaintIndex(oldIndex);
                repaintIndex(hoveredIndex);
            }
        }

        private void clearHover() {
            int oldIndex = hoveredIndex;
            hoveredIndex = -1;
            repaintIndex(oldIndex);
        }

        private int indexAt(Point point) {
            int index = locationToIndex(point);
            if (index < 0) {
                return -1;
            }
            Rectangle bounds = getCellBounds(index, index);
            return bounds != null && bounds.contains(point) ? index : -1;
        }

        private void repaintIndex(int index) {
            if (index < 0) {
                return;
            }
            Rectangle bounds = getCellBounds(index, index);
            if (bounds == null) {
                repaint();
            } else {
                repaint(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }
    }

    private final class InstalledVersionList extends JList<InstalledVersionEntry> {
        private int hoveredIndex = -1;
        private int expandedIndex = -1;
        private int animationIndex = -1;
        private float animationProgress;
        private float animationFrom;
        private float animationTo;
        private long animationStartedAt;
        private VersionListAction hoveredAction;
        private final Timer actionAnimationTimer = new Timer(33, e -> tickActionAnimation());

        InstalledVersionList(ListModel<InstalledVersionEntry> model) {
            super(model);
            setCellRenderer(new InstalledVersionCellRenderer());
            setFixedCellHeight(VERSION_CELL_HEIGHT);
            setToolTipText("");

            MouseAdapter mouseHandler = new MouseAdapter() {
                @Override
                public void mouseMoved(MouseEvent e) {
                    updateHover(e.getPoint());
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    clearHover();
                }

                @Override
                public void mouseClicked(MouseEvent e) {
                    handleVersionClick(e);
                }
            };
            addMouseMotionListener(mouseHandler);
            addMouseListener(mouseHandler);
        }

        @Override
        public String getToolTipText(MouseEvent event) {
            int index = indexAt(event.getPoint());
            if (index < 0) {
                return null;
            }
            VersionListAction action = actionAt(index, event.getPoint());
            if (action != null) {
                return switch (action) {
                    case RENAME -> t("action.renameVersion");
                    case OPEN_FOLDER -> t("action.openVersionFolder");
                    case DELETE -> t("action.deleteVersion");
                };
            }
            Rectangle cellBounds = getCellBounds(index, index);
            if (cellBounds != null && versionMoreButtonBounds(cellBounds).contains(event.getPoint())) {
                return t("dialog.versionActions");
            }
            InstalledVersionEntry entry = getModel().getElementAt(index);
            return displayLabelFor(entry.kind(), entry.id());
        }

        private void handleVersionClick(MouseEvent event) {
            if (!isEnabled() || !SwingUtilities.isLeftMouseButton(event)) {
                return;
            }

            int index = indexAt(event.getPoint());
            if (index < 0) {
                collapseActions();
                return;
            }

            setSelectedIndex(index);
            InstalledVersionEntry entry = getModel().getElementAt(index);
            VersionListAction action = actionAt(index, event.getPoint());
            if (action != null) {
                collapseActions();
                performVersionAction(action, entry.id());
                event.consume();
                return;
            }

            Rectangle cellBounds = getCellBounds(index, index);
            boolean moreClicked = cellBounds != null && versionMoreButtonBounds(cellBounds).contains(event.getPoint());
            if (moreClicked) {
                toggleActions(index);
                event.consume();
                return;
            }

            if (event.getClickCount() == 2) {
                if (isModernUi()) {
                    showInstanceDetailsOverlay(entry);
                } else {
                    launchButton.doClick();
                }
                event.consume();
                return;
            }

            if (expandedIndex == index) {
                collapseActions();
            } else if (expandedIndex >= 0) {
                collapseActions();
            }
        }

        private void performVersionAction(VersionListAction action, String versionId) {
            switch (action) {
                case RENAME -> renameVersion(versionId);
                case OPEN_FOLDER -> openVersionFolder(versionId);
                case DELETE -> deleteVersion(versionId);
            }
        }

        private void updateHover(Point point) {
            int oldIndex = hoveredIndex;
            VersionListAction oldAction = hoveredAction;
            hoveredIndex = indexAt(point);
            hoveredAction = hoveredIndex >= 0 ? actionAt(hoveredIndex, point) : null;

            boolean clickable = false;
            if (hoveredIndex >= 0) {
                Rectangle cellBounds = getCellBounds(hoveredIndex, hoveredIndex);
                clickable = hoveredAction != null
                        || (cellBounds != null && versionMoreButtonBounds(cellBounds).contains(point));
            }
            setCursor(Cursor.getPredefinedCursor(clickable ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));

            if (oldIndex != hoveredIndex || oldAction != hoveredAction) {
                repaintIndex(oldIndex);
                repaintIndex(hoveredIndex);
            }
        }

        private void clearHover() {
            int oldIndex = hoveredIndex;
            hoveredIndex = -1;
            hoveredAction = null;
            setCursor(Cursor.getDefaultCursor());
            repaintIndex(oldIndex);
        }

        private int indexAt(Point point) {
            int index = locationToIndex(point);
            if (index < 0) {
                return -1;
            }
            Rectangle bounds = getCellBounds(index, index);
            return bounds != null && bounds.contains(point) ? index : -1;
        }

        private VersionListAction actionAt(int index, Point point) {
            if (index < 0 || actionProgressFor(index) < 0.62f) {
                return null;
            }
            Rectangle cellBounds = getCellBounds(index, index);
            if (cellBounds == null) {
                return null;
            }
            for (VersionListAction action : VersionListAction.values()) {
                Rectangle bounds = versionActionButtonBounds(cellBounds, action, actionProgressFor(index));
                if (bounds.contains(point)) {
                    return action;
                }
            }
            return null;
        }

        private void toggleActions(int index) {
            if (expandedIndex == index && actionProgressFor(index) > 0.5f) {
                animateActions(index, false);
            } else {
                animateActions(index, true);
            }
        }

        private void collapseActions() {
            if (expandedIndex >= 0) {
                animateActions(expandedIndex, false);
            } else if (animationIndex >= 0 && animationProgress > 0f) {
                animateActions(animationIndex, false);
            }
        }

        private void animateActions(int index, boolean open) {
            if (index < 0) {
                return;
            }
            if (open && expandedIndex >= 0 && expandedIndex != index) {
                int oldIndex = expandedIndex;
                expandedIndex = -1;
                if (animationIndex == oldIndex) {
                    animationIndex = -1;
                }
                repaintIndex(oldIndex);
            }

            float currentProgress = actionProgressFor(index);
            animationIndex = index;
            animationFrom = currentProgress;
            animationTo = open ? 1f : 0f;
            if (!LinuxUiSupport.animationsEnabled()) {
                actionAnimationTimer.stop();
                animationProgress = animationTo;
                animationIndex = -1;
                expandedIndex = open ? index : -1;
                repaintIndex(index);
                return;
            }
            animationProgress = animationFrom;
            animationStartedAt = System.nanoTime();
            if (open) {
                expandedIndex = index;
            }
            actionAnimationTimer.restart();
            repaintIndex(index);
        }

        private void tickActionAnimation() {
            if (animationIndex < 0) {
                actionAnimationTimer.stop();
                return;
            }
            int index = animationIndex;
            float elapsed = (System.nanoTime() - animationStartedAt) / 1_000_000f;
            float t = Math.max(0f, Math.min(1f, elapsed / VERSION_ACTION_ANIMATION_MS));
            float eased = t * t * (3f - 2f * t);
            animationProgress = animationFrom + (animationTo - animationFrom) * eased;
            repaintIndex(index);

            if (t >= 1f) {
                actionAnimationTimer.stop();
                animationProgress = animationTo;
                if (animationTo == 0f && expandedIndex == index) {
                    expandedIndex = -1;
                }
                animationIndex = -1;
                repaintIndex(index);
            }
        }

        private float actionProgressFor(int index) {
            if (index == animationIndex) {
                return animationProgress;
            }
            return index == expandedIndex ? 1f : 0f;
        }

        private void repaintIndex(int index) {
            if (index < 0) {
                return;
            }
            Rectangle bounds = getCellBounds(index, index);
            if (bounds == null) {
                repaint();
            } else {
                repaint(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }
    }

    private final class AvailableVersionCellRenderer extends JPanel implements ListCellRenderer<VersionInstallOption> {
        private String displayText = "";
        private InstallKind kind = InstallKind.VANILLA;
        private boolean selected;
        private boolean hovered;
        private boolean enabled = true;

        AvailableVersionCellRenderer() {
            setOpaque(false);
            setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends VersionInstallOption> list,
                                                      VersionInstallOption value,
                                                      int index,
                                                      boolean isSelected,
                                                      boolean cellHasFocus) {
            kind = value == null ? InstallKind.VANILLA : value.kind();
            displayText = value == null ? "" : optionText(value);
            selected = isSelected;
            enabled = list.isEnabled();
            hovered = list instanceof AvailableVersionList versionList && index == versionList.hoveredIndex;
            setFont(list.getFont().deriveFont(Font.PLAIN, 12f));
            return this;
        }

        @Override
        public Dimension getPreferredSize() {
            FontMetrics metrics = getFontMetrics(getFont());
            return new Dimension(metrics.stringWidth(displayText) + 48, VERSION_CELL_HEIGHT);
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (!enabled) {
                g2.setComposite(AlphaComposite.SrcOver.derive(0.48f));
            }

            Rectangle row = new Rectangle(5, 3, Math.max(0, getWidth() - 10), Math.max(0, getHeight() - 6));
            if (selected || hovered) {
                // use a dark translucent overlay so wallpaper shows through but text remains readable
                Color fill = selected ? new Color(0, 0, 0, 140) : new Color(0, 0, 0, 80);
                g2.setColor(fill);
                g2.fillRoundRect(row.x, row.y, row.width, row.height, 9, 9);
                // subtle light outline for contrast
                g2.setColor(new Color(255, 255, 255, selected ? 24 : 12));
                g2.drawRoundRect(row.x, row.y, row.width, row.height, 9, 9);
            }

            g2.setColor(versionKindColor(kind));
            g2.fillRoundRect(row.x + 5, row.y + 8, 4, Math.max(6, row.height - 16), 4, 4);

            g2.setFont(getFont());
            FontMetrics metrics = g2.getFontMetrics();
            int textX = row.x + 17;
            int textY = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
            int textMaxWidth = Math.max(24, getWidth() - textX - 12);
            g2.setColor(selected ? Color.WHITE : TEXT_PRIMARY);
            g2.drawString(clipText(displayText, metrics, textMaxWidth), textX, textY);
            g2.dispose();
        }

        private String clipText(String text, FontMetrics metrics, int maxWidth) {
            if (text == null || text.isEmpty() || metrics.stringWidth(text) <= maxWidth) {
                return text == null ? "" : text;
            }
            String suffix = "...";
            int suffixWidth = metrics.stringWidth(suffix);
            if (suffixWidth >= maxWidth) {
                return suffix;
            }
            int low = 0;
            int high = text.length();
            while (low < high) {
                int mid = (low + high + 1) / 2;
                if (metrics.stringWidth(text.substring(0, mid)) + suffixWidth <= maxWidth) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            return text.substring(0, low) + suffix;
        }
    }

    private final class InstalledVersionCellRenderer extends JPanel implements ListCellRenderer<InstalledVersionEntry> {
        private String displayText = "";
        private InstallKind kind = InstallKind.VANILLA;
        private boolean selected;
        private boolean hovered;
        private boolean enabled = true;
        private float actionProgress;
        private VersionListAction hoveredAction;

        InstalledVersionCellRenderer() {
            setOpaque(false);
            setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends InstalledVersionEntry> list,
                                                      InstalledVersionEntry value,
                                                      int index,
                                                      boolean isSelected,
                                                      boolean cellHasFocus) {
            kind = value == null ? InstallKind.VANILLA : value.kind();
            displayText = value == null ? "" : displayLabelFor(value.kind(), value.id());
            selected = isSelected;
            enabled = list.isEnabled();
            hovered = false;
            actionProgress = 0f;
            hoveredAction = null;
            if (list instanceof InstalledVersionList versionList) {
                hovered = index == versionList.hoveredIndex;
                actionProgress = versionList.actionProgressFor(index);
                hoveredAction = hovered ? versionList.hoveredAction : null;
            }
            setFont(list.getFont().deriveFont(Font.PLAIN, 12f));
            return this;
        }

        @Override
        public Dimension getPreferredSize() {
            FontMetrics metrics = getFontMetrics(getFont());
            return new Dimension(metrics.stringWidth(displayText) + 132, VERSION_CELL_HEIGHT);
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (!enabled) {
                g2.setComposite(AlphaComposite.SrcOver.derive(0.48f));
            }

            Rectangle row = new Rectangle(5, 3, Math.max(0, getWidth() - 10), Math.max(0, getHeight() - 6));
            boolean active = selected || hovered || actionProgress > 0.01f;
            if (active) {
                // dark translucent overlay for active/hovered rows
                Color fill = selected
                        ? new Color(0, 0, 0, 140)
                        : hovered ? new Color(0, 0, 0, 80) : new Color(0, 0, 0, 48);
                g2.setColor(fill);
                g2.fillRoundRect(row.x, row.y, row.width, row.height, 9, 9);
                g2.setColor(new Color(255, 255, 255, selected ? 28 : 12));
                g2.drawRoundRect(row.x, row.y, row.width, row.height, 9, 9);
            }

            g2.setColor(versionKindColor(kind));
            g2.fillRoundRect(row.x + 5, row.y + 8, 4, Math.max(6, row.height - 16), 4, 4);

            g2.setFont(getFont());
            FontMetrics metrics = g2.getFontMetrics();
            int textX = row.x + 17;
            int textY = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
            int baseReserve = (hovered || actionProgress > 0.01f) ? 44 : 12;
            int actionReserve = Math.round((VERSION_ACTION_BUTTON_SIZE * 3 + VERSION_ACTION_GAP * 2 + 12) * actionProgress);
            int textMaxWidth = Math.max(24, getWidth() - textX - baseReserve - actionReserve);
            g2.setColor(selected ? Color.WHITE : new Color(232, 238, 245));
            g2.drawString(clipText(displayText, metrics, textMaxWidth), textX, textY);

            if (actionProgress > 0.02f) {
                Composite oldComposite = g2.getComposite();
                g2.setComposite(AlphaComposite.SrcOver.derive(Math.min(1f, actionProgress)));
                Rectangle cell = new Rectangle(0, 0, getWidth(), getHeight());
                for (VersionListAction action : VersionListAction.values()) {
                    paintActionButton(g2, versionActionButtonBounds(cell, action, actionProgress), action);
                }
                g2.setComposite(oldComposite);
            }

            if (hovered || actionProgress > 0.01f) {
                paintMoreButton(g2, versionMoreButtonBounds(new Rectangle(0, 0, getWidth(), getHeight())));
            }

            g2.dispose();
        }

        private void paintMoreButton(Graphics2D g2, Rectangle bounds) {
            if (actionProgress > 0.2f) {
                Color bg = MR_LIGHT_ACTIVE ? new Color(0, 0, 0, 14) : new Color(255, 255, 255, 18);
                g2.setColor(bg);
                g2.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 8, 8);
            }
            Color dotColor = MR_LIGHT_ACTIVE ? new Color(60, 65, 80, 210) : new Color(232, 238, 245, 210);
            g2.setColor(dotColor);
            int dotY = bounds.y + bounds.height / 2 - 2;
            int dotX = bounds.x + 6;
            for (int i = 0; i < 3; i++) {
                g2.fillOval(dotX + i * 5, dotY, 4, 4);
            }
        }

        private void paintActionButton(Graphics2D g2, Rectangle bounds, VersionListAction action) {
            boolean actionHovered = hoveredAction == action;
            Color fill, border, icon;
            if (MR_LIGHT_ACTIVE) {
                fill   = actionHovered ? new Color(0, 0, 0, 40) : new Color(0, 0, 0, 16);
                border = actionHovered ? new Color(0, 0, 0, 80) : new Color(0, 0, 0, 35);
                icon   = action == VersionListAction.DELETE ? new Color(175, 178, 188) : MR_TEXT_LIGHT;
            } else {
                fill   = actionHovered ? new Color(255, 255, 255, 66) : new Color(255, 255, 255, 30);
                border = actionHovered ? new Color(255, 255, 255, 112) : new Color(255, 255, 255, 48);
                icon   = action == VersionListAction.DELETE
                        ? new Color(178, 182, 192)
                        : new Color(235, 240, 247);
            }
            g2.setColor(fill);
            g2.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 8, 8);
            g2.setColor(border);
            g2.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 8, 8);
            paintActionIcon(g2, bounds, action, icon);
        }

        private void paintActionIcon(Graphics2D g2, Rectangle bounds, VersionListAction action, Color color) {
            Object oldAntialiasing = g2.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
            Object oldStrokeControl = g2.getRenderingHint(RenderingHints.KEY_STROKE_CONTROL);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_DEFAULT);
            switch (action) {
                case RENAME -> paintPixelIcon(g2, bounds, color,
                        "0000001",
                        "0000011",
                        "0000110",
                        "0001100",
                        "0011000",
                        "0110000",
                        "1100000");
                case OPEN_FOLDER -> paintPixelIcon(g2, bounds, color,
                        "0111000",
                        "1111110",
                        "1000010",
                        "1000010",
                        "1000010",
                        "1111110",
                        "0000000");
                case DELETE -> paintPixelIcon(g2, bounds, color, 1,
                        "100000001",
                        "010000010",
                        "001000100",
                        "000101000",
                        "000010000",
                        "000101000",
                        "001000100",
                        "010000010",
                        "100000001");
            }
            g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, oldStrokeControl);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAntialiasing);
        }

        private void paintPixelIcon(Graphics2D g2, Rectangle bounds, Color color, String... rows) {
            paintPixelIcon(g2, bounds, color, 2, rows);
        }

        private void paintPixelIcon(Graphics2D g2, Rectangle bounds, Color color, int pixel, String... rows) {
            int patternW = rows[0].length();
            int patternH = rows.length;
            int startX = bounds.x + (bounds.width - patternW * pixel) / 2;
            int startY = bounds.y + (bounds.height - patternH * pixel) / 2;
            g2.setColor(new Color(0, 0, 0, 80));
            paintPixelPattern(g2, rows, startX + 1, startY + 1, pixel);
            g2.setColor(color);
            paintPixelPattern(g2, rows, startX, startY, pixel);
        }

        private void paintPixelPattern(Graphics2D g2, String[] rows, int startX, int startY, int pixel) {
            for (int row = 0; row < rows.length; row++) {
                String line = rows[row];
                for (int col = 0; col < line.length(); col++) {
                    if (line.charAt(col) == '1') {
                        g2.fillRect(startX + col * pixel, startY + row * pixel, pixel, pixel);
                    }
                }
            }
        }

        private String clipText(String text, FontMetrics metrics, int maxWidth) {
            if (text == null || text.isEmpty() || metrics.stringWidth(text) <= maxWidth) {
                return text == null ? "" : text;
            }
            String suffix = "...";
            int suffixWidth = metrics.stringWidth(suffix);
            if (suffixWidth >= maxWidth) {
                return suffix;
            }
            int low = 0;
            int high = text.length();
            while (low < high) {
                int mid = (low + high + 1) / 2;
                if (metrics.stringWidth(text.substring(0, mid)) + suffixWidth <= maxWidth) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            return text.substring(0, low) + suffix;
        }
    }

    private static final class FullscreenModImagePanel extends JPanel {
        private BufferedImage image;
        private String message = "";

        FullscreenModImagePanel() {
            setOpaque(false);
            setMinimumSize(new Dimension(320, 220));
        }

        void setImage(BufferedImage image, String message) {
            this.image = image;
            this.message = message == null ? "" : message;
            repaint();
        }

        void setMessage(String message) {
            this.image = null;
            this.message = message == null ? "" : message;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int width = getWidth();
            int height = getHeight();
            if (image == null) {
                paintCenteredMessage(g2, width, height, message.isBlank() ? "Loading" : message);
                g2.dispose();
                return;
            }

            int availableWidth = Math.max(1, width - 24);
            int availableHeight = Math.max(1, height - 44);
            double scale = Math.min(availableWidth / (double) image.getWidth(), availableHeight / (double) image.getHeight());
            int drawWidth = Math.max(1, (int) Math.round(image.getWidth() * scale));
            int drawHeight = Math.max(1, (int) Math.round(image.getHeight() * scale));
            int x = (width - drawWidth) / 2;
            int y = (height - drawHeight) / 2;
            g2.drawImage(image, x, y, drawWidth, drawHeight, null);

            if (!message.isBlank()) {
                g2.setFont(getFont().deriveFont(Font.BOLD, 13f));
                FontMetrics metrics = g2.getFontMetrics();
                int labelWidth = metrics.stringWidth(message) + 18;
                int labelHeight = metrics.getHeight() + 8;
                int labelX = (width - labelWidth) / 2;
                int labelY = height - labelHeight - 6;
                g2.setColor(new Color(8, 10, 14, 190));
                g2.fillRoundRect(labelX, labelY, labelWidth, labelHeight, 8, 8);
                g2.setColor(Color.WHITE);
                g2.drawString(message, labelX + 9, labelY + metrics.getAscent() + 4);
            }
            g2.dispose();
        }

        private void paintCenteredMessage(Graphics2D g2, int width, int height, String text) {
            g2.setFont(getFont().deriveFont(Font.BOLD, 15f));
            FontMetrics metrics = g2.getFontMetrics();
            g2.setColor(Color.WHITE);
            g2.drawString(text, (width - metrics.stringWidth(text)) / 2, (height + metrics.getAscent()) / 2);
        }
    }

    private record ModSuggestionPalette(
            Color surfaceTop,
            Color surfaceBottom,
            Color border,
            Color title,
            Color secondary,
            Color selection,
            Color selectionTitle,
            Color selectionSecondary,
            Color accent,
            Color iconBackground,
            Color shadow,
            int arc,
            int rowArc,
            boolean aero) {
    }

    /** Theme-aware rounded body for the mod-search autocomplete popup. */
    private final class ModSuggestionSurface extends JPanel {
        private ModSuggestionSurface() {
            super(new BorderLayout());
            setOpaque(false);
            setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            ModSuggestionPalette palette = modSearchSuggestionPalette();
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            boolean reduced = LinuxUiSupport.reducedEffects();
            int inset = reduced ? 1 : 3;
            int x = inset;
            int y = inset;
            int width = Math.max(0, getWidth() - inset * 2 - 1);
            int height = Math.max(0, getHeight() - inset * 2 - 1);
            int arc = reduced ? Math.min(6, palette.arc()) : palette.arc();
            if (width <= 0 || height <= 0) {
                g2.dispose();
                return;
            }

            if (!reduced && palette.shadow().getAlpha() > 0) {
                g2.setColor(palette.shadow());
                g2.fillRoundRect(x + 1, y + 2, width, height, arc + 2, arc + 2);
            }

            RoundRectangle2D.Float body = new RoundRectangle2D.Float(
                    x, y, width, height, arc, arc);
            g2.setPaint(new GradientPaint(x, y, palette.surfaceTop(),
                    x, y + Math.max(1, height), palette.surfaceBottom()));
            g2.fill(body);

            if (palette.aero() && !reduced) {
                Shape oldClip = g2.getClip();
                g2.clip(body);
                Graphics2D shine = (Graphics2D) g2.create(x, y, width, height);
                paintMetroAeroEffect(shine, width, height, palette.accent());
                shine.dispose();
                g2.setClip(oldClip);
            }

            Shape oldClip = g2.getClip();
            g2.clip(body);
            Color accent = palette.accent();
            g2.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(),
                    reduced ? 150 : 205));
            g2.fillRoundRect(x + 12, y, Math.max(22, width / 5), 2, 2, 2);
            g2.setClip(oldClip);

            g2.setColor(palette.border());
            g2.draw(body);
            g2.dispose();
        }

        @Override
        protected void paintChildren(Graphics g) {
            ModSuggestionPalette palette = modSearchSuggestionPalette();
            Graphics2D g2 = (Graphics2D) g.create();
            int inset = LinuxUiSupport.reducedEffects() ? 1 : 3;
            int width = Math.max(0, getWidth() - inset * 2 - 1);
            int height = Math.max(0, getHeight() - inset * 2 - 1);
            int arc = LinuxUiSupport.reducedEffects() ? Math.min(6, palette.arc()) : palette.arc();
            g2.clip(new RoundRectangle2D.Float(inset, inset, width, height, arc, arc));
            super.paintChildren(g2);
            g2.dispose();
        }
    }

    /** Compact project card used only by the autocomplete popup. */
    private final class ModSearchSuggestionRenderer extends JPanel
            implements ListCellRenderer<ModrinthProject> {
        private final SuggestionIcon icon = new SuggestionIcon();
        private final JLabel title = new JLabel();
        private final JLabel meta = new JLabel();
        private final JLabel badge = new JLabel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                int pillHeight = Math.min(20, Math.max(14, getHeight() - 8));
                int pillY = (getHeight() - pillHeight) / 2;
                g2.setColor(modpack ? new Color(226, 116, 42) : new Color(24, 154, 91));
                g2.fillRoundRect(0, pillY, Math.max(0, getWidth() - 1), pillHeight,
                        pillHeight, pillHeight);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        private boolean selected;
        private boolean modpack;
        private boolean lastRow;

        private ModSearchSuggestionRenderer() {
            super(new BorderLayout(10, 0));
            setOpaque(false);
            setBorder(BorderFactory.createEmptyBorder(5, 12, 5, 12));

            JPanel text = new JPanel(new GridLayout(2, 1, 0, 1));
            text.setOpaque(false);
            text.add(title);
            text.add(meta);

            badge.setOpaque(false);
            badge.setHorizontalAlignment(SwingConstants.CENTER);
            badge.setVerticalAlignment(SwingConstants.CENTER);
            badge.setForeground(Color.WHITE);
            badge.setPreferredSize(new Dimension(48, 24));
            badge.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 5));

            add(icon, BorderLayout.WEST);
            add(text, BorderLayout.CENTER);
            add(badge, BorderLayout.EAST);
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends ModrinthProject> list,
                                                      ModrinthProject value, int index,
                                                      boolean isSelected, boolean cellHasFocus) {
            selected = isSelected;
            modpack = value != null && "modpack".equals(value.projectType());
            lastRow = index == list.getModel().getSize() - 1;
            ModSuggestionPalette palette = modSearchSuggestionPalette();
            Font baseFont = list.getFont();

            String projectTitle = value == null ? "" : value.title();
            title.setText(shortText(projectTitle, 68));
            title.setFont(baseFont.deriveFont(Font.BOLD, isMetroUi() ? 13.5f : 13f));
            title.setForeground(selected ? palette.selectionTitle() : palette.title());

            String author = value == null || value.author() == null ? "" : value.author().trim();
            String downloads = value == null ? "" : formatDownloads(value.downloads()) + " " + t("label.downloads");
            meta.setText(author.isBlank() ? downloads : author + "  •  " + downloads);
            meta.setFont(baseFont.deriveFont(Font.PLAIN, 10.5f));
            meta.setForeground(selected ? palette.selectionSecondary() : palette.secondary());

            badge.setText(modpack ? t("badge.modpack") : t("badge.mod"));
            badge.setFont(baseFont.deriveFont(Font.BOLD, 9f));
            badge.setForeground(Color.WHITE);

            ImageIcon projectIcon = value == null ? null
                    : modImageIcon(value.iconUrl(), 36, 36, modSearchSuggestionList::repaint);
            icon.setFont(baseFont);
            icon.setProject(projectIcon, projectTitle);
            return this;
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            ModSuggestionPalette palette = modSearchSuggestionPalette();
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (selected) {
                g2.setColor(palette.selection());
                g2.fillRoundRect(5, 2, Math.max(0, getWidth() - 10), Math.max(0, getHeight() - 4),
                        palette.rowArc(), palette.rowArc());
                g2.setColor(palette.accent());
                g2.fillRoundRect(5, 10, 3, Math.max(7, getHeight() - 20), 3, 3);
            } else if (!lastRow) {
                Color border = palette.border();
                g2.setColor(new Color(border.getRed(), border.getGreen(), border.getBlue(),
                        Math.min(55, border.getAlpha())));
                g2.drawLine(59, getHeight() - 1, Math.max(59, getWidth() - 13), getHeight() - 1);
            }
            g2.dispose();
        }

        private final class SuggestionIcon extends JComponent {
            private ImageIcon image;
            private String fallback = "?";

            private SuggestionIcon() {
                setOpaque(false);
                setPreferredSize(new Dimension(38, 38));
                setMinimumSize(new Dimension(38, 38));
            }

            private void setProject(ImageIcon projectImage, String projectTitle) {
                image = projectImage;
                String text = projectTitle == null ? "" : projectTitle.trim();
                if (text.isEmpty()) {
                    fallback = "?";
                } else {
                    fallback = new String(Character.toChars(text.codePointAt(0)))
                            .toUpperCase(java.util.Locale.ROOT);
                }
            }

            @Override
            protected void paintComponent(Graphics g) {
                ModSuggestionPalette palette = modSearchSuggestionPalette();
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                int size = Math.min(36, Math.min(getWidth(), getHeight()));
                int x = (getWidth() - size) / 2;
                int y = (getHeight() - size) / 2;
                int arc = isMetroUi() && !metroAeroEnabled() ? 3 : 9;
                RoundRectangle2D.Float shape = new RoundRectangle2D.Float(x, y, size, size, arc, arc);
                g2.setColor(palette.iconBackground());
                g2.fill(shape);
                if (image != null) {
                    Shape oldClip = g2.getClip();
                    g2.clip(shape);
                    image.paintIcon(this, g2, x, y);
                    g2.setClip(oldClip);
                } else {
                    g2.setColor(selected ? palette.selectionTitle() : palette.title());
                    g2.setFont(getFont().deriveFont(Font.BOLD, 15f));
                    FontMetrics metrics = g2.getFontMetrics();
                    int textX = x + (size - metrics.stringWidth(fallback)) / 2;
                    int textY = y + (size - metrics.getHeight()) / 2 + metrics.getAscent();
                    g2.drawString(fallback, textX, textY);
                }
                g2.setColor(palette.border());
                g2.draw(shape);
                g2.dispose();
            }
        }
    }

    private final class ModProjectCardRenderer extends JPanel implements ListCellRenderer<ModrinthProject> {
        private final JLabel badge = new JLabel();
        private final JLabel title = new JLabel();
        private final JLabel meta = new JLabel();
        private final JLabel description = new JLabel();
        private String projectType = "mod";
        private boolean selected;

        ModProjectCardRenderer() {
            super(new BorderLayout(12, 4));
            setBorder(BorderFactory.createEmptyBorder(14, 18, 14, 16));
            setOpaque(false);
            badge.setHorizontalAlignment(SwingConstants.CENTER);
            badge.setForeground(Color.WHITE);
            badge.setFont(badge.getFont().deriveFont(Font.BOLD, 11f));
            badge.setPreferredSize(new Dimension(74, 58));
            JPanel text = transparentPanel(new GridLayout(3, 1, 0, 2));
            title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));
            meta.setFont(meta.getFont().deriveFont(Font.PLAIN, 11f));
            description.setFont(description.getFont().deriveFont(Font.PLAIN, 11f));
            text.add(title);
            text.add(meta);
            text.add(description);
            add(badge, BorderLayout.WEST);
            add(text, BorderLayout.CENTER);
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends ModrinthProject> list, ModrinthProject value,
                                                      int index, boolean isSelected, boolean cellHasFocus) {
            projectType = value.projectType();
            selected = isSelected;
            String type = "modpack".equals(value.projectType()) ? t("badge.modpack") : t("badge.mod");
            ImageIcon icon = modImageIcon(value.iconUrl(), 58, 58, () -> modSearchResults.repaint());
            if (icon == null) {
                badge.setIcon(null);
                badge.setText(type);
            } else {
                badge.setText("");
                badge.setIcon(icon);
            }
            title.setText(value.title());
            String targetVersion = selectedModGameVersion();
            meta.setText(value.author() + " • " + formatDownloads(value.downloads()) + " " + t("label.downloads")
                    + (targetVersion.isBlank() ? "" : " • Minecraft " + targetVersion));
            description.setText(shortText(value.description(), 92));
            title.setForeground(TEXT_PRIMARY);
            meta.setForeground(TEXT_SECONDARY);
            description.setForeground(TEXT_SECONDARY);
            return this;
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            Color fill = MR_LIGHT_ACTIVE
                    ? (selected ? new Color(222, 232, 250) : new Color(244, 245, 248))
                    : (selected ? new Color(45, 53, 64) : new Color(31, 36, 45));
            g2.setColor(fill);
            g2.fillRoundRect(6, 6, getWidth() - 14, getHeight() - 12, 8, 8);
            g2.setColor("modpack".equals(projectType) ? new Color(241, 128, 47) : new Color(27, 173, 100));
            g2.fillRoundRect(6, 6, 6, getHeight() - 12, 6, 6);
            if (selected) {
                g2.setColor(new Color(85, 190, 135));
                g2.drawRoundRect(6, 6, getWidth() - 14, getHeight() - 12, 8, 8);
            }
            g2.dispose();
            super.paintComponent(g);
        }
    }

