    private record SkinTileData(String name, BufferedImage image, boolean slim, String source, String fingerprint) {
        private SkinTileData {
            if (fingerprint == null) {
                fingerprint = computeFingerprint(image, slim);
            }
            if (fingerprint == null) {
                fingerprint = source != null ? source : name + "|" + slim;
            }
        }

        private static String computeFingerprint(BufferedImage img, boolean slim) {
            if (img == null) return null;
            try {
                java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
                javax.imageio.ImageIO.write(img, "png", baos);
                byte[] bytes = baos.toByteArray();
                java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-1");
                md.update(bytes);
                md.update((byte) (slim ? 1 : 0));
                byte[] digest = md.digest();
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) sb.append(String.format("%02x", b));
                return sb.toString();
            } catch (Exception ignored) {
                return null;
            }
        }
    }

